package eu.kanade.tachiyomi.data.tts

/**
 * Лёгкий ручной JSON-разбор/сериализация словарей голосов и интонаций.
 *
 * org.json живёт только внутри Android, а в юнит-тестах app-модуля он не
 * замокан и бросает при любом обращении. Словари должны читаться и в тестах,
 * поэтому формат (массив объектов) разбирается этим хелпером независимо.
 */
internal object VoiceJson {

    /** Клоч JSON-массива: `[{"k":"v"},{"k":"v"}]` → список карт. */
    fun parseObjects(json: String): List<Map<String, String>> {
        val trimmed = json.trim()
        if (!trimmed.startsWith("[") || !trimmed.endsWith("]")) return parseObject(trimmed).let { if (it.isEmpty()) emptyList() else listOf(it) }
        val inner = trimmed.removePrefix("[").removeSuffix("]").trim()
        if (inner.isEmpty()) return emptyList()
        val result = mutableListOf<Map<String, String>>()
        var i = 0
        while (i < inner.length) {
            val objStart = inner.indexOf('{', i)
            if (objStart < 0) break
            var depth = 0
            var inStr = false
            var m = objStart
            var end = objStart
            while (m < inner.length) {
                val c = inner[m]
                if (inStr) {
                    if (c == '\\') { m += 2; continue }
                    if (c == '"') inStr = false
                } else {
                    when (c) {
                        '"' -> inStr = true
                        '{' -> depth++
                        '}' -> {
                            depth--
                            if (depth == 0) { end = m; break }
                        }
                    }
                }
                m++
            }
            val objText = inner.substring(objStart, end + 1)
            result.add(parseObject(objText))
            i = end + 1
        }
        return result
    }

    internal fun parseObject(text: String): Map<String, String> {
        val map = mutableMapOf<String, String>()
        val t = text.trim()
        if (!t.startsWith("{") || !t.endsWith("}")) return map
        val inner = t.removePrefix("{").removeSuffix("}").trim()
        if (inner.isEmpty()) return map
        for (pair in splitTopLevel(inner)) {
            val colon = pair.indexOf(':')
            if (colon <= 0) continue
            val key = unquote(pair.substring(0, colon).trim())
            val value = unquote(pair.substring(colon + 1).trim())
            map[key] = value
        }
        return map
    }

    /** Разбирает массив `["a","b"]` в список токенов. */
    fun parseArrayTokens(s: String): List<String> {
        val t = s.trim()
        if (!t.startsWith("[") || !t.endsWith("]")) {
            // Единичная метка без скобок.
            return if (t.isNotBlank()) listOf(unquote(t)) else emptyList()
        }
        val inner = t.removePrefix("[").removeSuffix("]").trim()
        if (inner.isEmpty()) return emptyList()
        return splitTopLevel(inner).map(::unquote).filter { it.isNotBlank() }
    }

    /** Разбивает содержимое по запятым нулевого уровня (не в строке и не в скобках). */
    internal fun splitTopLevel(text: String): List<String> {
        val result = mutableListOf<String>()
        var depth = 0
        var inStr = false
        var start = 0
        var i = 0
        while (i < text.length) {
            val c = text[i]
            if (inStr) {
                if (c == '\\') { i += 2; continue }
                if (c == '"') inStr = false
            } else {
                when (c) {
                    '"' -> inStr = true
                    '{', '[', '(' -> depth++
                    '}', ']', ')' -> depth--
                    ',' -> if (depth == 0) { result.add(text.substring(start, i)); start = i + 1 }
                }
            }
            i++
        }
        if (start < text.length) result.add(text.substring(start))
        return result
    }

    /** Снимает кавычки со строки, если они есть. */
    internal fun unquote(s: String): String {
        val t = s.trim()
        if (t.length >= 2 && t.first() == '"' && t.last() == '"') {
            return t.substring(1, t.length - 1).replace("\\\"", "\"")
        }
        return t
    }

    /**
     * Значение по ключу из плоского JSON-объекта: `{ "12": [...] }` → `[...]`.
     *
     * Ключи — числа (id книги), поэтому ищем `"<key>"` с двоеточием, а не как
     * обычное поле. null — ключа нет либо значение не строка/массив; вызывающий
     * трактует это как «для этой книги ролей нет».
     */
    fun extractArray(json: String, key: String): String? {
        val t = json.trim()
        if (!t.startsWith("{") || !t.endsWith("}")) return null
        val needle = "\"$key\""
        var i = 0
        while (i < t.length) {
            val at = t.indexOf(needle, i)
            if (at < 0) return null
            var m = at + needle.length
            while (m < t.length && t[m].isWhitespace()) m++
            if (m >= t.length || t[m] != ':') {
                i = at + needle.length
                continue
            }
            m++
            while (m < t.length && t[m].isWhitespace()) m++
            if (m >= t.length) return null
            return when (t[m]) {
                '[' -> {
                    var depth = 0
                    var inStr = false
                    var k = m
                    while (k < t.length) {
                        val c = t[k]
                        if (inStr) {
                            if (c == '\\') { k += 2; continue }
                            if (c == '"') inStr = false
                        } else {
                            when (c) {
                                '"' -> inStr = true
                                '[' -> depth++
                                ']' -> {
                                    depth--
                                    if (depth == 0) return t.substring(m, k + 1)
                                }
                            }
                        }
                        k++
                    }
                    null
                }
                '"' -> {
                    var inStr = false
                    var k = m
                    while (k < t.length) {
                        val c = t[k]
                        if (c == '\\') { k += 2; continue }
                        if (c == '"') { inStr = false; break }
                        inStr = true
                        k++
                    }
                    if (!inStr) null else t.substring(m, k + 1)
                }
                else -> null
            }
        }
        return null
    }

    /**
     * Заменить (или добавить) значение по ключу в плоском JSON-объекте.
     *
     * Пишется вручную и по верхнему уровню: чужие книги и их роли должны
     * пережить перезапись нетронутыми, а org.json здесь недоступен в тестах.
     */
    fun withArray(json: String, key: String, value: String): String {
        val t = json.trim()
        val entry = "\"$key\":$value"
        if (t.isEmpty() || !t.startsWith("{") || !t.endsWith("}")) return "{$entry}"
        val inner = t.removePrefix("{").removeSuffix("}").trim()
        if (inner.isEmpty()) return "{$entry}"
        val out = StringBuilder("{")
        var i = 0
        var replaced = false
        while (i < inner.length) {
            // Один элемент объекта: "key":value — value либо массив, либо строка.
            val keyStart = inner.indexOf('"', i)
            if (keyStart < 0) break
            var k = keyStart + 1
            var inStr = false
            while (k < inner.length) {
                val c = inner[k]
                if (c == '\\') { k += 2; continue }
                if (c == '"') { inStr = false; break }
                k++
            }
            if (inStr) break
            val name = inner.substring(keyStart + 1, k)
            var m = k + 1
            while (m < inner.length && inner[m].isWhitespace()) m++
            if (m >= inner.length || inner[m] != ':') break
            m++
            while (m < inner.length && inner[m].isWhitespace()) m++
            val valueEnd = valueEndOf(inner, m)
            if (valueEnd < 0) break
            val element = inner.substring(keyStart, valueEnd + 1)
            if (out.length > 1) out.append(',')
            if (name == key) {
                out.append(entry)
                replaced = true
            } else {
                out.append(element)
            }
            i = valueEnd + 1
        }
        if (!replaced) out.append(',').append(entry)
        out.append('}')
        return out.toString()
    }

    /** Индекс последнего символа значения, начавшегося в [start], или -1. */
    private fun valueEndOf(text: String, start: Int): Int {
        if (start >= text.length) return -1
        return when (text[start]) {
            '[' -> {
                var depth = 0
                var inStr = false
                var i = start
                while (i < text.length) {
                    val c = text[i]
                    if (inStr) {
                        if (c == '\\') { i += 2; continue }
                        if (c == '"') inStr = false
                    } else {
                        when (c) {
                            '"' -> inStr = true
                            '[' -> depth++
                            ']' -> {
                                depth--
                                if (depth == 0) return i
                            }
                        }
                    }
                    i++
                }
                -1
            }
            '"' -> {
                var i = start + 1
                while (i < text.length) {
                    val c = text[i]
                    if (c == '\\') { i += 2; continue }
                    if (c == '"') return i
                    i++
                }
                -1
            }
            else -> {
                var i = start
                while (i < text.length && text[i] != ',' && !text[i].isWhitespace()) i++
                if (i == start) -1 else i - 1
            }
        }
    }

    fun jsonEscape(s: String): String = buildString(s.length) {
        for (c in s) {
            when (c) {
                '"' -> append("\\\"")
                '\\' -> append("\\\\")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                else -> append(c.coerceAtLeast(' '))
            }
        }
    }
}

package eu.kanade.tachiyomi.data.tts

/**
 * Разметка реплик для озвучки.
 *
 * На экране у каждой реплики есть служебные пометки — номер по порядку
 * чтения, кто говорит, пауза. Их должно быть ВИДНО, но TTS не должен их
 * произносить. Поэтому текст для показа и текст для синтеза расходятся:
 * [strip] снимает разметку перед отправкой в движок.
 *
 * Поддерживаемые пометки:
 *
 * | Запись        | Значение                                   | Читается |
 * |---------------|--------------------------------------------|----------|
 * | `{1}`         | номер реплики в порядке чтения             | нет      |
 * | `{ж}` `{м}`   | пол говорящего (женский / мужской)         | нет      |
 * | `{ж2}`        | вторая женщина в сцене (свой голос)        | нет      |
 * | `{имя:Аки}`   | имя говорящего                             | нет      |
 * | `{пауза}`     | дополнительная пауза перед репликой        | нет      |
 * | `{...}`       | любая другая служебная пометка             | нет      |
 * | `÷`           | разделитель частей реплики (короткая пауза)| нет      |
 *
 * Всё, что не в фигурных скобках, читается как обычно.
 *
 * Имя говорящего живёт в метке `{имя:Аки}`, но авточтение получает текст из
 * OCR, где меток нет. Поэтому есть и обратный путь: [speakerNameFromText]
 * распознаёт подпись персонажа в самой реплике («АКИ: …», «Аки — …»), а
 * [withSpeakerName] прикрепляет метку обратно. Метка снимается в [strip] и на
 * экране, и в синтезе, поэтому имя не начинает произноситься дважды.
 */
object SpeechMarkup {

    // ВАЖНО: фигурные скобки внутри класса символов обязаны быть экранированы.
    // На JVM/ART без экрана работает и без экрана, но ICU-движок регулярок
    // (Itel, Infinix и др. Android 13+) бросает PatternSyntaxException прямо в
    // <clinit>, из-за чего ЛЮБОЕ обращение к TTS роняло приложение
    // (ExceptionInInitializerError).
    private val TAG = Regex("""\{[^\{\}]{0,40}\}""")
    private val DIVIDER = '÷'

    /**
     * Подпись персонажа в начале реплики капсом: «АКИ: …», «АКИ — …»,
     * «КИМ ЧЕН: …». В комиксах и вебтунах имя набрано прописными, а сама
     * реплика — строчными, поэтому такой префикс надёжно отличает имя от
     * обычного слова, даже если OCR не сохранил шрифт.
     */
    private val CAPS_NAME = Regex(
        """^\s*([A-ZА-ЯЁ][A-ZА-ЯЁ'\-]{1,23}(?:\s+[A-ZА-ЯЁ][A-ZА-ЯЁ'\-]{1,23})?)\s*[:—–]\s*(\S.*)$""",
    )

    /**
     * Подпись персонажа с одной заглавной буквы: «Аки: …», «Аки — …».
     * Разрешаем не короче трёх букв: «Нет: я не знаю» и «Помоги — где ты?»
     * превратились бы в «нового персонажа» с собственным голосом.
     */
    private val TITLE_NAME = Regex(
        """^\s*([А-ЯЁA-Z][а-яёa-z]{2,23}(?:\s+[А-ЯЁA-Z][а-яёa-z]{2,23})?)\s*[:—–]\s*(\S.*)$""",
    )

    /**
     * Слова, с которых реплика не может начинаться как с имени. Список
     * короткий и явный: угадывать «имя» по одной заглавной букве нельзя, иначе
     * любая короткая реплика («Он ушёл», «Помоги — где ты?») завела бы себе
     * отдельный голос, а роль из словаря получала бы чужое имя.
     */
    private val NOT_A_NAME = setOf(
        "э", "эй", "ах", "хм", "ну", "о", "а", "и", "у", "не", "нет", "да",
        "ты", "вы", "он", "она", "мы", "все", "вот", "это", "так", "затем",
        "потом", "потому", "поэтому", "значит", "вдруг", "опять", "снова",
        "если", "когда", "чтобы", "ладно", "слушай", "смотри", "боже",
        "господи", "чёрт", "кто", "что", "где", "куда", "зачем", "привет",
        "здравствуй", "пока", "прости", "извини", "спасибо", "глава", "том",
        "помоги", "попробуй", "подожди", "пожалуйста", "иди", "стой", "беги",
        "неужели", "правда", "точно", "хорошо", "отлично", "увы", "помощь",
    )

    /** Допустимые символы имени: без фигурных скобок, иначе метка не распарсится. */
    private val NAME_NOISE = Regex("""[^\p{L}\p{N} ._'’\-]""")

    /** Пол, объявленный разметкой: "female" | "male" | null. */
    fun genderOf(text: String): String? {
        val m = TAG.findAll(text).map { it.value.trim('{', '}').lowercase() }
        m.forEach {
            when {
                it.startsWith("ж") || it.startsWith("f") -> return "female"
                it.startsWith("м") || it.startsWith("m") -> return "male"
            }
        }
        return null
    }

    /**
     * Номер говорящего в сцене: `{ж2}` -> 1 (второй женский слот),
     * `{ж}`/`{м}` -> 0. Нужен, чтобы два персонажа одного пола звучали
     * разными голосами.
     */
    fun speakerSlot(text: String): Int {
        TAG.findAll(text).forEach { match ->
            val body = match.value.trim('{', '}').lowercase()
            if (body.startsWith("ж") || body.startsWith("м") ||
                body.startsWith("f") || body.startsWith("m")
            ) {
                val digits = body.dropWhile { !it.isDigit() }.takeWhile { it.isDigit() }
                if (digits.isNotEmpty()) return (digits.toIntOrNull() ?: 1).minus(1).coerceAtLeast(0)
                return 0
            }
        }
        return 0
    }

    /** Есть ли запрос на дополнительную паузу перед репликой. */
    fun hasPause(text: String): Boolean =
        TAG.findAll(text).any { it.value.trim('{', '}').lowercase().startsWith("пауза") }

    /** Имя говорящего из `{имя:Аки}`, если задано. */
    fun speakerName(text: String): String? {
        TAG.findAll(text).forEach { match ->
            val body = match.value.trim('{', '}')
            val lower = body.lowercase()
            if (lower.startsWith("имя:") || lower.startsWith("name:")) {
                return body.substringAfter(':').trim().ifBlank { null }
            }
        }
        return null
    }

    /**
     * Имя говорящего из САМОГО текста реплики («АКИ: …», «Аки — …»).
     *
     * Зачем это нужно. Метку `{имя:…}` авточтение раньше не собирало, поэтому
     * словарь голосовых ролей не мог сработать на OCR-чтении вообще: оставался
     * «только пол», а настроенные роли молча игнорировались. Второе применение
     * — слот голоса персонажа (см. AutoReadEngine.voiceSlotFor): без имени
     * третью реплику того же героя не отличить от нового персонажа, и голос
     * менялся на каждой реплике.
     */
    fun speakerNameFromText(text: String): String? {
        val line = text.trim()
        if (line.isEmpty()) return null
        CAPS_NAME.find(line)?.let { match ->
            val name = cleanName(match.groupValues[1])
            // Подпись без реплики («АКИ —») — это заголовок панели, а не реплика.
            if (name != null && match.groupValues[2].isNotBlank()) return name
        }
        TITLE_NAME.find(line)?.let { match ->
            val name = cleanName(match.groupValues[1])
            if (name != null) return name
        }
        return null
    }

    /** Имя реплики: из разметки, иначе из текста. Порядок важен — разметка точнее. */
    fun speakerNameOrGuess(text: String): String? =
        speakerName(text) ?: speakerNameFromText(SpeechMarkup.strip(text))

    /**
     * Прикрепляет метку `{имя:…}` к реплике, если имени ещё нет. Само слово
     * имени при этом НЕ вырезается: читатель слышит подпись так же, как видит
     * её на кадре, а служебная метка снимается в [strip] и не произносится.
     */
    fun withSpeakerName(text: String, name: String?): String {
        if (speakerName(text) != null) return text
        val clean = cleanName(name) ?: return text
        return "{имя:$clean} $text"
    }

    /**
     * Имя приводится к безопасному виду: без фигурных скобок (иначе метка
     * распадётся и будет произнесена), без переносов и не длиннее 24 символов
     * (длина метки в [TAG] ограничена 40 символами вместе со скобками).
     */
    private fun cleanName(raw: String?): String? {
        val cleaned = raw.orEmpty()
            .replace('\n', ' ')
            .replace(NAME_NOISE, " ")
            .replace(Regex("""\s+"""), " ")
            .trim()
        if (cleaned.length < 2 || cleaned.lowercase() in NOT_A_NAME) return null
        return cleaned.take(24)
    }

    /**
     * Текст для синтеза: разметка убрана, `÷` заменён на запятую (короткая
     * пауза), лишние пробелы схлопнуты.
     */
    fun strip(text: String): String {
        var out = normalizeSpeechPunctuation(text)
        out = TAG.replace(out, " ")
        out = out.replace(DIVIDER, ',')
        out = out.replace(Regex("[~≈]+"), "") // тильду не озвучивать словом «тильда»
        out = out.replace(Regex("""\s+"""), " ")
        out = out.replace(Regex("""\s+([,.!?;:])"""), "$1")
        out = out.replace(Regex(""",{2,}"""), ",")
        return out.trim().trim(',').trim()
    }

    fun forSpeech(text: String): String {
        var out = text.replace(Regex("\\.{2,}"), "…")
        out = out.replace(Regex("!{2,}"), "!!")
        out = out.replace(Regex("\\?{2,}"), "??")
        out = out.replace(Regex("([!?]{2})[!?]+"), "$1")
        out = out.replace(Regex("(?:;;|:){2,}"), ";")
        out = out.replace(Regex("\\s+([,!?;:…])"), "$1")
        out = out.replace(Regex("(^|\\s)[.,!?;:·•*#|/^_=+<>]+(\\s|$)"), " ")
        out = out.replace(Regex(",{2,}"), ",")
        out = out.replace(Regex("\\s{2,}"), " ")
        return out.trim().trim(',').trim()
    }

    /**
     * Нормализация «японской» и полноширинной пунктуации перед синтезом.
     *
     * Google Lens и сканлатеры часто отдают реплики с полноширинными знаками
     * (＂！＂, ＂？＂, ＂：＂, ＂。＂, CJK-скобки), а синтезатор читает такие знаки
     * ВСЛУХ словами («восклицательный знак», «двоеточие», «правая скобка»)
     * вместо паузы и интонации. Приводим их к обычным ASCII/типографским
     * аналогам — движок даёт им эмоцию и паузу, как задумано. Сами буквы и
     * слова любых языков не трогаем: меняются только служебные знаки.
     */
    private fun normalizeSpeechPunctuation(text: String): String = buildString(text.length) {
        for (c in text) {
            when {
                // Полноширинные ASCII-формы U+FF01..FF5E (! ~ 0-9 A-Z a-z) — обычные.
                c in '！'..'～' -> append(c - 0xFEE0)
                else -> when (c) {
                    '　' -> append(' ') // идеографический пробел
                    '。' -> append('.')
                    '、' -> append(',')
                    // CJK-скобки: голос говорил «скобка». Рамку цитаты озвучивать
                    // нечем — просто снимаем её (остаётся сама реплика).
                    '「', '」', '『', '』', '【', '】', '〈', '〉', '《', '》', '〔', '〕' -> append(' ')
                    '・', '･' -> append(' ')
                    // Долгота каны и волнистые черты звука не имеют —
                    // проговариваться словами тоже не должны.
                    'ー', '〜', '∼' -> Unit
                    else -> append(c)
                }
            }
        }
    }

    /** Добавляет номер реплики в начало, если его там ещё нет. */
    fun withIndex(text: String, index: Int): String =
        if (TAG.containsMatchIn(text) && text.trimStart().startsWith("{$index}")) {
            text
        } else {
            "{$index} $text"
        }

    /** Собирает пометки для показа: `{3}{ж2}` перед текстом. */
    fun tagsOf(text: String): String =
        TAG.findAll(text).joinToString("") { it.value }
}

package eu.kanade.tachiyomi.data.tts

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import java.net.HttpURLConnection
import java.net.URL

/**
 * Определение пола говорящего по странице: Gemini Vision получает кадр и
 * список реплик и отвечает, кто произносит каждую (male/female/unknown) —
 * по лицам персонажей и хвостикам речевых баллонов.
 *
 * Требует Google AI ключ (Настройки → OCR). Без ключа/при ошибке возвращает
 * unknown для всех реплик — озвучка идёт основным голосом, ничего не ломается.
 */
object SpeakerGenderService {

    suspend fun detect(
        imageJpeg: ByteArray,
        lines: List<String>,
        prefs: OcrPreferences,
    ): List<String?> = withContext(Dispatchers.IO) {
        val unknown = List<String?>(lines.size) { null }
        val apiKey = prefs.googleApiKey().get()
        if (apiKey.isBlank() || lines.isEmpty()) return@withContext unknown

        try {
            val model = prefs.googleModel().get().ifBlank { "gemini-2.5-flash" }
            val numbered = lines.mapIndexed { i, t -> "${i + 1}. ${t.take(120)}" }.joinToString("\n")
            val prompt =
                "This is a manga/comic page. For each numbered dialogue line below, look at the " +
                    "characters' faces and the speech bubble tails to decide WHO SPEAKS it. " +
                    "Answer ONLY with a JSON array of strings, one per line, in the same order, " +
                    "each being exactly \"male\", \"female\" or \"unknown\". No other text.\n\n" + numbered

            val body = JSONObject().apply {
                put("generationConfig", JSONObject().put("temperature", 0.0))
                put(
                    "contents",
                    JSONArray().put(
                        JSONObject().put(
                            "parts",
                            JSONArray()
                                .put(JSONObject().put("text", prompt))
                                .put(
                                    JSONObject().put(
                                        "inline_data",
                                        JSONObject()
                                            .put("mime_type", "image/jpeg")
                                            .put(
                                                "data",
                                                android.util.Base64.encodeToString(
                                                    imageJpeg,
                                                    android.util.Base64.NO_WRAP,
                                                ),
                                            ),
                                    ),
                                ),
                        ),
                    ),
                )
            }

            val url = "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$apiKey"
            val conn = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                doOutput = true
                connectTimeout = 15_000
                readTimeout = 45_000
                setRequestProperty("Content-Type", "application/json")
            }
            val response = try {
                conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
                val code = conn.responseCode
                val text = (if (code in 200..299) conn.inputStream else conn.errorStream)
                    ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
                if (code !in 200..299) {
                    logcat(LogPriority.WARN) { "Gender detect HTTP $code: ${text.take(120)}" }
                    return@withContext unknown
                }
                text
            } finally {
                conn.disconnect()
            }

            val answer = JSONObject(response)
                .optJSONArray("candidates")?.optJSONObject(0)
                ?.optJSONObject("content")?.optJSONArray("parts")
                ?.optJSONObject(0)?.optString("text").orEmpty()
                .replace("```json", "").replace("```", "").trim()

            val arr = JSONArray(answer)
            List(lines.size) { i ->
                when (arr.optString(i, "unknown").lowercase()) {
                    "male" -> "male"
                    "female" -> "female"
                    else -> null
                }
            }
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Speaker gender detection failed" }
            unknown
        }
    }
}

package eu.kanade.tachiyomi.data.tts

/**
 * Самодельный ВСТРОЕННЫЙ AI-помощник озвучки. Никаких API-ключей и сети:
 * пол говорящего определяется лингвистической эвристикой прямо на устройстве.
 *
 * Для русского текста работает морфология:
 *  • глаголы прошедшего времени от первого лица: «сказала/подумала/пришла…»
 *    → женская реплика; «сказал/подумал/пришёл…» → мужская;
 *  • самоописания: «я рада», «я сама», «я готова» vs «я рад», «я сам»,
 *    «я готов»;
 *  • обращения-маркеры: «сестрёнка, ты…», «братик, ты…» относятся к
 *    собеседнику и НЕ учитываются для говорящего.
 *
 * Скоринг: считаем женские и мужские маркеры, отвечаем полом только при
 * явном перевесе — иначе null (нейтральный голос). Лучше промолчать, чем
 * озвучить неверным полом.
 */
object LocalSpeakerAi {

    // «я/мне/меня …-ла» — окончание прошедшего времени ж.р.
    private val feminineVerb = Regex("""(?:^|\s)(?:я|ведь я|и я)\s+(?:\S+\s+){0,2}?\S+ла(?:сь)?\b""")
    private val masculineVerb = Regex("""(?:^|\s)(?:я|ведь я|и я)\s+(?:\S+\s+){0,2}?\S+(?:[^аеиоуыэюяль]|ёл|ел|ал|ул|ил|ыл|л)(?:ся)?\b""")

    private val feminineSelf = listOf(
        "я сама", "я рада", "я готова", "я должна", "я уверена", "я согласна",
        "я не могла", "я была", "я хотела", "я думала", "я поняла", "я знала",
        "я видела", "я слышала", "я пришла", "я решила", "сама справлюсь",
        "я устала", "я испугалась", "я замужем",
        // самоидентификация через существительные
        "я мама", "я мать", "я сестра", "я дочь", "я бабушка", "я девушка",
        "я женщина", "я принцесса", "я королева", "я ведьма", "я учительница",
        // самоидентификация через прилагательные
        "я красивая", "я сильная", "я умная", "я добрая", "я злая",
        "я беременна", "я влюблена", "я свободна", "я занята", "я права",
    )
    private val masculineSelf = listOf(
        "я сам", "я рад", "я готов", "я должен", "я уверен", "я согласен",
        "я не мог", "я был", "я хотел", "я думал", "я понял", "я знал",
        "я видел", "я слышал", "я пришёл", "я пришел", "я решил", "сам справлюсь",
        "я устал", "я испугался", "я женат",
        // самоидентификация через существительные
        "я папа", "я отец", "я брат", "я сын", "я дед", "я мужчина", "я парень",
        "я юноша", "я принц", "я король", "я воин", "я рыцарь", "я маг",
        // самоидентификация через прилагательные
        "я красивый", "я сильный", "я умный", "я добрый", "я злой",
        "я свободен", "я занят", "я прав", "я виноват",
    )

    /** Пол говорящего: "female" | "male" | null (не уверены). */
    fun guessGender(rawText: String): String? {
        val text = " " + rawText.lowercase().replace('ё', 'ё') + " "

        var female = 0
        var male = 0

        for (marker in feminineSelf) if (text.contains(marker)) female += 2
        for (marker in masculineSelf) if (text.contains(marker)) male += 2

        if (feminineVerb.containsMatchIn(text)) female += 1
        else if (masculineVerb.containsMatchIn(text)) male += 1

        return when {
            female > male -> "female"
            male > female -> "male"
            else -> null
        }
    }

    /**
     * Пол для каждой реплики кадра. Реплики без явных маркеров наследуют
     * пол предыдущей уверенной реплики того же кадра только если стоят
     * вплотную (диалог одного персонажа из нескольких бабблов подряд).
     */
    fun guessGenders(lines: List<String>): List<String?> {
        val result = arrayOfNulls<String>(lines.size)
        for (i in lines.indices) {
            result[i] = guessGender(lines[i])
        }
        return result.toList()
    }

    /**
     * СЛОВАРНАЯ подстраховка (пол по упомянутым лицам). Голосует только при
     * ЧИСТОМ признаке: в реплике упомянут ровно один пол. Оба пола сразу —
     * это разговор О ком-то, пол говорящего не определяем (null → нарратор).
     * v1.9.135: ранее эта эвристика жила в AutoReadEngine и перевешивала
     * count'ами даже смешанные маркеры — отсюда инвертируемые голоса при
     * авточтении. Вынесена сюда, чтобы быть доступной unit-тестам без
     * android-зависимостей.
     */
    fun genderByMentions(text: String): String? {
        // Основы (не формы), чтобы ловить все падежи: «сестра/сестры/
        // сестрёнка/сестре», «принцесса/принцессой» и т.д. Конфликтные корни
        // не берём («корол-» совпадает с «королева» ж.р., «мам» — с «мамка»).
        val maleMarkers = listOf(
            "брат", "отц", "пап", "дед", "сын", "мужчин", "парн",
            "господин", "старик", "мальчик", "юнош", "принц", "король",
        )
        val femaleMarkers = listOf(
            "сестр", "мате", "мам", "бабушк", "доч", "женщин", "девушк",
            "госпож", "старух", "девочк", "принцесс", "королева",
        )
        val lower = text.lowercase()
        // Подстрочный поиск покрывает падежи: «моей сестры», «к отцу».
        val maleCount = maleMarkers.count { lower.contains(it) }
        val femaleCount = femaleMarkers.count { lower.contains(it) }
        if (maleCount > 0 && femaleCount > 0) return null
        return when {
            maleCount > 0 -> "male"
            femaleCount > 0 -> "female"
            else -> null
        }
    }
}

package eu.kanade.tachiyomi.data.tts

/**
 * Театральные ремарки и междометия: что произнести и как.
 *
 * Проблема была в трёх местах. Первое: ремарка в скобках попадала в синтез
 * либо выбрасывалась совсем, либо читалась словом — «(вздох)» звучало как
 * «вздох». Второе: `а`, `аа`, `ааа` не различались, хотя означают разное —
 * удивление, попытку закричать, крик. Третье: состояние персонажа (бежит,
 * устал, обессилел, зовёт помощь) вообще не влияло на голос.
 *
 * Ремарки делятся на два вида, и это не украшение, а смысл:
 *
 *  * **звук** (вздох, вдох, стон, крик, смех, кашель) — ПРОИЗНОСИТСЯ.
 *    Синтезатор не умеет вздыхать, поэтому звук передаётся вытянутым
 *    «А-а-а», а характер звука берёт на себя питч и темп;
 *  * **состояние** (шёпот, бег, усталость, слабость, боль, испуг, злость) —
 *    НЕ произносится, а меняет подачу всей реплики. Произносить слово
 *    «шёпот» вслух нельзя, это сломало бы чтение.
 *
 * Ничего не теряется: неизвестная ремарка просто снимается, но любой звук из
 * таблицы произносится, а любое состояние доходит до голоса модификатором.
 *
 * Модуль чистый — без Android и без движка, поэтому проверяется на JVM.
 */
object SpeechCue {

    /** Как произнести один кусок реплики. */
    data class Delivery(
        val text: String,
        val pitch: Float = 1.0f,
        val rate: Float = 1.0f,
        val pauseAfterMs: Int = 0,
        /**
         * Кусок пришёл из звука или междометия, то есть его подача уже
         * задана здесь. Движок в этом случае не добавляет поверх знаковую
         * пунктуацию, иначе «Ааа!» получил бы крик дважды.
         */
        val fromCue: Boolean = false,
        /**
         * Кусок — настоящий звук (вздох, стон, крик), который обычный голос
         * не умеет произносить, а лишь читает буквами. Такие куски — ровно те,
         * что мост отправляет в плагин озвучки; междометия и обычный текст
         * остаются на голосе.
         */
        val isSound: Boolean = false,
        /**
         * Тип звука («sigh», «moan», «cry», …). Плагину нужен именно тип: он
         * подбирает нужный образец, а не читает подставленный текст.
         */
        val soundId: String? = null,
    )

    /** Типы звуков: стабильные ключи для плагина, порядок как в [SOUNDS]. */
    object SoundId {
        const val CRY_FOR_HELP = "cry_for_help"
        const val CRY = "cry"
        const val MOAN = "moan"
        const val GASP = "gasp"
        const val SIGH = "sigh"
        const val LAUGH = "laugh"
        const val COUGH = "cough"
    }

    /** Звук: что говорить и каким голосом. */
    class Sound(
        val spoken: String,
        val pitch: Float,
        val rate: Float,
        val pauseMs: Int,
        val words: List<String>,
        /** Тип звука для плагина озвучки, см. [SoundId]. */
        val id: String,
    )

    /** Состояние: только модификатор подачи, ничего не произносится. */
    class State(
        val pitch: Float,
        val rate: Float,
        val words: List<String>,
    )

    // Порядок важен: первое совпадение выигрывает. «Крик помощи» и «вдох»
    // стоят раньше «крика» и «вздоха», иначе крик о помощи читался бы
    // обычным криком, а вдох — выдохом.
    private val SOUNDS = listOf(
        Sound(
            spoken = "А-а-а! Помогите!",
            pitch = 1.28f,
            rate = 1.10f,
            pauseMs = 420,
            words = listOf(
                "крик помощи", "зовет помощь", "зовёт помощь", "на помощь",
                "помогите", "помоги", "спасите", "спаси", "救命",
            ),
            id = SoundId.CRY_FOR_HELP,
        ),
        Sound(
            spoken = "А-а-а!",
            pitch = 1.30f,
            rate = 1.15f,
            pauseMs = 380,
            words = listOf(
                "вопль", "визг", "крик", "кричит", "кричу", "орёт", "орет",
                "воет", "воёт", "рычит", "закричал", "закричала", "вскрикнул",
                "вскрикнула", "кричит о помощи",
            ),
            id = SoundId.CRY,
        ),
        Sound(
            spoken = "А-а-а...",
            pitch = 0.92f,
            rate = 0.85f,
            pauseMs = 320,
            words = listOf(
                "стонет от боли", "стон", "стонет", "хнычет", "хнычеть",
                "ныть", "поскуливает", "скулит",
            ),
            id = SoundId.MOAN,
        ),
        Sound(
            spoken = "А-а-а!",
            pitch = 1.05f,
            rate = 0.95f,
            pauseMs = 240,
            words = listOf(
                "вдох", "вдыхает", "задыхается", "хватает воздух",
                "не хватает воздуха", "дышит часто", "задыхаясь",
            ),
            id = SoundId.GASP,
        ),
        Sound(
            spoken = "А-а-а...",
            pitch = 0.86f,
            rate = 0.78f,
            pauseMs = 360,
            words = listOf(
                "вздох", "вздыхает", "вздохнув", "выдох", "выдыхает",
            ),
            id = SoundId.SIGH,
        ),
        Sound(
            spoken = "Ха-ха-ха!",
            pitch = 1.12f,
            rate = 1.12f,
            pauseMs = 260,
            words = listOf(
                "смеется", "смеётся", "смех", "хохочет", "хихикает",
                "усмехается", "смешок",
            ),
            id = SoundId.LAUGH,
        ),
        Sound(
            spoken = "Кхм... Кхм!",
            pitch = 0.94f,
            rate = 0.9f,
            pauseMs = 300,
            words = listOf("кашель", "кашляет", "кашлянул", "кашлянуть", "кашлит"),
            id = SoundId.COUGH,
        ),
    )

    // Тише и медленнее — шёпот. Бег, усталость и слабость меняют темп, и
    // порядок снова важен: «задыхаясь» не должно превращаться в шёпот.
    private val STATES = listOf(
        State(
            1.0f, 0.72f,
            listOf("шёпот", "шепот", "шёпотом", "шепчет", "шепчетом", "тихо говорит", "потихоньку"),
        ),
        State(
            1.02f, 1.18f,
            listOf("бежит", "бегом", "на бегу", "бегущий", "на бегущих", "спешит", "торопится", "в бегах"),
        ),
        State(
            0.92f, 0.86f,
            listOf(
                "устал", "устала", "усталость", "тяжело дышит", "выдохшийся",
                "выдохлась", "истощен", "истощён", "без сил", "сил нет",
            ),
        ),
        State(
            0.88f, 0.80f,
            listOf(
                "слабость", "вялость", "обессилел", "обессилела", "слабый голосом",
                "едва говорит", "хрипло", "сипло",
            ),
        ),
        State(
            0.95f, 0.88f,
            listOf("боль", "болит", "рана", "ранен", "ранена", "испытывает боль"),
        ),
        State(
            0.90f, 1.05f,
            listOf("испуг", "боится", "боюсь", "страх", "трусит", "дрожит", "боязливо"),
        ),
        State(
            1.12f, 1.12f,
            listOf("злость", "злится", "ярость", "сердит", "взбешён", "взбешен", "разозлён", "разозлен"),
        ),
        State(
            1.14f, 1.04f,
            listOf(
                "удивлён", "удивлен", "удивление", "изумлён", "изумлен",
                "шок", "потрясён", "потрясен", "разился",
            ),
        ),
    )

    /**
     * Ремарки в скобках: `(вздох)`, `[ааа]`, `*шёпотом*`, а также курсив и
     * кавычки. Закрывающая скобка экранирована — без экрана ICU-движок
     * части Android падает прямо на разборе шаблона (см. предупреждение
     * в [SpeechMarkup]).
     */
    // Внутренняя часть ремарки допускает `*`: разметка `(*шёпотом*)` и `(шёпотом)`
    // должны разбираться одинаково. Запрещены только закрывающие скобки — иначе
    // группа «съест» конец ремарки. Закрывающая часть — целая серия: у `(*шёпотом*)`
    // их две (`*` и `)`), иначе хвост утекал бы в произносимый текст.
    private val CUE_SPAN = Regex("""[(\[*]\s*([^()\[\]\{\}]{1,60}?)\s*[\)\]\*]+""")

    /**
     * Кандидат в междометие: короткая «слово-сгусток» из букв и дефисов,
     * стоящая сама по себе. Дальше решает белый список, а не сам шаблон.
     *
     * Так сделано намеренно. Если разрешить «любую последовательность из
     * а, у, о, м, х», под неё попадут обычные слова: «еху», «уху», «аму»,
     * «уа», «хам», «ом». Список явный, поэтому «хам» останется словом.
     */
    private val CANDIDATE = Regex("""(?<![\p{L}\p{N}])([\p{L}\-]{1,12})(?![\p{L}\p{N}])""")

    /**
     * Белый список междометий. Повторы букв и дефисы значимы: «а» — это
     * удивление, «аа» — попытка закричать, «ааа» — уже крик, «а-а-а» —
     * то же, но тянутое.
     */
    private val INTERJECTIONS: Set<String> = setOf(
        // удивление, короткое «а» и его вытянутые варианты
        "а", "аа", "ааа", "аааа", "ааааа", "аааааа",
        "а-а", "а-а-а", "а-а-а-а", "а-а-а-а-а",
        "а-а-а-а-а", "а-ах", "а-а-а-х", "аа-а", "а-а-ах", "аах", "а-у-а",
        // вдох / выдох / хрип
        "ах", "аха", "ахх", "ааах", "ааа-а", "ух", "уха", "уух", "уах", "ухх",
        "ох", "оха", "о-о", "о-о-о", "оах", "охх",
        // тяжёлое дыхание, усталость
        "у", "уу", "у-у", "у-у-у", "у-у-у-у", "ы", "ыы", "ыыы", "ыыыы", "ы-ы",
        // мысль, размышление
        "мм", "ммм", "м-м", "м-м-м", "мммм", "ммммм", "хм", "х-м", "хмм", "хммм",
        "эм", "эмм", "э-э", "э-э-э", "эге-гей", "и-и", "х-х",
        // согласие и понимание
        "угу", "угу-угу", "ага", "ага-ага", "ого", "ой", "уау", "а-у", "уа-у", "а-и",
        // просьба тишины и раздражение
        "ти", "тсс", "тш", "шш", "пф", "пфф", "пфс",
        // резкий испуг
        "бам", "бум", "бух", "бах", "ай", "аааа", "ой-ой",
    )

    /** Знаки, которые приклеиваются к междометию и не должны отделяться. */
    private val TAIL_PUNCT = "!?.,…"

    /** Что за звук задан ремаркой, или null. */
    fun soundOf(remark: String): Sound? {
        val low = remark.lowercase()
        return SOUNDS.firstOrNull { s -> s.words.any { low.contains(it) } }
    }

    /** Какое состояние описано в ремарке, или null. */
    fun stateOf(remark: String): State? {
        val low = remark.lowercase()
        return STATES.firstOrNull { s -> s.words.any { low.contains(it) } }
    }

    /**
     * Является ли токен междометием.
     *
     * Хвостовая пунктуация не мешает: «Ааа!», «ах…» — это то же самое
     * междометие, просто с восклицательным знаком. Без этого `*Ааа!*` и `[Ааа!]`
     * молчали: в наборе лежит «Ааа», а проверяли мы «Ааа!».
     */
    fun isInterjection(token: String): Boolean =
        token.lowercase().trimEnd(' ', '!', '?', '.', ',', ';', ':', '…', '‼', '⁇') in INTERJECTIONS

    /**
     * Подставляет вместо ремарок произносимое: звук → вытянутое междометие,
     * состояние и неизвестная ремарка → пусто (состояние меняет подачу, а не
     * текст; неизвестное не читается словом). Голое междометие в скобках
     * остаётся: `[ааа]` — это и есть звук, терять его незачем.
     */
    fun render(text: String): String {
        var out = CUE_SPAN.replace(text) { match ->
            val remark = match.groupValues[1].trim('*').trim()
            soundOf(remark)?.spoken
                ?: if (isInterjection(remark)) remark
                // `*курсив*` — текст, который нужно показать и прочесть, а не
                // указание говорящему. Согласуется с deliveries().
                else if (match.value.trimStart().startsWith("*") && stateOf(remark) == null) {
                    remark.replace(Regex("[*~]"), " ")
                } else ""
        }
        out = out.replace(Regex("[*~]"), " ")
        out = out.replace(Regex(""" {2,}"""), " ")
        return out.replace(Regex("""\s+([,.!?;:…])"""), "$1").trim()
    }

    /** Слова согласия и понимания — ровный тон, без испуга. */
    // «уа» убрано намеренно: это сленговое «назад», а не междометие.
    private val AGREEMENT = setOf("ага", "ага-ага", "угу", "угу-угу", "ого", "уау", "а-у", "а-у-а")

    /** Звуки размышления — тише и медленнее, реплика «потом». */
    private val THINKING = setOf(
        "мм", "ммм", "мммм", "ммммм", "м-м", "м-м-м", "хм", "х-м", "хмм", "хммм",
        "х-х", "эм", "эмм", "э-э", "э-э-э", "эге-гей", "и-и", "у", "уу", "у-у", "у-у-у",
        "у-у-у-у", "ы", "ыы", "ыыы", "ыыыы", "ы-ы", "ти", "тш", "шш",
    )

    /** Резкий испуг — короткий и высокий. */
    private val STARTLE = setOf("ой", "ой-ой", "ай", "бам", "бум", "бух", "бах")

    /**
     * Подача междометия по его виду и длине. Одно «а» — удивление, «аа» —
     * попытка закричать, «ааа» и длиннее — крик; раньше они читались
     * одинаково, и разница терялась.
     */
    fun interjectionDelivery(word: String): Delivery {
        // Синтезу регистр безразличен, но единый вид удобнее в логах и в
        // разметке: `ааа` из ремарки и в начале фразы выглядит одинаково.
        val spoken = word.replaceFirstChar { it.uppercaseChar() }
        val core = spoken.trim().lowercase().trim(*TAIL_PUNCT.toCharArray())
        val letters = core.filter { it.isLetter() }
        val aCount = letters.count { it == 'а' || it == 'a' }
        val breath = core.any { it == 'х' || it == 'ц' || it == 'h' }
        val sigh = core.any { it == 'у' || it == 'о' || it == 'ы' || it == 'y' }
        val long = letters.length >= 4
        val (p, r, pause) = when {
            core in AGREEMENT -> Triple(1.04f, 0.98f, 200)
            core in THINKING -> Triple(0.96f, 0.86f, 240)
            core in STARTLE -> Triple(1.18f, 1.06f, 220)
            breath -> Triple(1.06f, 0.92f, 240)
            sigh -> Triple(0.88f, 0.84f, 260)
            aCount >= 3 || long -> Triple(1.28f, 1.12f, 320)
            aCount == 2 -> Triple(1.16f, 0.90f, 240)
            else -> Triple(1.10f, 0.95f, 180)
        }
        return Delivery(spoken, pitch = p, rate = r, pauseAfterMs = pause, fromCue = true)
    }

    /**
     * Полная разметка реплики: куски со своей подачей.
     *
     * Ремарки убираются (звук превращается в произносимое с собственным
     * голосом), состояние становится множителем подачи, а голые междометия
     * выделяются отдельными кусками. Именно так «ааа» перестаёт читаться
     * вместе со следующей фразой общим тоном, а шёпот делает тише и
     * медленнее всю реплику.
     */
    fun deliveries(sentence: String): List<Delivery> {
        if (sentence.isBlank()) return emptyList()

        val spans = CUE_SPAN.findAll(sentence).toList()

        // Состояние: при нескольких ремарках побеждает самое заметное
        // (самая крайняя скорость), чтобы «(устал) (бегом)» не усреднялось.
        val state = spans.mapNotNull { stateOf(it.groupValues[1]) }
            .maxByOrNull { kotlin.math.abs(it.rate - 1f) }
        val sp = state?.pitch ?: 1.0f
        val sr = state?.rate ?: 1.0f

        val out = mutableListOf<Delivery>()

        /** Раскладывает обычный текст: голые междометия — отдельными кусками. */
        fun plain(raw: String) {
            // Осиротевшие `*` и `~` от незакрытой разметки не произносятся
            // и не превращаются в отдельный вызов движка.
            val part = raw.replace(Regex("[*~]"), " ")
            var last = 0
            CANDIDATE.findAll(part).forEach { m ->
                if (!isInterjection(m.value)) return@forEach
                // Знаки после междометия («А-а-а!») остаются с ним же, иначе
                // восклицательный знак уедет в отдельный кусок.
                var end = m.range.last + 1
                while (end < part.length && part[end] in TAIL_PUNCT) end++
                val head = part.substring(last, m.range.first).trim()
                if (isAudible(head)) out += Delivery(head, sp, sr, defaultPause(head))
                val d = interjectionDelivery(part.substring(m.range.first, end))
                if (isAudible(d.text)) {
                    out += Delivery(
                        d.text,
                        d.pitch * sp,
                        d.rate * sr,
                        d.pauseAfterMs,
                        fromCue = true,
                    )
                }
                last = end
            }
            val tail = part.substring(last).trim()
            if (isAudible(tail)) out += Delivery(tail, sp, sr, defaultPause(tail))
        }

        var cursor = 0
        for (span in spans) {
            plain(sentence.substring(cursor, span.range.first))
            cursor = span.range.last + 1
            val remark = span.groupValues[1].trim('*').trim()
            val sound = soundOf(remark)
            // `*курсив*` — обычный текст, а не ремарка. Молча выбрасывать слово
            // нельзя: OCR вебтунов и переводов даёт звёздочки сплошь и рядом.
            val starEmphasis = span.value.trimStart().startsWith("*") &&
                sound == null && stateOf(remark) == null && !isInterjection(remark)
            when {
                // Звук произносится сразу, собственным голосом: так вздох
                // отличается от крика, а не читается тем же тоном, что весь
                // текст под ним.
                sound != null -> out += Delivery(
                    sound.spoken,
                    sound.pitch * sp,
                    sound.rate * sr,
                    sound.pauseMs,
                    fromCue = true,
                    isSound = true,
                    soundId = sound.id,
                )
                isInterjection(remark) -> plain(remark)
                // Звёздочки вокруг обычного слова — выделение, а не указание
                // говорящему: произносим само слово.
                starEmphasis -> plain(span.value)
                // Состояние и неизвестная ремарка не произносятся: первое уже
                // учтено множителем, второе не должно читаться как слово.
                else -> Unit
            }
        }
        plain(sentence.substring(cursor))

        if (out.isEmpty()) {
            val clean = render(sentence)
            if (isAudible(clean)) out += Delivery(clean, sp, sr, defaultPause(clean))
        }
        return out
    }

    /**
     * Произносим ли кусок: хотя бы одна буква или цифра. Одинокая пунктуация
     * (`(` или `)` от незакрытой `(*ремарка*)`) не должна уходить в движок
     * отдельным вызовом — он её либо пропустит, либо озвучит как символы.
     */
    internal fun isAudible(text: String): Boolean = text.any { it.isLetterOrDigit() }

    /** Пауза после куска: та же логика, что в движке, но по самому куску. */
    private fun defaultPause(text: String): Int = when {
        text.endsWith("!") || text.endsWith("?") ||
            text.endsWith("‼") || text.endsWith("⁇") -> 420
        text.endsWith(",") || text.endsWith(";") -> 160
        else -> 260
    }
}

package eu.kanade.tachiyomi.data.tts

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import java.net.HttpURLConnection
import java.net.URL

/**
 * Проверка страницы моделью с картинкой: кто говорит каждую реплику, что
 * пропущено, где OCR ошибся.
 *
 * Локальный OCR различает ТЕКСТ, но не понимает РИСУНОК: хвостик облачка,
 * кому он указывает, где мысль, а где реплика. Поэтому голоса в сцене без
 * подписей назначаются по кругу. Единственный источник этой информации —
 * модель, которая видит картинку.
 *
 * Чего вызов НЕ делает:
 *  • не выдумывает текст: непрочитанное остаётся как есть, спорное помечается
 *    флагом [LineCheck.uncertain] — иначе получаются правдоподобные
 *    «разiiiнение» и «сахар-самаар», уже зафиксированные в todo.md;
 *  • не трогает ничего вне книги: ответ приходит страницей, применяется
 *    страницей, книжные роли пишутся в словарь этой книги.
 *
 * Без ключа/при ошибке возвращает null, и вызывающая сторона оставляет
 * локальный разбор: озвучка и порядок чтения не ломаются.
 */
object PageRoleVerifier {

    /**
     * Реплика после проверки.
     *
     * [kept] = false — модель решила, что это не реплика (титул, примечание
     * переводчика, пустая рамка). Такие строки не произносятся, но остаются в
     * отчёте, чтобы ничего не пропало молча.
     */
    data class LineCheck(
        val role: String,
        val text: String,
        val thought: Boolean,
        val kept: Boolean,
        /** true — модель не уверена; строка принимается, но помечается. */
        val uncertain: Boolean,
    )

    data class PageCheck(
        val lines: List<LineCheck>,
        /** Что страница не учла: титры, примечания, звуки. Только для отчёта. */
        val dropped: List<String>,
        /** Модель отвечает по картинке (false — вызова не было). */
        val checked: Boolean,
        /** Причина отказа, если [checked] = false. */
        val reason: String?,
    )

    /** Ответ без проверки: локальный разбор остаётся как есть. */
    fun unavailable(reason: String): PageCheck =
        PageCheck(lines = emptyList(), dropped = emptyList(), checked = false, reason = reason)

    suspend fun verify(
        imageJpeg: ByteArray,
        pageName: String,
        draftLines: List<String>,
        prefs: OcrPreferences,
    ): PageCheck = withContext(Dispatchers.IO) {
        if (draftLines.isEmpty()) return@withContext unavailable("нет строк для проверки")
        val apiKey = prefs.googleApiKey().get()
        if (apiKey.isBlank()) return@withContext unavailable("нет ключа Google AI")

        try {
            val model = prefs.googleModel().get().ifBlank { "gemini-2.5-flash" }
            val body = JSONObject().apply {
                put("generationConfig", JSONObject().put("temperature", 0.0))
                put(
                    "contents",
                    JSONArray().put(
                        JSONObject().put(
                            "parts",
                            JSONArray()
                                .put(JSONObject().put("text", prompt(pageName, draftLines)))
                                .put(
                                    JSONObject().put(
                                        "inline_data",
                                        JSONObject()
                                            .put("mime_type", "image/jpeg")
                                            .put(
                                                "data",
                                                android.util.Base64.encodeToString(
                                                    imageJpeg,
                                                    android.util.Base64.NO_WRAP,
                                                ),
                                            ),
                                    ),
                                ),
                        ),
                    ),
                )
            }

            val url = "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$apiKey"
            val conn = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                doOutput = true
                connectTimeout = 15_000
                readTimeout = 60_000
                setRequestProperty("Content-Type", "application/json")
            }
            val response = try {
                conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
                val code = conn.responseCode
                val text = (if (code in 200..299) conn.inputStream else conn.errorStream)
                    ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
                if (code !in 200..299) {
                    logcat(LogPriority.WARN) { "Page verify HTTP $code: ${text.take(160)}" }
                    return@withContext unavailable("HTTP $code от модели")
                }
                text
            } finally {
                conn.disconnect()
            }

            val answer = JSONObject(response)
                .optJSONArray("candidates")?.optJSONObject(0)
                ?.optJSONObject("content")?.optJSONArray("parts")
                ?.optJSONObject(0)?.optString("text").orEmpty()
            parse(answer, draftLines)
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Page role verification failed" }
            unavailable("ошибка: ${e.javaClass.simpleName}")
        }
    }

    /**
     * Разбор ответа модели.
     *
     * Модель отдаёт `{"pages":[{"page":"…","lines":[…]}]}`. Разбор терпимый к
     * мусору и Markdown-заборам: если что-то не распозналось, возвращается
     * `checked = false`, а НЕ частичный правдоподобный результат — иначе
     * половина реплик получила бы роли, а половина осталась бы с догадками
     * локального разбора, и отладить это было бы невозможно.
     */
    internal fun parse(answer: String, draftLines: List<String>): PageCheck {
        val cleaned = answer.replace("```json", "").replace("```", "").trim()
        if (cleaned.isEmpty()) return unavailable("пустой ответ модели")

        // Разбор без org.json: в юнит-тестах app-модуля он не замокан и
        // бросает, а проверять разбор модели нужно именно тестами. Свой
        // разбор уже есть в VoiceJson — он же умеет вложенные массивы.
        val pagesText = VoiceJson.extractArray(cleaned, "pages") ?: return unavailable("ответ без поля pages")
        val page = VoiceJson.parseObjects(pagesText).firstOrNull() ?: return unavailable("пустой pages")
        val linesText = VoiceJson.extractArray(page["lines"].orEmpty(), "lines")
            ?: page["lines"]?.takeIf { it.trim().startsWith("[") }
            ?: return unavailable("ответ без lines")

        val lineObjects = VoiceJson.parseObjects(linesText)
        if (lineObjects.isEmpty()) return unavailable("модель не вернула ни одной реплики")

        val out = ArrayList<LineCheck>(lineObjects.size)
        for (o in lineObjects) {
            val text = o["text"].orEmpty().trim()
            if (text.isEmpty()) continue
            // Честность важнее правдоподобия: модель не должна «улучшать» текст.
            val replaced = o["draft_text"].orEmpty().trim()
            out += LineCheck(
                role = o["role"].orEmpty().trim().ifEmpty { UNKNOWN_ROLE },
                text = text,
                thought = o["thought"].equals("true", ignoreCase = true),
                kept = o["kept"]?.equals("false", ignoreCase = true) != true,
                // Строка, которой в черновике не было, — её модель либо
                // прочитала лучше OCR, либо сочинила. Помечаем как спорную,
                // чтобы её можно было откатить, не выбрасывая страницу.
                uncertain = replaced.isNotEmpty() && replaced != text,
            )
        }

        // "dropped" лежит на уровне страницы, рядом с "lines": то, что модель
        // не считала репликой (титры, примечания, звуки). Возвращается
        // списком, чтобы пропажу нельзя было спутать с опечаткой модели.
        val dropped = page["dropped"]
            ?.let { VoiceJson.extractArray(it, "dropped") ?: it }
            ?.let { VoiceJson.parseArrayTokens(it) }
            ?.map { it.trim() }
            ?.filter { it.isNotEmpty() }
            .orEmpty()

        if (out.isEmpty()) return unavailable("все строки ответа пустые")
        return PageCheck(lines = out, dropped = dropped, checked = true, reason = null)
    }

    /** Роль, когда модель не назвала говорящего. */
    const val UNKNOWN_ROLE = "?"

    /**
     * Промпт.
     *
     * Написан так, чтобы работать на любом жанре и стиле: правила про формы
     * реплик, а не про конкретную мангу. Отдельно вынесено то, что в прошлых
     * правках приводило к выдуманным словам: модели запрещено «улучшать»
     * текст, непрочитанное помечается, а пропуск фиксируется в `dropped`,
     * чтобы его нельзя было спутать с опечаткой модели.
     */
    internal fun prompt(pageName: String, draftLines: List<String>): String {
        val numbered = draftLines.mapIndexed { i, t -> "${i + 1}. ${t.take(200)}" }.joinToString("\n")
        return """
            Ты проверяешь страницу манги/комикса/веб-комикса по КАРТИНКЕ.
            Жанр, стиль и язык любые — правила ниже универсальны.

            ЧЕРНОВИК РАСПОЗНАВАНИЯ (строки уже извлечены OCR, они могут быть
            ошибочны, склеены или обрезаны):

            $numbered

            ВЫПОЛНИ ЧЕТЫРЕ ПРОВЕРКИ:

            1) АТРИБУЦИЯ. У каждого речевого облачка есть хвостик, он указывает
               на говорящего. Определи, КТО говорит, и запиши его имя (или
               "?" если персонаж без подписи и определить нельзя).
               ФОРМЫ РЕПЛИК:
               - прямоугольная надпись ВНЕ облачков = нарратор (роль "narrator");
               - обычный эллипс/скруглённая рамка с хвостиком = речь;
               - эллипс БЕЗ хвостика (облачко мысли) = thought: true;
               - рваная/взрывная рамка, капля, шип = выкрик, это речь, а не мысль;
               - прямоугольник с прямой репликой без хвостика = тоже речь.
               Если в сцене один персонаж — у всех его реплик одна и та же роль.

            2) ПОЛНОТА. Добавь реплики, мысли и тексты рамок, которых НЕТ в
               черновике (OCR их пропустил). Для добавленных строк укажи
               draft_text = "" (их не было в черновике).
               НЕ добавляй: SFX/звуки, титулы, примечания переводчика, рамки
               без слов, подписи «глава N», Credits.

            3) ТОЧНОСТЬ ТЕКСТА. Исправь явные ошибки распознавания.
               ЖЁСТКОЕ ОГРАНИЧЕНИЕ: не додумывай, не пересказывай, не
               фразеологизмруй и не исправляй орфографию ради красоты.
               Если слово неразборчиво — оставь как распознано, лучше с
               вопросительным знаком. Выдуманное слово хуже опечатки.

            4) НЕ ЛИШНЕЕ. То, что не реплика, перенеси в "dropped" списком
               строками, а не удаляй молча.

            "page" — ровно "$pageName" (не выдумывай имя файла).
            "role" для персонажа — его имя как в сцене, для нарратора
            "narrator", для неизвестного "?".

            ВЕРНИ ТОЛЬКО JSON, без пояснений и без Markdown-заборов:
            {"pages":[{"page":"$pageName","lines":[{"role":"...","text":"...","thought":false,"kept":true}],"dropped":["..."]}]}
            Для добавленных OCR строк добавь поле "draft_text".
        """.trimIndent()
    }
}

package eu.kanade.tachiyomi.data.tts

import android.content.Context
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import logcat.LogPriority
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import okio.ByteString
import tachiyomi.core.common.util.system.logcat
import java.io.File
import java.net.HttpURLConnection
import java.net.URL
import java.security.MessageDigest
import java.util.GregorianCalendar
import java.util.Locale
import java.util.TimeZone
import java.util.UUID
import java.util.concurrent.TimeUnit
import kotlin.coroutines.resume

/**
 * Клиент бесплатной онлайн-озвучки Microsoft Edge (edge-tts): те же WebSocket-
 * endpoint и голоса, что использует «Читать вслух» в браузере Edge.
 *
 * Никакого API-ключа не требуется — только интернет. Голоса отдаются
 * аудио-потоком MP3, который приложение проигрывает тем же плеером, что и
 * остальные сетевые движки (Google Web, ElevenLabs).
 *
 * Протокол (раньше жил в Python-библиотеке rany2/edge-tts):
 *  - список голосов — GET voices/list (парсится строками без библиотек);
 *  - синтез — WebSocket wss://speech.platform.bing.com/.../edge/v1, на вход
 *    speech.config + SSML, на выход бинарные сообщения с MP3-чанками.
 *  - Sec-MS-GEC — SHA-256 от (Unix-время в тиках Windows 1601, округлённое
 *    до 5 минут) + trusted-токен; иначе сервер закрывает соединение.
 *
 * Мультиязычные голоса (ShortName содержит «Multilingual») распознают язык
 * текста автоматически — они отмечены в списке и доступны для любого текста.
 */
object EdgeTts {

    private const val TRUSTED_CLIENT_TOKEN = "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
    /** Разница эпох Unix (1970) и Windows file time (1601), в секундах. */
    private const val WIN_EPOCH = 11_644_473_600L
    private const val CHROMIUM_FULL_VERSION = "143.0.3650.75"
    private const val CHROMIUM_MAJOR = "143"
    private const val SEC_MS_GEC_VERSION = "1-$CHROMIUM_FULL_VERSION"

    private const val BASE_URL =
        "speech.platform.bing.com/consumer/speech/synthesize/readaloud"
    private const val VOICE_LIST_URL =
        "https://$BASE_URL/voices/list?trustedclienttoken=$TRUSTED_CLIENT_TOKEN"
    private const val WSS_URL =
        "wss://$BASE_URL/edge/v1?TrustedClientToken=$TRUSTED_CLIENT_TOKEN"

    /** Голос по умолчанию: русский женский (нейтральный). */
    const val DEFAULT_VOICE = "ru-RU-SvetlanaNeural"

    private const val SSML_BYTE_LIMIT = 3600
    private const val AUDIO_CACHE_FILES = 32
    private const val AUDIO_CACHE_BYTES = 64L * 1024L * 1024L

    private val client by lazy {
        OkHttpClient.Builder()
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(90, TimeUnit.SECONDS)
            .pingInterval(10, TimeUnit.SECONDS)
            .build()
    }

    private val userAgent =
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
            "(KHTML, like Gecko) Chrome/$CHROMIUM_MAJOR.0.0.0 Safari/537.36 " +
            "Edg/$CHROMIUM_MAJOR.0.0.0"

    /** Один голос Edge TTS из публичного списка. */
    data class EdgeVoice(
        val shortName: String,
        val gender: String,
        val locale: String,
        val friendlyName: String,
    ) {
        /** Мультиязычные голоса понимают ЖД текст на любом из больших языков. */
        val multilingual: Boolean get() = shortName.contains("Multilingual", ignoreCase = true)
        val language: String get() = locale.substringBefore('-').lowercase()
        val genderIcon: String get() = when {
            gender.contains("Female", true) -> "♀"
            gender.contains("Male", true) -> "♂"
            else -> "•"
        }
        /** Короткая подпись для списка: название • пол • язык (+ 🌐). */
        val label: String
            get() = buildString {
                append(shortName)
                append(" • ").append(genderIcon)
                append(" ").append(locale)
                if (multilingual) append(" • 🌐 мультиязычный")
            }
    }

    /** Все доступные языки в полученном списке голосов, отсортированы (ru первым). */
    fun languagesOf(voices: List<EdgeVoice>): List<String> = voices
        .map { it.language }
        .distinct()
        .sortedWith(compareBy<String> { it != "ru" }.thenBy { it })

    /** Мультиязычные голоса (понимают любой текст из основных языков). */
    fun multilingualVoices(voices: List<EdgeVoice>): List<EdgeVoice> =
        voices.filter { it.multilingual }

    /**
     * Sec-MS-GEC токен: SHA-256 от (Windows-file-time, округлённый до 5 минут)
     * + trusted-токен. Без него сервер отвечает 403/закрывает вебсокет.
     */
    fun secMsGec(nowEpochSeconds: Long = System.currentTimeMillis() / 1000): String {
        var ticks = nowEpochSeconds + WIN_EPOCH
        ticks -= ticks % 300L
        val windowsTicks = ticks * 10_000_000L
        val digest = MessageDigest.getInstance("SHA-256")
            .digest("$windowsTicks$TRUSTED_CLIENT_TOKEN".toByteArray(Charsets.US_ASCII))
        return digest.joinToString("") { "%02X".format(it.toInt() and 0xFF) }
    }

    /** «Javascript-стиль» дата-строка, которую ждёт сервер в X-Timestamp. */
    private fun jsTimestamp(): String {
        val cal = GregorianCalendar(TimeZone.getTimeZone("UTC"))
        val days = arrayOf("Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat")
        val months = arrayOf("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
        return String.format(
            Locale.US,
            "%s %s %02d %04d %02d:%02d:%02d GMT+0000 (Coordinated Universal Time)",
            days[cal.get(GregorianCalendar.DAY_OF_WEEK) - 1],
            months[cal.get(GregorianCalendar.MONTH)],
            cal.get(GregorianCalendar.DAY_OF_MONTH),
            cal.get(GregorianCalendar.YEAR),
            cal.get(GregorianCalendar.HOUR_OF_DAY),
            cal.get(GregorianCalendar.MINUTE),
            cal.get(GregorianCalendar.SECOND),
        )
    }

    private fun uuidHex(): String = UUID.randomUUID().toString().replace("-", "")

    private fun escapeXml(s: String): String = buildString {
        for (c in s) {
            when (c) {
                '&' -> append("&amp;")
                '<' -> append("&lt;")
                '>' -> append("&gt;")
                '"' -> append("&quot;")
                '\'' -> append("&apos;")
                else -> append(c)
            }
        }
    }

    /**
     * Список ВСЕХ голосов Edge TTS (текущий каталог: ~300 голосов, 50+ языков).
     * Пустой список при ошибке сети/403 — никаких фейковых данных.
     */
    suspend fun fetchVoices(): List<EdgeVoice> = withContext(Dispatchers.IO) {
        runCatching {
            val conn = URL(VOICE_LIST_URL +
                "&Sec-MS-GEC=${secMsGec()}&Sec-MS-GEC-Version=$SEC_MS_GEC_VERSION")
                .openConnection() as HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            conn.setRequestProperty("User-Agent", userAgent)
            conn.setRequestProperty("Authority", "speech.platform.bing.com")
            conn.setRequestProperty("Accept", "*/*")
            conn.setRequestProperty("Sec-Fetch-Site", "none")
            conn.setRequestProperty("Sec-Fetch-Mode", "cors")
            conn.setRequestProperty("Sec-Fetch-Dest", "empty")
            conn.setRequestProperty("Sec-CH-UA-Mobile", "?0")
            if (conn.responseCode !in 200..299) {
                logcat(LogPriority.WARN) { "EdgeTTS voices HTTP ${conn.responseCode}" }
                return@runCatching emptyList<EdgeVoice>()
            }
            val body = conn.inputStream.bufferedReader().readText()
            conn.disconnect()
            val arr = org.json.JSONArray(body)
            buildList {
                for (i in 0 until arr.length()) {
                    val v = arr.optJSONObject(i) ?: continue
                    val short = v.optString("ShortName")
                    if (short.isBlank()) continue
                    val locale = v.optString("Locale").ifBlank { "xx-XX" }
                    add(
                        EdgeVoice(
                            shortName = short,
                            gender = v.optString("Gender"),
                            locale = locale,
                            friendlyName = v.optString("FriendlyName").ifBlank { short },
                        ),
                    )
                }
            }.sortedWith(
                compareBy(
                    { it.friendlyName.contains("Multilingual", true) },
                    { it.locale },
                    { it.shortName },
                ),
            )
        }.getOrElse { error ->
            logcat(LogPriority.WARN, error) { "EdgeTTS voice list fetch failed" }
            emptyList()
        }
    }

    /**
     * Синтез одного текста в файл MP3. [ratePercent] и [pitchHz] — значения
     * prosody от настроек скорости/высоты приложения (0 = обычный голос).
     * Вернёт null при ошибке сети/сервера/пустого результата.
     */
    suspend fun synthesizeToFile(
        context: Context,
        text: String,
        voice: String = DEFAULT_VOICE,
        ratePercent: Int = 0,
        pitchHz: Int = 0,
        useCache: Boolean = false,
    ): File? = withContext(Dispatchers.IO) {
        val cleanText = sanitizeForSsml(text)
        if (cleanText.isBlank()) return@withContext null
        val cacheDir = File(context.cacheDir, "edge_tts").apply { mkdirs() }
        val cached = audioCacheFile(cacheDir, cleanText, voice, ratePercent, pitchHz)
        if (useCache && cached.isFile && cached.length() >= 1024) return@withContext cached
        val target = if (useCache) {
            File.createTempFile("edge_", ".mp3", cacheDir)
        } else {
            File(context.cacheDir, "tts_edge_${System.nanoTime()}.mp3")
        }
        var completed = false
        try {
            target.outputStream().buffered().use { output ->
                for (chunk in chunkForSsml(cleanText)) {
                    val data = speakChunk(chunk, voice, ratePercent, pitchHz, 0)
                    if (data.isEmpty()) {
                        throw IllegalStateException("EdgeTTS returned an empty chunk for $voice")
                    }
                    output.write(data)
                }
            }
            if (!useCache) {
                completed = true
                target
            } else {
                if (!target.renameTo(cached)) {
                    target.copyTo(cached, overwrite = true)
                    target.delete()
                }
                pruneAudioCache(cacheDir)
                if (cached.length() < 1024) {
                    cached.delete()
                    null
                } else {
                    completed = true
                    cached
                }
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "EdgeTTS synthesis failed" }
            null
        } finally {
            if (!completed && target.exists()) target.delete()
        }
    }

    internal fun chunkForSsml(text: String, limit: Int = SSML_BYTE_LIMIT): List<String> {
        if (text.isBlank() || limit <= 0) return emptyList()
        val chunks = mutableListOf<String>()
        var start = 0
        while (start < text.length) {
            while (start < text.length && text[start].isWhitespace()) start++
            if (start >= text.length) break
            if (escapeXml(text.substring(start)).toByteArray(Charsets.UTF_8).size <= limit) {
                chunks += text.substring(start).trim()
                break
            }
            var low = start + 1
            var high = text.length
            var end = start
            while (low <= high) {
                val middle = (low + high) ushr 1
                val size = escapeXml(text.substring(start, middle)).toByteArray(Charsets.UTF_8).size
                if (size <= limit) {
                    end = middle
                    low = middle + 1
                } else {
                    high = middle - 1
                }
            }
            if (end <= start) end = (start + 1).coerceAtMost(text.length)
            val usefulStart = start + (end - start) * 3 / 4
            val whitespace = text.substring(usefulStart, end).lastIndexOfAny(charArrayOf(' ', '\n', '\r', '\t'))
            val cut = if (whitespace >= 0) usefulStart + whitespace + 1 else end
            chunks += text.substring(start, cut).trim()
            start = cut
        }
        return chunks.filter(String::isNotBlank)
    }

    private fun sanitizeForSsml(text: String): String = buildString(text.length) {
        for (char in text) {
            when {
                char == '\n' || char == '\r' || char == '\t' -> append(char)
                char.code in 0..31 || char.code in 127..159 -> Unit
                else -> append(char)
            }
        }
    }.replace("\r\n", "\n").replace('\r', '\n').trim()

    private fun audioCacheFile(
        directory: File,
        text: String,
        voice: String,
        ratePercent: Int,
        pitchHz: Int,
    ): File {
        val source = "$voice|$ratePercent|$pitchHz|$text"
        val digest = MessageDigest.getInstance("SHA-256")
            .digest(source.toByteArray(Charsets.UTF_8))
            .joinToString("") { "%02x".format(it.toInt() and 0xFF) }
        return File(directory, "$digest.mp3")
    }

    private fun pruneAudioCache(directory: File) {
        val files = directory.listFiles { file -> file.isFile && file.extension.equals("mp3", true) }
            ?.sortedBy { it.lastModified() }
            .orEmpty()
        var totalBytes = files.sumOf(File::length)
        var remaining = files.size
        for (file in files) {
            if (remaining <= AUDIO_CACHE_FILES && totalBytes <= AUDIO_CACHE_BYTES) break
            val size = file.length()
            if (file.delete()) {
                totalBytes -= size
                remaining--
            }
        }
    }

    /** Один SSML-запрос на WebSocket, возвращает конкатенированный MP3. */
    private suspend fun speakChunk(
        text: String,
        voice: String,
        ratePercent: Int,
        pitchHz: Int,
        volumePercent: Int,
    ): ByteArray = suspendCancellableCoroutine { cont ->
            val requestId = uuidHex()
            val url = WSS_URL +
                "&Sec-MS-GEC=${secMsGec()}" +
                "&Sec-MS-GEC-Version=$SEC_MS_GEC_VERSION" +
                "&ConnectionId=$requestId"
            val request = Request.Builder()
                .url(url)
                .header("User-Agent", userAgent)
                .header("Pragma", "no-cache")
                .header("Cache-Control", "no-cache")
                .header("Origin", "chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold")
                .header("Sec-WebSocket-Version", "13")
                .header("Cookie", "muid=${uuidHex().uppercase()};")
                .build()
            val ws = client.newWebSocket(request, EdgeSocketListener(
                requestId = requestId,
                voice = voice,
                text = text,
                ratePercent = ratePercent,
                pitchHz = pitchHz,
                volumePercent = volumePercent,
                onResult = { bytes -> if (cont.isActive) cont.resume(bytes) },
                onError = { error ->
                    if (cont.isActive) cont.resume(ByteArray(0))
                    if (error != null) logcat(LogPriority.WARN, error) { "EdgeTTS websocket error" }
                },
            ))
            cont.invokeOnCancellation { ws.cancel() }
        }

    /** Собирает MP3 из бинарных аудио-сообщений WebSocket-соединения. */
    private class EdgeSocketListener(
        private val requestId: String,
        private val voice: String,
        private val text: String,
        private val ratePercent: Int,
        private val pitchHz: Int,
        private val volumePercent: Int,
        private val onResult: (ByteArray) -> Unit,
        private val onError: (Throwable?) -> Unit,
    ) : WebSocketListener() {

        private val audio = java.io.ByteArrayOutputStream()
        private var finished = false

        override fun onOpen(webSocket: WebSocket, response: Response) {
            val ts = jsTimestamp()
            webSocket.send(
                "X-Timestamp:$ts\r\n" +
                    "Content-Type:application/json; charset=utf-8\r\n" +
                    "Path:speech.config\r\n\r\n" +
                    "{\"context\":{\"synthesis\":{\"audio\":{\"metadataoptions\":" +
                    "{\"sentenceBoundaryEnabled\":\"false\",\"wordBoundaryEnabled\":\"true\"}," +
                    "\"outputFormat\":\"audio-24khz-48kbitrate-mono-mp3\"}}}}\r\n",
            )
            val s = escapeXml(text)
            val rate = if (ratePercent >= 0) "+$ratePercent%" else "$ratePercent%"
            val pitch = if (pitchHz >= 0) "+${pitchHz}Hz" else "${pitchHz}Hz"
            val vol = if (volumePercent >= 0) "+$volumePercent%" else "$volumePercent%"
            val language = voice.substringBefore('-', "en").lowercase(Locale.US)
            val ssml =
                "<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' " +
                    "xml:lang='$language'><voice name='${escapeXml(voice)}'>" +
                    "<prosody pitch='$pitch' rate='$rate' volume='$vol'>$s</prosody>" +
                    "</voice></speak>"
            webSocket.send(
                "X-RequestId:$requestId\r\n" +
                    "Content-Type:application/ssml+xml\r\n" +
                    "X-Timestamp:${ts}Z\r\n" +
                    "Path:ssml\r\n\r\n$ssml",
            )
        }

        override fun onMessage(webSocket: WebSocket, text: String) {
            // Path:turn.end — конец аудио для этого запроса.
            if (text.contains("turn.end")) finish(webSocket)
        }

        override fun onMessage(webSocket: WebSocket, bytes: ByteString) {
            val n = bytes.size
            if (n < 2) return
            val headerLength = ((bytes[0].toInt() and 0xFF) shl 8) or (bytes[1].toInt() and 0xFF)
            if (2 + headerLength > n) return
            val header = bytes.substring(2, 2 + headerLength).utf8()
            if (header.contains("Path:audio", ignoreCase = true) &&
                header.contains("Content-Type:audio/mpeg", ignoreCase = true)
            ) {
                // Аудио идёт сразу после заголовка + \r\n\r\n (2 байта).
                val data = bytes.substring(2 + headerLength)
                if (data.size > 0) audio.write(data.toByteArray())
            }
        }

        override fun onClosed(webSocket: WebSocket, code: Int, reason: String) {
            if (!finished) {
                finished = true
                onError(null)
            }
        }

        override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
            if (!finished) {
                finished = true
                onError(t)
            }
        }

        private fun finish(webSocket: WebSocket) {
            if (finished) return
            finished = true
            runCatching { webSocket.close(1000, "ok") }
            onResult(audio.toByteArray())
        }
    }
}

package eu.kanade.tachiyomi.data.tts

import android.content.Context
import eu.kanade.tachiyomi.data.ai.DocExporter
import mihon.domain.ocr.model.OcrPageResult
import java.io.File

/**
 * Собирает распознанный текст главы в единый документ со спикерами.
 *
 * После фонового скана ([eu.kanade.tachiyomi.data.ocr.OcrChapterScanner]) каждая
 * страница кэшируется как [OcrPageResult]. Этот хелпер читает эти кэши,
 * приписывает говорящему пол/голос (через локальную морфологию [LocalSpeakerAi])
 * и отдаёт текст в виде страниц-блоков. Готовый документ можно сохранить как
 * TXT / Markdown, а также выгрузить в PDF или DOCX через существующий
 * [DocExporter] (тот самый, что уже делает PDF/DOCX для AI-чата).
 *
 * Формат «кто говорит»: если пол не определён, реплика идёт как есть; если
 * определён — перед текстом ставится `[Ж]` / `[М]` (голос женский/мужской).
 */
object ChapterOcrTranscript {

    data class PageBlock(
        val pageIndex: Int,
        val title: String,
        val lines: List<SpokenLine>,
    )

    data class SpokenLine(
        val text: String,
        val gender: String?, // "female" | "male" | null
        val narrator: Boolean,
    )

    /**
     * Построить блоки страниц из кэшированных результатов.
     *
     * @param pages результаты OCR по порядку страниц (пустые страницы допустимы —
     *              они будут отмечены как «нет текста», а не выброшены).
     */
    fun build(pages: List<OcrPageResult>, chapterName: String): List<PageBlock> {
        return pages.mapIndexed { index, page ->
            val lines = page.regions
                .map { it.text.trim() }
                .filter { it.isNotBlank() }
                .map { text ->
                    val g = LocalSpeakerAi.guessGenders(listOf(text)).firstOrNull()
                    SpokenLine(
                        text = text,
                        gender = g?.takeIf { it == "female" || it == "male" },
                        narrator = false,
                    )
                }
            PageBlock(
                pageIndex = page.pageIndex,
                title = "$chapterName — страница ${index + 1}",
                lines = lines,
            )
        }
    }

    /** Превращает блоки в читаемый Markdown (заголовок + реплики с [[Ж]]/[[М]]). */
    fun toMarkdown(blocks: List<PageBlock>, title: String): String {
        val sb = StringBuilder()
        sb.append("# $title\n\n")
        blocks.forEach { b ->
            sb.append("## ${b.title}\n\n")
            if (b.lines.isEmpty()) {
                sb.append("_(текст не распознан)_\n\n")
            } else {
                b.lines.forEach { line ->
                    val gender = when (line.gender) {
                        "female" -> "[Ж] "
                        "male" -> "[М] "
                        else -> ""
                    }
                    sb.append("- $gender${line.text}\n")
                }
                sb.append("\n")
            }
        }
        return sb.toString()
    }

    /** Превращает блоки в плоский TXT (просто реплики в порядке чтения). */
    fun toPlainText(blocks: List<PageBlock>, title: String): String {
        val sb = StringBuilder()
        sb.append(title).append("\n").append("=".repeat(title.length)).append("\n\n")
        blocks.forEachIndexed { index, b ->
            sb.append("[${index + 1}] ${b.title}\n")
            b.lines.forEach { line ->
                val gender = when (line.gender) {
                    "female" -> "[Ж] "
                    "male" -> "[М] "
                    else -> ""
                }
                sb.append("  $gender${line.text}\n")
            }
            if (b.lines.isEmpty()) sb.append("  (текст не распознан)\n")
            sb.append("\n")
        }
        return sb.toString()
    }

    /**
     * Сохранить документ в папку экспорта воркспейса.
     *
     * @param format "md" | "txt" | "pdf" | "docx"
     * @return созданный файл.
     */
    fun write(context: Context, blocks: List<PageBlock>, title: String, format: String): File {
        val safeTitle = title.replace(Regex("[^\\p{L}\\p{N} _-]"), "_").take(60)
        val fileName = "$safeTitle.${if (format == "markdown") "md" else format}"
        return when (format) {
            "pdf" -> {
                val items = blocks.map { b ->
                    DocExporter.Item(
                        title = b.title,
                        text = b.lines.joinToString("\n") {
                            val g = when (it.gender) {
                                "female" -> "[Ж] " else -> if (it.gender == "male") "[М] " else ""
                            }
                            g + it.text
                        }.ifBlank { "—" },
                        imagePath = null,
                    )
                }
                DocExporter.exportPdf(context, items, fileName)
            }
            "docx" -> {
                val items = blocks.map { b ->
                    DocExporter.Item(
                        title = b.title,
                        text = b.lines.joinToString("\n") {
                            val g = when (it.gender) {
                                "female" -> "[Ж] " else -> if (it.gender == "male") "[М] " else ""
                            }
                            g + it.text
                        }.ifBlank { "—" },
                        imagePath = null,
                    )
                }
                DocExporter.exportDocx(context, items, fileName)
            }
            else -> {
                // TXT и MD — простые текстовые файлы.
                val text = if (format == "md" || format == "markdown") toMarkdown(blocks, title) else toPlainText(blocks, title)
                File(eu.kanade.tachiyomi.data.ai.AiWorkspace.root(context), "export")
                    .apply { mkdirs() }
                    .let { dir ->
                        File(dir, fileName).apply { writeText(text, Charsets.UTF_8) }
                    }
            }
        }
    }
}

package eu.kanade.tachiyomi.data.tts

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.os.Build
import androidx.core.app.NotificationCompat
import eu.kanade.tachiyomi.R
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat

/**
 * Уведомление «Сейчас читается»: распознанный текст страницы + кнопка
 * «⏹ Остановить» прямо в шторке. Текст остаётся в уведомлении, даже когда
 * озвучка закончилась — можно перечитать.
 */
object TtsReadingNotifier {

    private const val CHANNEL_ID = "yomikai_tts_reading"
    private const val NOTIFICATION_ID = 0x77A1
    private const val ACTION_STOP = "app.yomikai.TTS_STOP"

    private var receiverRegistered = false

    /**
     * Читатель нажал «⏹ Остановить» в шторке.
     *
     * Кнопка раньше только глушила синтез: цикл авточтения продолжал листать
     * главу, кадр за кадром проглатывался в тишину, и читатель получал
     * пролистанную главу вместо остановки. Теперь запрос доходит до цикла
     * через [consumeStopRequest].
     */
    @Volatile
    private var stopRequested = false

    /**
     * Забрать запрос «остановить», если он был. Одноразово.
     *
     * Запрос сбрасывается чтением, а не показом уведомления: показ случается
     * в начале каждого кадра и затер бы ответ, который читатель уже дал.
     */
    fun consumeStopRequest(): Boolean {
        if (!stopRequested) return false
        stopRequested = false
        return true
    }

    private val stopReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context, intent: Intent) {
            if (intent.action == ACTION_STOP) {
                stopRequested = true
                TtsSpeaker.stop()
                dismiss(context)
            }
        }
    }

    /**
     * Лимит текста в уведомлении.
     *
     * Android отбрасывает Notification, чей суммарный размер превышает
     * ~500 КБ (RemoteViews / Bundle), и падает с TransactionTooLargeException
     * либо DeadObjectException, залив logcat простынёй. Полная страница OCR
     * легко даёт несколько тысяч символов, поэтому режем жёстко.
     */
    private const val MAX_NOTIFICATION_TEXT = 800

    /**
     * Показать уведомление о чтении.
     *
     * [pageLabel] — где читатель находится в главе («Страница 3 из 20»).
     * Показывается под заголовком: авточтение читает главу, а не одну
     * страницу, и без такой подсказки шторка выглядит как зависшая на первой.
     */
    fun show(context: Context, text: String, pageLabel: String? = null) {
        if (text.isBlank()) return
        val app = context.applicationContext
        val nm = app.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            nm.createNotificationChannel(
                NotificationChannel(
                    CHANNEL_ID,
                    "Озвучка страниц",
                    NotificationManager.IMPORTANCE_LOW,
                ),
            )
        }

        if (!receiverRegistered) {
            val filter = IntentFilter(ACTION_STOP)
            try {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                    app.registerReceiver(stopReceiver, filter, Context.RECEIVER_NOT_EXPORTED)
                } else {
                    @Suppress("UnspecifiedRegisterReceiverFlag")
                    app.registerReceiver(stopReceiver, filter)
                }
                receiverRegistered = true
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "Failed to register TTS stop receiver" }
            }
        }

        val stopIntent = PendingIntent.getBroadcast(
            app,
            0,
            Intent(ACTION_STOP).setPackage(app.packageName),
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE,
        )

        val safeText = text.take(MAX_NOTIFICATION_TEXT)
        val notification = NotificationCompat.Builder(app, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_mihon)
            .setContentTitle(pageLabel?.let { "🔊 Читается глава · $it" } ?: "🔊 Читается страница")
            .setContentText(safeText.take(120))
            .setStyle(NotificationCompat.BigTextStyle().bigText(safeText))
            .setOnlyAlertOnce(true)
            .setOngoing(false)
            .addAction(0, "⏹ Остановить", stopIntent)
            .build()

        // Без разрешения POST_NOTIFICATIONS (Android 13+) notify() бросает
        // SecurityException; уведомление — не повод ронять читалку.
        try {
            nm.notify(NOTIFICATION_ID, notification)
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "TTS notification rejected" }
        }
    }

    fun dismiss(context: Context) {
        val nm = context.applicationContext
            .getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        nm.cancel(NOTIFICATION_ID)
    }
}

