package eu.kanade.tachiyomi.data.ai

import android.content.Context
import eu.kanade.tachiyomi.util.storage.getUriCompat
import eu.kanade.tachiyomi.util.system.toShareIntent
import logcat.LogPriority
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import java.io.File

/**
 * Навыки, которые агент создаёт сам.
 *
 * Читатель просил инструмент, которого нет, и не хочет ждать, пока его
 * напишут вручную. Навык — это **рецепт**: список шагов из уже встроенных
 * инструментов ([AiAgent] умеет исполнять `@tool`), сохраняемый в
 * `workspace/skills/<имя>.json` и вызываемый одним движением.
 *
 * ## Почему рецепт, а не код
 *
 * Наивный «агент пишет и исполняет свой код» на Android означает либо
 * интерпретатор внутри приложения, либо запуск шелл-скриптов — и то и другое
 * здесь неприемлемо. Рецепт ограничен тем, что уже есть в приложении, поэтому
 * новый навык не может ни уйти в сеть по чужому адресу, ни испортить систему.
 * Всё, что он делает, уже разрешено пользователю отдельными инструментами.
 *
 * Шаги исполняются по порядку, остановившись на первом `error` — чтобы
 * следующий шаг не работал с несуществующим файлом.
 */
object AiSkills {

    /** Один шаг рецепта: имя инструмента и его аргументы. */
    data class Step(val tool: String, val args: Map<String, String>)

    data class Skill(
        val name: String,
        val description: String,
        val steps: List<Step>,
    ) {
        /** Подстановки `{вход}` в аргументах — то, ради чего навык заводят. */
        fun withInput(input: String): Skill = copy(
            steps = steps.map { step ->
                step.copy(args = step.args.mapValues { (_, v) -> v.replace(INPUT_TOKEN, input) })
            },
        )

        companion object {
            const val INPUT_TOKEN = "{вход}"
        }
    }

    private fun dir(context: Context): File =
        File(AiWorkspace.root(context), "skills").apply { mkdirs() }

    private fun fileOf(context: Context, name: String): File =
        File(dir(context), AiWorkspacePaths.sanitize(name) + ".json")

    fun list(context: Context): List<Skill> =
        dir(context).listFiles { f -> f.extension == "json" }
            ?.mapNotNull { runCatching { fromJson(JSONObject(it.readText())) }.getOrNull() }
            ?.sortedBy { it.name }
            .orEmpty()

    fun get(context: Context, name: String): Skill? =
        fileOf(context, name).takeIf { it.isFile }
            ?.let { runCatching { fromJson(JSONObject(it.readText())) }.getOrNull() }

    fun save(context: Context, s: Skill): Boolean {
        if (s.name.isBlank() || s.steps.isEmpty()) return false
        return runCatching {
            fileOf(context, s.name).writeText(toJson(s).toString(2))
            true
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "AiSkills save failed for ${s.name}" }
            false
        }
    }

    fun delete(context: Context, name: String): Boolean = fileOf(context, name).delete()

    /**
     * Разбор описания навыка от модели.
     *
     * Модель присылает JSON одним куском, и разбирать его надёжнее вручную с
     * проверкой каждого поля: упавший `optJSONArray` молча оставил бы навык
     * без шагов, и он «сохранился», но ничего не делает.
     */
    fun parse(raw: String): Skill? = runCatching {
        val obj = JSONObject(raw.trim().removePrefix("```json").removePrefix("```").removeSuffix("```").trim())
        val name = obj.optString("name").trim()
        if (name.isBlank()) return null
        val arr = obj.optJSONArray("steps") ?: return null
        val steps = buildList {
            for (i in 0 until arr.length()) {
                val s = arr.optJSONObject(i) ?: continue
                val tool = s.optString("tool").trim()
                if (tool.isBlank()) continue
                val argsObj = s.optJSONObject("args")
                val args = buildMap {
                    if (argsObj != null) {
                        for (k in argsObj.keys()) put(k, argsObj.optString(k))
                    }
                }
                add(Step(tool, args))
            }
        }
        if (steps.isEmpty()) return null
        Skill(name, obj.optString("description").trim(), steps)
    }.getOrNull()

    /** Короткий список навыков для промпта: имена и что они делают. */
    fun promptLines(context: Context): String {
        val list = list(context)
        if (list.isEmpty()) {
            return "Навыков пока нет. Создать новый: skill_create {\"name\":\"...\",\"description\":\"...\",\"steps\":[{\"tool\":\"write_file\",\"args\":{...}}]}"
        }
        return "Свои навыки (skill_run {\"name\":\"...\",\"input\":\"...\"}):\n" +
            list.joinToString("\n") { "• ${it.name} — ${it.description} (шагов: ${it.steps.size})" }
    }

    /** Разбор одного шага в вызов инструмента. */
    fun toCall(step: Step): AiAgent.ToolCall {
        val args = JSONObject()
        step.args.forEach { (k, v) -> args.put(k, v) }
        return AiAgent.ToolCall(step.tool, args)
    }

    private fun toJson(s: Skill): JSONObject = JSONObject().apply {
        put("name", s.name)
        put("description", s.description)
        put(
            "steps",
            JSONArray().apply {
                s.steps.forEach { step ->
                    put(
                        JSONObject().apply {
                            put("tool", step.tool)
                            put(
                                "args",
                                JSONObject().apply { step.args.forEach { (k, v) -> put(k, v) } },
                            )
                        },
                    )
                }
            },
        )
    }

    private fun fromJson(obj: JSONObject): Skill {
        val arr = obj.optJSONArray("steps") ?: JSONArray()
        val steps = buildList {
            for (i in 0 until arr.length()) {
                val s = arr.optJSONObject(i) ?: continue
                val tool = s.optString("tool").trim()
                if (tool.isBlank()) continue
                val argsObj = s.optJSONObject("args")
                val args = buildMap {
                    if (argsObj != null) {
                        for (k in argsObj.keys()) put(k, argsObj.optString(k))
                    }
                }
                add(Step(tool, args))
            }
        }
        return Skill(obj.optString("name"), obj.optString("description"), steps)
    }

    /**
     * Открыть созданный файл. Отдельная функция, а не кнопка в списке, потому
     * что «отправить» и «открыть» — разные намерения: первое делится файлом
     * наружу, второе показывает его в галерее/читалке.
     */
    fun openIntent(context: Context, f: File) = runCatching {
        f.getUriCompat(context).toShareIntent(
            context = context,
            type = "application/octet-stream",
            message = f.name,
        )
    }.getOrNull()
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import eu.kanade.tachiyomi.data.tts.TtsSpeaker
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.delay
import org.json.JSONObject
import java.io.File

/**
 * Озвучка страницы и главы В ФАЙЛ — инструменты, которых в приложении не было.
 *
 * Почему они живут здесь, а не в ReaderActivity: «прочти книгу и пришли
 * аудиофайл» — это не то же самое, что озвучка в колонке. Авточтение
 * (`speak_chapter`) и кнопка «озвучить страницу» (`speak_page`) играют текст
 * В ЧИТАЛКЕ и возвращаются мгновенно, файла за ними не остаётся, поэтому
 * читатель просил файл и не получал его. Единственный инструмент, который
 * делал mp3, — `render_audio`, а он умеет только произвольный ТЕКСТ: прочитать
 * им страницу нельзя.
 *
 * Здесь оба новых действия идут в обход регистрации в Activity: текст страницы
 * берётся ТЕМ ЖЕ OCR, что у `page_text` (реестр [ReaderAiActions]), синтез —
 * ТЕМ ЖЕ, что у `render_audio` ([AiChatTools], Edge TTS в workspace/audio/).
 * Новый аудио-бэкенд не изобретается, регистрация в ReaderActivity не нужна.
 */
object ReaderAudioExport {

    const val ACTION_PAGE_AUDIO = "page_audio"
    const val ACTION_CHAPTER_AUDIO = "chapter_audio"
    const val ACTION_WAIT_IDLE = "wait_idle"

    /** Действия, которые обслуживает этот объект, а не реестр [ReaderAiActions]. */
    val ACTION_NAMES = listOf(ACTION_PAGE_AUDIO, ACTION_CHAPTER_AUDIO, ACTION_WAIT_IDLE)

    /** Результат действия: текст для модели и, если получилось, mp3 для чата. */
    data class Outcome(val output: String, val file: File? = null)

    /**
     * Служебные ответы реестра читалки, которые не являются текстом страницы.
     *
     * `page_text` на пустом кадре отдаёт не пустую строку, а словесную заглушку
     * «На странице не распознан текст». Синтезировать её — значит озвучить
     * читателю техническое сообщение вместо книги.
     */
    private val NOT_TEXT = listOf("не распознан текст", "не удалось получить кадр")

    /**
     * Сколько страниц главы озвучивать по умолчанию. Много — долго: на каждой
     * странице отдельный вызов OCR плюс синтез, а Edge TTS едет по accumulating
     * тексту. Читатель «озвучь мне главу» обычно имеет в виду текущую главу, а
     * не том на 200 кадров, поэтому потолок небольшой и его видно в ответе.
     */
    private const val DEFAULT_MAX_PAGES = 20
    private const val MAX_PAGES_LIMIT = 60

    /**
     * Бюджет сбора текста главы. Синтез длинного текста идёт ПОСЛЕ сбора, и
     * таймаут инструмента в [AiAgent] общий, поэтому сборка обязана закончиться
     * сама и вернуть что успела, а не висеть до отсечки.
     */
    private const val DEFAULT_BUDGET_MS = 240_000L
    private const val MAX_BUDGET_MS = 600_000L

    /**
     * Потолок собранного текста в символах.
     *
     * Синтез Edge TTS идёт последовательно по чанкам, и глава на 200 кадров —
     * это десятки мегабайт аудио и десятки минут работы. Обрезаем на ~20 000
     * символов (примерно 25 минут озвучки) и честно пишем в ответе, что текст
     * обрезан: лучше короткий целый файл, чем mp3, который не дождался.
     */
    private const val MAX_TEXT_CHARS = 20_000

    /** Пауза после turn_page: страница должна отрисоваться до следующего OCR. */
    private const val PAGE_SETTLE_MS = 900L

    /** Как часто опрашиваем движок озвучки в wait_idle. */
    private const val POLL_MS = 250L

    /**
     * Сколько непрерывной тишины считаем концом озвучки.
     *
     * Не 0: между страницами авточтения движок замолкает примерно на 1.3 с
     * (листание + отрисовка + захват кадра), и нулевой порог объявил бы конец
     * чтения на середине главы. 3 секунды тишины подряд — уже не «пауза между
     * репликами», а реальная остановка.
     */
    private const val QUIET_SETTLE_MS = 3_000L

    /** Сколько ждать начала речи, если `speak_page` только что вернулся. */
    private const val DEFAULT_START_MS = 6_000L

    private const val DEFAULT_WAIT_MS = 60_000L

    /**
     * Выполнить действие. null — действие не наше, вызывающий код отдаёт его
     * в реестр [ReaderAiActions] как раньше.
     */
    suspend fun run(context: Context, action: String, args: JSONObject): Outcome? = when (action) {
        ACTION_PAGE_AUDIO -> pageAudio(context, args)
        ACTION_CHAPTER_AUDIO -> chapterAudio(context, args)
        ACTION_WAIT_IDLE -> waitIdle(args)
        else -> null
    }

    /**
     * MP3 текущей страницы.
     *
     * Текст берётся из `page_text` — это ровно тот же кадр и тот же OCR, что
     * у `see_page`, новый распознаватель не заводится. Если модель уже
     * получила текст страницы и не хочет повторного OCR, может передать его
     * аргументом `text`.
     */
    private suspend fun pageAudio(
        context: Context,
        args: JSONObject,
    ): Outcome {
        val own = args.optString("text").trim()
        val text = if (own.isNotBlank()) own else pageText()
        if (isFailure(text)) return Outcome(text)
        if (isNotText(text)) {
            return Outcome("ОШИБКА: на текущей странице не распознан текст — озвучивать нечего")
        }
        val name = args.optString("name").ifBlank { defaultName("страница") }
        val voice = args.optString("voice").ifBlank { null }
        val rendered = AiChatTools.renderAudio(context, text, voice, name)
        return Outcome(
            "Страница озвучена в файл. ${rendered.output}",
            rendered.file,
        )
    }

    /**
     * MP3 главы.
     *
     * Текста главы у агента нет и взять его больше неоткуда: `book_recall`
     * хранит правила и заметки, а не содержимое страниц. Поэтому глава
     * собирается существующими средствами — `page_text` на текущей странице и
     * `turn_page` дальше, — и это описано в промпте, чтобы модель не пыталась
     * листать вместо инструмента.
     *
     * Позиция читателя восстанавливается: после сбора возвращаем её на
     * исходную страницу, иначе книга осталась бы на середине главы.
     */
    private suspend fun chapterAudio(
        context: Context,
        args: JSONObject,
    ): Outcome {
        val scope = args.optString("scope").trim().lowercase()
        if (scope == "page" || scope == "страница") {
            return pageAudio(context, args)
        }

        val maxPages = args.optInt("max_pages", DEFAULT_MAX_PAGES)
            .coerceIn(1, MAX_PAGES_LIMIT)
        val budgetMs = args.optLong("budget_ms", DEFAULT_BUDGET_MS)
            .coerceIn(20_000L, MAX_BUDGET_MS)

        val started = System.currentTimeMillis()
        val start = pagePosition()
            ?: return Outcome("ОШИБКА: читалка не ответила про страницы. ${ReaderAiActions.describe()}")

        val collected = StringBuilder()
        var page = start.current
        var emptyInARow = 0
        var taken = 0
        var cutByBudget = false
        var cutByText = false

        loop@ while (taken < maxPages) {
            if (System.currentTimeMillis() - started > budgetMs) {
                cutByBudget = true
                break@loop
            }
            val text = pageText()
            if (isFailure(text)) {
                if (taken == 0) {
                    // Сбор не начался, но страницу мы уже могли пролистать —
                    // возвращать надо и на этом пути, иначе читатель останется
                    // не там, где открыл книгу.
                    val back = restorePage(start.current)
                    val where = if (back) {
                        "Читалка возвращена на страницу ${start.current}."
                    } else {
                        "ВНИМАНИЕ: вернуть книгу на страницу ${start.current} не вышло — проверьте, где она остановилась."
                    }
                    return Outcome("$text $where")
                }
                // Страница не распозналась — это не повод бросать главу, но
                // три подряд пустых кадра означают, что дальше идти незачем.
                emptyInARow++
                if (emptyInARow >= 3) break@loop
            } else if (isNotText(text)) {
                emptyInARow++
                if (emptyInARow >= 3) break@loop
            } else {
                emptyInARow = 0
                collected.append(text.trim()).append("\n\n")
                taken++
                if (collected.length >= MAX_TEXT_CHARS) {
                    cutByText = true
                    break@loop
                }
            }

            if (start.total > 0 && page >= start.total) break@loop
            val turned = turn("next")
            if (isFailure(turned) || turned.contains("Нельзя перейти") ||
                turned.contains("прыгать на саму страницу")
            ) {
                break@loop
            }
            val next = firstNumber(turned)
            if (next == null || next == page) break@loop
            page = next
            delay(PAGE_SETTLE_MS)
        }

        val restored = restorePage(start.current)

        if (collected.isBlank()) {
            return Outcome("ОШИБКА: текст главы не распознан — озвучивать нечего")
        }
        val name = args.optString("name").ifBlank { defaultName("глава") }
        val voice = args.optString("voice").ifBlank { null }
        val rendered = AiChatTools.renderAudio(context, collected.toString(), voice, name)
        val tail = buildString {
            append("Собрано страниц: $taken")
            if (start.total > 0) append(" из ${start.total}")
            // Не обещаем возврата на страницу, если он не удался: читатель
            // должен знать, что книга осталась там, где остановилась.
            if (restored) {
                append(". Читалка возвращена на страницу ${start.current}.")
            } else {
                append(". ВНИМАНИЕ: вернуть книгу на страницу ${start.current} не вышло — она осталась там, где остановилась.")
            }
            if (cutByText) {
                append(" Текст обрезан на ${MAX_TEXT_CHARS} символах — остальное добери вторым вызовом.")
            }
            if (cutByBudget) append(" Остановлено по лимиту времени, остальное добери вторым вызовом.")
        }
        return Outcome("$tail ${rendered.output}", rendered.file)
    }

    /**
     * Дождаться конца текущей озвучки.
     *
     * Без этого инструмента модель не может читать книгу постранично:
     * `speak_page` возвращается мгновенно (озвучка только запускается), и
     * следующий вызов обрывает предыдущую. Здесь мы честно ждём и говорим, что
     * вышло: «тишина» (закончилось или не началось) либо «идёт» (ещё звучит).
     */
    private suspend fun waitIdle(args: JSONObject): Outcome {
        val waitMs = args.optLong("wait_ms", DEFAULT_WAIT_MS).coerceIn(1_000L, 900_000L)
        val startMs = args.optLong("start_ms", DEFAULT_START_MS).coerceIn(0L, waitMs)
        val quietMs = args.optLong("quiet_ms", QUIET_SETTLE_MS).coerceIn(500L, 30_000L)

        val started = System.currentTimeMillis()
        var heard = false
        var quietSince = 0L
        while (true) {
            val now = System.currentTimeMillis()
            val elapsed = now - started
            if (TtsSpeaker.isSpeaking) {
                heard = true
                quietSince = 0L
            } else {
                if (quietSince == 0L) quietSince = now
                val quiet = now - quietSince
                if (heard && quiet >= quietMs) {
                    return Outcome("Тишина: озвучка закончилась (ждал ${elapsed / 1000} с). Можно листать дальше.")
                }
                if (!heard && elapsed >= startMs) {
                    return Outcome(
                        "Тишина: озвучка так и не началась за ${startMs / 1000} с — " +
                            "на странице, похоже, нечего читать. Листай сам через turn_page.",
                    )
                }
            }
            if (elapsed >= waitMs) {
                return Outcome(
                    "Идёт: через ${waitMs / 1000} с озвучка всё ещё звучит. " +
                        "Позови wait_idle ещё раз или прерви через stop_speak.",
                )
            }
            delay(POLL_MS)
        }
    }

    /** Текст текущей страницы существующим OCR читалки. */
    private suspend fun pageText(): String =
        ReaderAiActions.run("page_text", JSONObject()).trim()

    private suspend fun turn(target: String): String =
        ReaderAiActions.run("turn_page", JSONObject().put("to", target)).trim()

    private data class Position(val current: Int, val total: Int)

    /** «Страниц в главе: 20, открыта: 3» → current=3, total=20. */
    private suspend fun pagePosition(): Position? {
        val raw = ReaderAiActions.run("page_count", JSONObject()).trim()
        if (isFailure(raw)) return null
        val numbers = raw.matchNumbers()
        val total = numbers.getOrNull(0) ?: 0
        val current = numbers.getOrNull(1) ?: 1
        return Position(current = current.coerceAtLeast(1), total = total.coerceAtLeast(0))
    }

    /**
     * Вернуть книгу на исходную страницу.
     *
     * Отмена здесь намеренно ловится: неудалось вернуть страницу — не повод
     * выбрасывать уже собранный текст и mp3, о котором читатель просил.
     * Но сказать «вернулась» при этом нельзя, поэтому возвращаем признак.
     */
    private suspend fun restorePage(page: Int): Boolean {
        return try {
            turn(page.toString())
            delay(PAGE_SETTLE_MS)
            true
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            false
        }
    }

    /** Реестр читалки возвращает и служебные строки («ОШИБКА действия…»). */
    private fun isFailure(text: String): Boolean =
        text.startsWith("ОШИБКА") || text.startsWith("ДЕЙСТВИЕ")

    /** Служебная заглушка читалки вместо текста страницы. */
    private fun isNotText(text: String): Boolean =
        text.isBlank() || NOT_TEXT.any { text.contains(it, ignoreCase = true) }

    /**
     * Имя файла по умолчанию. С хвостом времени, иначе два вызова подряд
     * («озвучь страницу», «озвучь ещё») затёрли бы друг друга и читатель получил
     * бы один файл вместо двух.
     */
    private fun defaultName(prefix: String): String =
        "${prefix}_${System.currentTimeMillis() / 1000 % 100_000}"

    private fun String.matchNumbers(): List<Int> =
        Regex("\\d+").findAll(this).mapNotNull { it.value.toIntOrNull() }.toList()

    private fun firstNumber(text: String): Int? = text.matchNumbers().firstOrNull()
}

package eu.kanade.tachiyomi.data.ai

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat

/**
 * Суб-агент «сюжет по мере чтения».
 *
 * Копит произнесённые реплики и просит модель пересказать прочитанное от
 * первого лица — так, как это пересказал бы человек, который там был: с
 * эмоциями, с оценкой, а не как протокол.
 *
 * Почему «по мере чтения», а не по итогам главы: пересказ берётся из того же
 * текста, что и озвучка, поэтому он появляется, пока читатель слушает, и не
 * ждёт конца. Честная оговорка — качество пересказа упирается в качество
 * распознавания: если в тексте «ХО-РОШО», то и в пересказе будет «ХО-РОШО».
 * Поэтому агент получает ровно то, что было произнесено, без «улучшений».
 *
 * Ничего не выдумывает на своей стороне: пустой ответ модели — это пустой
 * ответ, а не текст «похоже, глава про…».
 */
class ReadingPlotAgent(
    /**
     * Хранилище пересказа по книгам.
     *
     * Файл, а не настройка: ключ настройки должен быть известен на этапе
     * компиляции, а книга меняется. Кэш настроек для этого не годится.
     */
    private val store: PlotStore,
    /**
     * Есть ли ключ ИИ.
     *
     * Проверка ключа вне агента и через лямбду, а не прямой доступ к
     * настройкам: иначе агент нельзя было бы проверить тестом вовсе — в
     * app-модуле Injekt не поднят, а именно это требование (не выдумывать
     * пересказ без модели) важнее всего остального в классе.
     */
    private val aiKeyPresent: () -> Boolean,
) {

    /** Состояние вкладки «Сюжет». */
    data class State(
        /** Текст пересказа; пусто — пересказа ещё нет. */
        val text: String = "",
        /** Сколько реплик учтено. */
        val heard: Int = 0,
        /** Идёт ли запрос к модели. */
        val thinking: Boolean = false,
        /** Причина, по которой пересказа нет (нет ключа, нет текста, ошибка). */
        val reason: String? = null,
        /** Модель, которая ответила. */
        val model: String = "",
        /**
         * Размышления модели, если она их вернула.
         *
         * Раньше поле приходило и молча выбрасывалось: читатель видел только
         * итог и не мог понять, откуда он. Теперь оно лежит в состоянии и
         * показывается по кнопке — тем же приёмом, что «Размышления ▸» в чате.
         */
        val reasoning: String = "",
    )

    private val _state = MutableStateFlow(State())
    val state = _state.asStateFlow()

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    /** Реплики текущей главы; последние и уходят в модель. */
    private val heard = ArrayDeque<String>()

    /** Идёт ли пересказ — повторный запрос во время него не запускаем. */
    private var requesting = false

    /**
     * Текущий запрос пересказа.
     *
     * Держать его надо было, чтобы «Стоп» действительно отменял запрос: у
     * агента был только флаг `requesting`, который запрещал новый запрос, но
     * ничего не отменял — и пересказ дописывался после остановки чтения.
     */
    @Volatile
    private var recapJob: kotlinx.coroutines.Job? = null

    /**
     * Учесть произнесённую реплику и, когда набралось достаточно, обновить
     * пересказ.
     *
     * Обновление не на каждую реплику: это запрос к модели, и частота здесь
     * задаёт и стоимость, и то, насколько плавно выглядит текст. Пересказ
     * собирается заново из накопленного, поэтому он не «размазывается».
     */
    fun onSpoken(line: String, bookId: Long?) {
        val text = line.trim()
        if (text.isEmpty() || bookId == null) return
        synchronized(heard) {
            // Один и тот же бабл повторно не считается: страница может
            // вернуться в кадр, и пересказ рос бы от дублей.
            if (heard.isNotEmpty() && heard.last() == text) return
            heard.addLast(text)
            while (heard.size > MAX_LINES) heard.removeFirst()
            _state.value = _state.value.copy(heard = heard.size)
        }
        if (snapshot().size >= MIN_LINES_FOR_RECAP) requestRecap(bookId)
    }

    /**
     * Показать сохранённый пересказ книги.
     *
     * Читатель возвращается к книге — и видит то, что уже было написано, а не
     * пустую вкладку до первого запроса к модели.
     */
    fun loadFor(bookId: Long?) {
        val id = bookId ?: return
        val saved = store.read(id)
        if (saved.isNotBlank()) {
            _state.value = _state.value.copy(text = saved)
        }
    }

    /** Перезапуск для новой главы: пересказ старой книги не должен висеть. */
    fun reset() {
        synchronized(heard) { heard.clear() }
        recapJob?.cancel()
        recapJob = null
        requesting = false
        currentBookId = null
        _state.value = State()
    }

    /**
     * Остановить идущий запрос пересказа.
     *
     * Отдельный публичный метод, а не только сброс флага: иначе «Стоп» в
     * консоли останавливал агента и чтение, а пересказ тем временем дописывался
     * уже после остановки — и панель «Сюжет» менялась на живого читателя.
     *
     * @return true, если запрос был и действительно отменён.
     */
    fun cancel(): Boolean {
        val job = recapJob
        if (job == null || !job.isActive) return false
        job.cancel()
        // Одной отмены корутины мало: запрос висит в блокирующем сокете.
        AiAssistant.abortActiveRequests("отмена пересказа")
        _state.value = _state.value.copy(thinking = false, reason = "Остановлено")
        AiConsole.user("Сюжет: запрос пересказа отменён")
        return true
    }

    /** Запросить пересказ принудительно (кнопка «обновить»). */
    fun refresh(bookId: Long?) {
        if (bookId == null) {
            _state.value = _state.value.copy(reason = "Книга не открыта")
            return
        }
        if (snapshot().isEmpty()) {
            _state.value = _state.value.copy(reason = "Пока нечего пересказывать: не озвучено ни одной реплики")
            return
        }
        requestRecap(bookId)
    }

    private fun snapshot(): List<String> = synchronized(heard) { heard.toList() }

    /** Книга, для которой считается пересказ (задаётся при refresh). */
    @Volatile
    private var currentBookId: Long? = null

    private fun requestRecap(bookId: Long) {
        currentBookId = bookId
        val lines = snapshot()
        if (lines.isEmpty() || requesting) return
        if (!runCatching(aiKeyPresent).getOrDefault(false)) {
            _state.value = _state.value.copy(reason = "Нет ключа ИИ: пересказ пишет модель, а не приложение")
            return
        }
        requesting = true
        _state.value = _state.value.copy(thinking = true, reason = null)
        AiConsole.note(
            title = "Сюжет: запрошен пересказ",
            detail = "реплик в накопленном: ${lines.size} · книга $bookId",
        )
        recapJob = scope.launch {
            try {
                val reply = AiAssistant.chatFull(
                    userPrompt = prompt(lines),
                    systemPrompt = SYSTEM,
                    maxTokens = MAX_TOKENS,
                )
                val text = reply?.content?.trim().orEmpty()
                if (text.isEmpty()) {
                    // Модель не ответила содержательно — показываем честную
                    // причину, а не правдоподобный текст.
                    val onlyReasoning = reply?.reasoning?.isNotBlank() == true
                    _state.value = _state.value.copy(
                        thinking = false,
                        reason = if (onlyReasoning) {
                            "Модель вернула только размышления, без текста пересказа"
                        } else {
                            "Модель не ответила"
                        },
                    )
                    AiConsole.note(
                        title = "Сюжет: пересказ не получен",
                        detail = if (onlyReasoning) {
                            "модель вернула только размышления, без текста"
                        } else {
                            "модель не ответила"
                        },
                        level = AiConsole.Level.WARN,
                    )
                } else {
                    // Пересказ сразу пишется на диск: закрытие читалки не
                    // должна стирать работу, за которую заплатили запросом.
                    runCatching { store.write(currentBookId ?: 0L, text) }
                        .onFailure { logcat(LogPriority.WARN, it) { "Plot save failed" } }
                    _state.value = _state.value.copy(
                        text = text,
                        thinking = false,
                        reason = null,
                        model = reply?.model.orEmpty(),
                        reasoning = reply?.reasoning.orEmpty(),
                    )
                    AiConsole.note(
                        title = "Сюжет: пересказ готов",
                        detail = "модель ${reply?.model.orEmpty()} · символов ${text.length}",
                        level = AiConsole.Level.OK,
                    )
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "Reading plot recap failed" }
                _state.value = _state.value.copy(thinking = false, reason = "Ошибка: ${e.message}")
            } finally {
                requesting = false
            }
        }
    }

    companion object {
        /**
         * Промпт пересказа.
         *
         * Живёт в companion, а не в инстансе: он не читает настроек и не
         * держит состояния, а проверяться должен без Injekt и без «ключа» —
         * иначе главное требование к нему (не выдумывать сюжет) осталось бы
         * непроверяемым.
         */
        fun prompt(lines: List<String>): String = buildString {
    appendLine("Ниже реплики, произнесённые при чтении страниц манги/комикса по порядку.")
    appendLine("Перескажи это как человек, который там был: от первого лица, с эмоциями,")
    appendLine("с оценкой того, что происходило, и с тем, что чувствовали герои.")
    appendLine("Это пересказ для читателя, а не протокол и не список реплик.")
    appendLine("Опирайся ТОЛЬКО на эти строки: не додумывай сюжет, событий и персонажей,")
    appendLine("о которых в них нет. Орфографию и ошибки распознавания исправляй молча.")
    appendLine()
    appendLine("РЕПЛИКИ:")
    lines.forEach { appendLine("- $it") }
    appendLine()
    appendLine("Пиши связным текстом от первого лица, 3-6 абзацев. Без заголовков и списков.")
        }

        /** Сколько последних реплик уходит в пересказ. */
        private const val MAX_LINES = 120

        /** С какого числа реплик пересказ имеет смысл. */
        private const val MIN_LINES_FOR_RECAP = 6

        private const val MAX_TOKENS = 900

        private val SYSTEM =
            "Ты — читатель манги, который пересказывает услышанное другу. " +
                "Пишешь живым русским языком, от первого лица, с эмоциями. " +
                "Не выдумываешь того, чего в репликах нет."
    }
}

package eu.kanade.tachiyomi.data.ai

import java.io.File

/**
 * Обзор workspace: что вообще лежит в папке и как это прочитать целиком.
 *
 * Читатель просил, чтобы агент «видел сразу всё, что в воркспейсе, анализировал
 * по очереди и задавал уточняющие вопросы». Раньше у агента был только
 * `read_file` по одному файлу: чтобы понять, что есть, нужно было угадать имя
 * и проверить всё подряд, а на несуществующем файле он получал «Файл не
 * найден» и строил выводы по неполной картине.
 *
 * Здесь две чистые функции (без `Context`, с `File` вместо него) — их можно
 * проверить обычными unit-тестами на JVM, и в них же живёт главное: **бюджет
 * символов**. Список из сотни файлов, выведенный в ответ целиком, съедает
 * контекст хода, после которого модель начинает отвечать мусором, поэтому
 * список обрезается по лимиту и честно говорит, что не показал.
 */
object AiWorkspaceSurvey {

    /** Сколько символов отдаём под один обзор по умолчанию. */
    const val DEFAULT_TREE_BUDGET = 6_000

    /** Сколько символов текста читать за один пакетный вызов. */
    const val DEFAULT_READ_BUDGET = 12_000

    /**
     * Дерево файлов: папки и файлы с размерами, от самых свежих.
     *
     * @param subdir подкаталог относительно корня, "" или "." — весь корень.
     * @param limit максимум строк, даже если символы ещё остались.
     * @param maxBudget обрезка по символам.
     */
    fun renderTree(root: File, subdir: String = "", limit: Int = 200, maxBudget: Int = DEFAULT_TREE_BUDGET): String {
        val base = resolveDir(root, subdir) ?: return "Каталог не найден: $subdir"
        val entries = base.walkTopDown()
            .onEnter { it.canRead() }
            .filter { it != base }
            .sortedWith(
                compareBy(
                    { it.path.count { ch -> ch == '/' || ch == java.io.File.separatorChar } },
                    { it.name.lowercase() },
                ),
            )
            .toList()

        if (entries.isEmpty()) return "В каталоге ${describe(root, base)} пусто"

        val sb = StringBuilder("В папке ${describe(root, base)} — ${entries.size} объект(ов):\n")
        var shown = 0
        var truncated = false
        // Место под завершающую пометку резервируем заранее, иначе она сама
        // вылезет за бюджет: бюджет — это предел ответа модели, а не «список
        // плюс ещё немножка».
        val reserve = 70 + entries.size.toString().length
        for (f in entries) {
            if (shown >= limit) {
                truncated = true
                break
            }
            val rel = relative(root, f)
            val line = buildString {
                append("  ")
                append(rel)
                if (f.isDirectory) {
                    append('/')
                } else {
                    append(" — ")
                    append(f.length() / 1024)
                    append(" КБ")
                }
            }
            // Обрезаем по символам, но не посреди строки: недописанный путь
            // хуже, чем лишняя строка в ответе.
            if (sb.length + line.length + 1 + reserve > maxBudget) {
                truncated = true
                break
            }
            sb.append(line).append('\n')
            shown++
        }
        if (truncated) {
            sb.append("… показано $shown из ${entries.size}. Смотри по частям: workspace_list с path.")
        }
        return sb.toString().trimEnd()
    }

    /**
     * Чтение нескольких файлов по очереди в пределах бюджета символов.
     *
     * Порядок сохраняется: для книги «глава 1 → глава 2» это важно, а сортировка
     * по имени переставляла бы их произвольно. Файл, который не влез в бюджет,
     * помечается, а не молча пропускается — иначе агент решит, что прочитал всё.
     */
    fun readMany(root: File, names: List<String>, budget: Int = DEFAULT_READ_BUDGET): String {
        if (names.isEmpty()) return "Не указано ни одного файла"
        val sb = StringBuilder()
        var spent = 0
        for (name in names) {
            val f = resolveFile(root, name)
            if (f == null || !f.isFile) {
                sb.append("— $name: НЕ НАЙДЕН\n")
                continue
            }
            if (f.extension.lowercase() in IMAGE_EXT) {
                // Раньше здесь было «я не вижу картинки». Это неправда: и
                // read_file, и see_image спрашивают vision-модель. Одно
                // сообщение говорило «не вижу», другое — «спрошу», и модель
                // верила тому, что прочитала последним.
                sb.append("— $name: изображение ${f.length() / 1024} КБ; текста нет. ")
                sb.append("Спросить vision можно see_image {\"name\":\"$name\",\"question\":\"что на ней\"}, ")
                sb.append("прочитать — read_file\n")
                continue
            }
            val text = runCatching { f.readText() }.getOrElse {
                sb.append("— $name: НЕ ЧИТАЕТСЯ\n")
                continue
            }
            val header = "— $name (${text.length} симв.)\n"
            val room = budget - spent - header.length
            if (room <= 0) {
                sb.append("— $name: не вошёл в бюджет чтения, читай отдельно read_file\n")
                continue
            }
            val body = if (text.length > room) text.take(room) + "\n… (файл обрезан по бюджету)" else text
            sb.append(header).append(body).append('\n')
            spent += header.length + body.length
            if (spent >= budget) {
                val rest = names.drop(names.indexOf(name) + 1)
                if (rest.isNotEmpty()) {
                    sb.append("Бюджет чтения исчерпан, не прочитано: ${rest.joinToString(", ")}")
                }
                break
            }
        }
        return sb.toString().trimEnd()
    }

    private val IMAGE_EXT = setOf("png", "jpg", "jpeg", "webp", "gif", "bmp")

    private fun resolveDir(root: File, subdir: String): File? {
        val clean = subdir.trim().trimStart('/')
        if (clean.isEmpty() || clean == ".") return root
        val f = File(root, clean)
        // Тот же запрет выхода за workspace, что и в resolveFile: иначе
        // `{"path": "../../.."}` перечислял содержимое /sdcard и приватных
        // папок приложения.
        val contained = runCatching {
            val base = root.canonicalFile
            val target = f.canonicalFile
            target == base || target.path.startsWith(base.path + File.separator)
        }.getOrDefault(false)
        return f.takeIf { contained && it.isDirectory }
    }

    private fun resolveFile(root: File, name: String): File? {
        val clean = name.trim().trimStart('/')
        if (clean.isEmpty()) return null
        val f = File(root, clean)
        // Выход за пределы workspace запрещён: путь из модели не должен
        // приводить к файлам приложения.
        return runCatching {
            val base = root.canonicalFile
            val target = f.canonicalFile
            if (target == base || target.path.startsWith(base.path + File.separator)) f else null
        }.getOrNull()
    }

    private fun relative(root: File, f: File): String = runCatching {
        f.absolutePath.removePrefix(root.absolutePath).trimStart('/')
    }.getOrDefault(f.name)

    private fun describe(root: File, dir: File): String =
        if (dir == root) "workspace (корень)" else relative(root, dir)
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.pdf.PdfDocument
import android.text.Layout
import android.text.StaticLayout
import android.text.TextPaint
import java.io.File
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/**
 * Экспорт сообщений чата в документы БЕЗ внешних библиотек:
 *
 * • PDF — системный android.graphics.pdf.PdfDocument: текст с переносами
 *   (StaticLayout) и картинки, многостраничный A4.
 * • DOCX — это zip с OOXML-файлами; собирается вручную (ZipOutputStream):
 *   [Content_Types].xml + document.xml + relationships + media/…jpg.
 *   Открывается Word/WPS/Google Docs — проверенная минимальная структура.
 *
 * Правило (по требованию пользователя): текст без картинок -> и PDF и DOCX
 * доступны; если среди выделенных сообщений есть картинка — экспорт идёт
 * в DOCX или PDF (не в plain text).
 */
object DocExporter {

    data class Item(val title: String, val text: String, val imagePath: String?)

    // ---------- PDF ----------

    fun exportPdf(context: Context, items: List<Item>, fileName: String): File {
        val doc = PdfDocument()
        val pageW = 595 // A4 @72dpi
        val pageH = 842
        val margin = 40f
        val contentW = (pageW - margin * 2).toInt()

        val titlePaint = TextPaint().apply {
            color = Color.BLACK; textSize = 13f; isFakeBoldText = true; isAntiAlias = true
        }
        val textPaint = TextPaint().apply {
            color = Color.DKGRAY; textSize = 11f; isAntiAlias = true
        }

        var page = doc.startPage(PdfDocument.PageInfo.Builder(pageW, pageH, doc.pages.size + 1).create())
        var canvas = page.canvas
        var y = margin

        fun newPage() {
            doc.finishPage(page)
            page = doc.startPage(PdfDocument.PageInfo.Builder(pageW, pageH, doc.pages.size + 1).create())
            canvas = page.canvas
            y = margin
        }

        fun drawText(paint: TextPaint, text: String) {
            if (text.isBlank()) return
            val layout = StaticLayout.Builder.obtain(text, 0, text.length, paint, contentW)
                .setAlignment(Layout.Alignment.ALIGN_NORMAL).setLineSpacing(2f, 1f).build()
            var line = 0
            while (line < layout.lineCount) {
                val lineBottom = layout.getLineBottom(line) - layout.getLineTop(line)
                if (y + lineBottom > pageH - margin) newPage()
                // Рисуем построчно, чтобы уметь переносить через страницы
                val start = layout.getLineStart(line)
                val end = layout.getLineEnd(line)
                canvas.drawText(text.substring(start, end).trimEnd(), margin, y + paint.textSize, paint)
                y += lineBottom
                line++
            }
            y += 6f
        }

        for (item in items) {
            drawText(titlePaint, item.title)
            drawText(textPaint, item.text)
            val img = item.imagePath?.let { BitmapFactory.decodeFile(it) }
            if (img != null) {
                val scale = minOf(contentW.toFloat() / img.width, 1f)
                val w = (img.width * scale).toInt()
                val h = (img.height * scale).toInt()
                if (y + h > pageH - margin) newPage()
                val scaled = if (scale < 1f) Bitmap.createScaledBitmap(img, w, h, true) else img
                canvas.drawBitmap(scaled, margin, y, Paint(Paint.FILTER_BITMAP_FLAG))
                y += h + 10f
                if (scaled !== img) scaled.recycle()
                img.recycle()
            }
            y += 8f
        }
        doc.finishPage(page)

        val out = File(File(AiWorkspace.root(context), "export"), fileName).apply { parentFile?.mkdirs() }
        out.outputStream().use { doc.writeTo(it) }
        doc.close()
        return out
    }

    // ---------- DOCX (минимальный валидный OOXML) ----------

    fun exportDocx(context: Context, items: List<Item>, fileName: String): File {
        val out = File(File(AiWorkspace.root(context), "export"), fileName).apply { parentFile?.mkdirs() }
        val images = items.mapIndexedNotNull { i, item ->
            item.imagePath?.let { path -> Triple(i, "image${i + 1}.jpg", path) }
        }

        ZipOutputStream(out.outputStream()).use { zip ->
            fun put(name: String, content: ByteArray) {
                zip.putNextEntry(ZipEntry(name))
                zip.write(content)
                zip.closeEntry()
            }
            fun put(name: String, content: String) = put(name, content.toByteArray(Charsets.UTF_8))

            val imageTypes = if (images.isEmpty()) "" else
                """<Default Extension="jpg" ContentType="image/jpeg"/><Default Extension="jpeg" ContentType="image/jpeg"/>"""
            put(
                "[Content_Types].xml",
                """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>$imageTypes
<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
</Types>""",
            )
            put(
                "_rels/.rels",
                """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>""",
            )
            val imageRels = images.joinToString("") { (i, name, _) ->
                """<Relationship Id="rImg$i" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/$name"/>"""
            }
            put(
                "word/_rels/document.xml.rels",
                """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">$imageRels</Relationships>""",
            )

            val body = StringBuilder()
            for ((idx, item) in items.withIndex()) {
                body.append("<w:p><w:pPr><w:rPr><w:b/></w:rPr></w:pPr><w:r><w:rPr><w:b/></w:rPr><w:t xml:space=\"preserve\">")
                    .append(xmlEscape(item.title)).append("</w:t></w:r></w:p>")
                item.text.lines().forEach { line ->
                    body.append("<w:p><w:r><w:t xml:space=\"preserve\">")
                        .append(xmlEscape(line)).append("</w:t></w:r></w:p>")
                }
                val img = images.firstOrNull { it.first == idx }
                if (img != null) {
                    val bmp = BitmapFactory.decodeFile(img.third)
                    if (bmp != null) {
                        // EMU: 9525 на пиксель; ограничиваем ширину 15 см
                        val maxW = 5_400_000L
                        var wEmu = bmp.width * 9525L
                        var hEmu = bmp.height * 9525L
                        if (wEmu > maxW) {
                            hEmu = hEmu * maxW / wEmu
                            wEmu = maxW
                        }
                        bmp.recycle()
                        body.append(
                            """<w:p><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"><wp:extent cx="$wEmu" cy="$hEmu"/><wp:docPr id="${img.first + 1}" name="${img.second}"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="${img.first + 1}" name="${img.second}"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rImg${img.first}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="$wEmu" cy="$hEmu"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>""",
                        )
                    }
                }
            }
            put(
                "word/document.xml",
                """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>$body<w:sectPr/></w:body></w:document>""",
            )
            for ((_, name, path) in images) {
                // Перекодируем в JPEG (вдруг это png/webp)
                val bmp = BitmapFactory.decodeFile(path) ?: continue
                zip.putNextEntry(ZipEntry("word/media/$name"))
                bmp.compress(Bitmap.CompressFormat.JPEG, 88, zip)
                zip.closeEntry()
                bmp.recycle()
            }
        }
        return out
    }

    private fun xmlEscape(s: String) = s
        .replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        .replace("\"", "&quot;").replace("'", "&apos;")
}

