        // в спеке уронил бы мужскую реплику на женский голос.
        val serverVoice = roleVoice
            ?.let { spec -> parseVoiceSpec(spec).second.ifBlank { spec } }
            ?.takeIf { it.lowercase(Locale.US) in REMOTE_SERVER_VOICE_IDS }
            ?: gender
