 */
private fun speakElevenLabs(
    context: Context,
    text: String,
    roleVoice: String? = null,
    gender: String? = null,
) {
    val p = prefs()
    val apiKey = p.elevenApiKey().get()
    if (apiKey.isBlank()) {
        // Ключа нет — честный фолбэк на бесплатную веб-озвучку
        speakGoogleWeb(context, text)
        return
    }
    val voiceId = elevenVoiceId(roleVoice, gender)
    currentJob = scope.launch {
        setSpeaking(true)
        try {
            val conn = URL("https://api.elevenlabs.io/v1/text-to-speech/$voiceId")
                .openConnection() as HttpURLConnection
            conn.requestMethod = "POST"
            conn.doOutput = true
            conn.connectTimeout = 20_000
            conn.readTimeout = 60_000
            conn.setRequestProperty("xi-api-key", apiKey)
            conn.setRequestProperty("Content-Type", "application/json")
            conn.setRequestProperty("Accept", "audio/mpeg")
            val body = """{"text":${jsonQuote(text)},"model_id":"eleven_multilingual_v2"}"""
            conn.outputStream.use { it.write(body.toByteArray()) }
            if (conn.responseCode in 200..299) {
                val file = File(context.cacheDir, "tts_eleven.mp3")
                conn.inputStream.use { input -> file.outputStream().use { input.copyTo(it) } }
                playFileBlocking(file)
            } else {
                logcat(LogPriority.WARN) { "ElevenLabs HTTP ${conn.responseCode}" }
                speakGoogleWebInline(context, text)
            }
            conn.disconnect()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "ElevenLabs TTS failed" }
            speakGoogleWebInline(context, text)
        } finally {
            setSpeaking(false)
        }
    }
}

 * обычное поле. null — ключа нет либо значение не строка/массив; вызывающий
 * трактует это как «для этой книги ролей нет».
 */
fun extractArray(json: String, key: String): String? {
    val t = json.trim()
    if (!t.startsWith("{") || !t.endsWith("}")) return null
    val needle = "\"$key\""
    var i = 0
    while (i < t.length) {
        val at = t.indexOf(needle, i)
        if (at < 0) return null
        var m = at + needle.length
        while (m < t.length && t[m].isWhitespace()) m++
        if (m >= t.length || t[m] != ':') {
            i = at + needle.length
            continue
        }
        m++
        while (m < t.length && t[m].isWhitespace()) m++
        if (m >= t.length) return null
        return when (t[m]) {
            '[' -> {
                var depth = 0
                var inStr = false
                var k = m
                while (k < t.length) {
                    val c = t[k]
                    if (inStr) {
                        if (c == '\\') { k += 2; continue }
                        if (c == '"') inStr = false
                    } else {
                        when (c) {
                            '"' -> inStr = true
                            '[' -> depth++
                            ']' -> {
                                depth--
                                if (depth == 0) return t.substring(m, k + 1)
                            }
                        }
                    }
                    k++
                }
                null
            }
            '"' -> {
                var inStr = false
                var k = m
                while (k < t.length) {
                    val c = t[k]
                    if (c == '\\') { k += 2; continue }
                    if (c == '"') { inStr = false; break }
                    inStr = true
                    k++
                }
                if (!inStr) null else t.substring(m, k + 1)
            }
            else -> null
        }
    }
    return null
}

/**
 * Заменить (или добавить) значение по ключу в плоском JSON-объекте.
 *
 * Пишется вручную и по верхнему уровню: чужие книги и их роли должны
 * пережить перезапись нетронутыми, а org.json здесь недоступен в тестах.
 */
fun withArray(json: String, key: String, value: String): String {
    val t = json.trim()
    val entry = "\"$key\":$value"
    if (t.isEmpty() || !t.startsWith("{") || !t.endsWith("}")) return "{$entry}"
    val inner = t.removePrefix("{").removeSuffix("}").trim()
    if (inner.isEmpty()) return "{$entry}"
    val out = StringBuilder("{")
    var i = 0
