        private const val ACTION_CYCLE_ENGINE = "eu.kanade.tachiyomi.ocr.OVERLAY_CYCLE_ENGINE"
        private const val ACTION_CYCLE_VOICE = "eu.kanade.tachiyomi.ocr.OVERLAY_CYCLE_VOICE"
