@Composable
fun ReaderAiChatOverlay(
    context: Context,
    mangaId: Long?,
    mangaTitle: String,
    chapterTitle: String?,
    onClose: () -> Unit,
    onVoiceGender: String = "female",
    /**
     * Полная остановка по кнопке «Стоп»: прерывает ход агента и всё, что он
     * успел запустить. Без этого кнопка «Стоп» в меню читалки недоступна
     * именно тогда, когда она нужнее всего, — когда открыт чат.
     */
    onStopRequested: () -> Unit = {},
) {
    val history = remember { mutableStateListOf<Msg>() }
    var loading by remember { mutableStateOf(false) }
    var input by remember { mutableStateOf("") }
    var showClearConfirm by remember { mutableStateOf(false) }
    var showConsole by remember { mutableStateOf(false) }
    var attachedName by remember { mutableStateOf<String?>(null) }
    var attachedBytes by remember { mutableStateOf<ByteArray?>(null) }
    var activity by remember { mutableStateOf("") }
    var elapsed by remember { mutableStateOf(0L) }
    var backendLine by remember { mutableStateOf("") }
    var sessionLine by remember { mutableStateOf("") }
    // Как работаем с этой книгой: чат/отыгрыш, 18+, цензура. Заполняется
    // из файла книги и меняется чипами прямо в шапке. Ключ — mangaId, иначе
    // при переходе на другую книгу остались бы настройки предыдущей.
    var bookSettings by remember(mangaId) {
        mutableStateOf(BookKnowledge.profile(context, mangaId))
    }
    // У отыгрыша своя история: канал определяется режимом и объявлен здесь,
    // до лямбды отправки, которая его использует.
    val historyChannel = AiHistoryManager.channelOf(bookSettings.mode)
    // Растёт после каждого ответа: эффект ниже перечитывает сводку сессии.
    var sessionRefresh by remember { mutableStateOf(0) }

    // Вкладка чата: 0 — переписка, 1 — файлы workspace. Читатель искал файлы
    // в чате и в папке телефона: папки на Android 11+ приложение создать не
    // может, поэтому список файлов показываем прямо в чате.
    var tab by remember { mutableStateOf(0) }
    var filesRefresh by remember { mutableStateOf(0) }

    val listState = rememberLazyListState()
    val scope = rememberCoroutineScope()

    // Задача текущего хода: без ссылки её нечем прервать, а прерывать
    // читателю нужно — иначе ответ агента нельзя остановить.
    var runningJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }

    // Сообщение, отправленное «поверх» текущего хода. Раньше поле ввода
    // блокировалось на всё время работы агента, поэтому последовательно
    // спросить его было нельзя в принципе.
    var queuedMessage by remember { mutableStateOf<Pair<String, ByteArray?>?>(null) }

    val showToast: (String) -> Unit = { message -> context.toast(message) }
    val scrollTo: (Int) -> Unit = { index -> scope.launch { listState.animateScrollToItem(index) } }
    val setActivity: (String) -> Unit = { text ->
        scope.launch {
            activity = text
            elapsed = 0L
        }
    }

    LaunchedEffect(Unit) {
        val prefs = uy.kohesive.injekt.Injekt.get<mihon.domain.ocr.service.OcrPreferences>()
        // Снимок бэкенда читает сеть, каталоги моделей и сессии ранера — это
        // диск и binder, и на главном потоке (здесь это Main.immediate)
        // он подвешивал чат на открытии.
        val state = withContext(Dispatchers.IO) {
            eu.kanade.tachiyomi.data.ai.AiBackends.state(context, prefs)
        }
        val backend = eu.kanade.tachiyomi.data.ai.AiBackends.byId(prefs.aiBackend().get())
        val status = eu.kanade.tachiyomi.data.ai.AiBackends.statusOf(
            backend,
            state,
            prefs.aiProvider().get(),
        )
        val chatTarget = eu.kanade.tachiyomi.data.ai.AiModelRoles.chatTarget(
            chatBackend = prefs.aiBackend().get(),
            chatProvider = prefs.aiProvider().get(),
            chatModel = chatModelLabel(context, prefs),
        )
        val orchestrator = eu.kanade.tachiyomi.data.ai.AiModelRoles.orchestratorTarget(
            chatBackend = prefs.aiBackend().get(),
            chatProvider = prefs.aiProvider().get(),
            chatModel = chatTarget.model,
            orchestratorBackend = prefs.aiOrchestratorBackend().get(),
            orchestratorModel = prefs.aiOrchestratorModel().get(),
            backendState = state,
        )
        val ocrEngine = prefs.ocrModel().get()
        val autoRotate = prefs.aiAutoRotate().get()
        val lines = eu.kanade.tachiyomi.data.ai.AiModelRoles.statusLines(
            eu.kanade.tachiyomi.data.ai.AiModelRoles.ocrTarget(
                engineId = ocrEngine.name,
                engineTitle = mihon.data.ocr.OcrPlugins.byModel(ocrEngine).title,
            ),
            chatTarget,
            orchestrator,
        )
        backendLine = if (status.available) {
            // При включённой автосмене отвечать может не та модель, что выбрана,
            // и без подписи это выглядит как «выбрали не ту». Имя ответившей
            // модели показывается в подвале каждого сообщения.
            val rotationNote = if (autoRotate) " · автосмена моделей" else ""
            (lines.joinToString(" · ") + rotationNote).trim()
        } else {
            "${backend.title} · недоступно: ${status.missing.joinToString(", ")}"
        }
    }

    LaunchedEffect(loading) {
        if (!loading) {
            elapsed = 0L
            activity = ""
        }
    }

    LaunchedEffect(loading) {
        while (loading) {
            kotlinx.coroutines.delay(1000)
            elapsed += 1
        }
    }

    val send: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
        if (text.isNotBlank() && !loading) {
            // Поле очищаем сразу при отправке: оставлять отправленный текст в
            // поле нельзя — читатель видит «не отправлено» и ждёт второй раз.
            input = ""
            runningJob = sendMessage(
                context = context,
                scope = scope,
                mangaId = mangaId,
                mangaTitle = mangaTitle,
                chapterTitle = chapterTitle,
                input = text,
                attachmentsName = fileName,
                attachmentsBytes = fileBytes,
                history = history,
                loading = { loading = it },
                onScroll = scrollTo,
                censorship = bookSettings.censorship,
                historyChannel = historyChannel,
                onActivity = setActivity,
                onDone = { sessionRefresh += 1 },
            ).also {
                // Ход завершился — ссылка больше не нужна, иначе «Стоп» отменил
                // бы уже завершённую работу и обнулил индикатор.
                scope.launch {
                    it.join()
                    runningJob = null
                }
            }
            attachedName = null
            attachedBytes = null
        }
    }

    // Отправка, которая не теряет сообщение, поданное во время работы
    // агента: оно встаёт в очередь и уходит следующим ходом.
    val sendOrQueue: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
        when {
            text.isBlank() -> Unit
            // Идёт ход — копим. Больше одного сообщения в очередь не берём:
            // читателю важнее ответить сейчас, чем копить пачку.
            loading -> {
                if (queuedMessage == null) {
                    queuedMessage = text to fileBytes
                    input = ""
                    attachedName = null
                    attachedBytes = null
                    showToast("Сообщение в очереди — уйдёт следом")
                }
            }
            else -> send(text, fileName, fileBytes)
        }
    }

    // Стоп: прерываем ход агента и всё, что он успел запустить, — озвучку и
    // авточтение. Иначе остановленный ответ оставляет читателя вслух
    // читающую главу.
    val stopEverything: () -> Unit = {
        runningJob?.cancel()
        runningJob = null
        loading = false
        // «Сюжет» шёл своим запросом и раньше дожидался его сам: остановка
        // агента и чтения его не трогала, и пересказ дописывался на живого
        // читателя уже после «Стоп».
        val plotStopped = eu.kanade.tachiyomi.data.ai.ReadingPlotAgentHolder.agent.cancel()
        // Сокет сам по себе отмены не знает: пока он висит, модель продолжает
        // отвечать в никуда, и «Стоп» держал бы экран занятым до 90 секунд.
        runCatching { eu.kanade.tachiyomi.data.ai.AiHttpServer.abortAllRequests("кнопка «Стоп» в чате") }
        eu.kanade.tachiyomi.data.ai.AiAssistant.abortActiveRequests("кнопка «Стоп» в чате")
        eu.kanade.tachiyomi.data.ai.AiConsole.user(
            title = "Остановлено",
            detail = "агент: ${if (runningJob != null) "был в работе" else "не работал"}" +
                (if (plotStopped) " · сюжет: запрос отменён" else ""),
        )
        onStopRequested()
        showToast("Остановлено")
    }

    // Очередь уходит сама, как только освободился агент.
    LaunchedEffect(loading, queuedMessage) {
        val next = queuedMessage
        if (!loading && next != null) {
            queuedMessage = null
            send(next.first, null, next.second)
        }
    }

    // История книги грузится один раз на книгу: перечитывать её на каждый
    // ответ нельзя — файл на диске ещё не дописан, и перезагрузка стирала бы
    // сообщение, которое агент только что сохранил.
    // Канал входит в ключ ОТДЕЛЬНО: раньше он был в одном ключе с mangaId, и
    // переключение «Чат ⇄ Отыгрыш» делало history.clear() прямо посреди
    // разговора — читатель видел пустой чат и делал вывод, что агент всё
    // забыл.
    LaunchedEffect(mangaId) {
        history.clear()
        history.addAll(AiHistoryManager.load(context, mangaId, historyChannel))
        runCatching { listState.scrollToItem((history.size - 1).coerceAtLeast(0)) }
    }
    LaunchedEffect(mangaId, historyChannel) {
        if (history.isEmpty()) return@LaunchedEffect
        val loaded = AiHistoryManager.load(context, mangaId, historyChannel)
        if (loaded.isEmpty()) return@LaunchedEffect
        history.clear()
        history.addAll(loaded)
        runCatching { listState.scrollToItem((history.size - 1).coerceAtLeast(0)) }
    }

    // Сводка сессии — отдельный эффект: она меняется после ответа агента,
    // когда выучены новые правила/источники.
    LaunchedEffect(mangaId, sessionRefresh) {
        // Сессия книги создаётся при первом входе в чат, чтобы знания и
        // история этой книги не смешивались с глобальным AI-чатом.
        if (mangaId != null) {
            sessionLine = withContext(Dispatchers.IO) {
                eu.kanade.tachiyomi.data.ai.BookKnowledge.ensureSession(context, mangaId)
                eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, mangaId)
            }
        } else {
            sessionLine = eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, null)
        }
    }

    val fileLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument(),
    ) { uri: Uri? ->
        if (uri == null) return@rememberLauncherForActivityResult
        val (name, bytes) = readUriFile(context, uri) ?: return@rememberLauncherForActivityResult
        attachedName = name
        attachedBytes = bytes
    }

    Dialog(
        properties = DialogProperties(
            usePlatformDefaultWidth = false,
            decorFitsSystemWindows = false,
        ),
        onDismissRequest = onClose,
    ) {
        Surface(modifier = Modifier.fillMaxSize()) {
            Column(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        // Диалог рисуется во весь экран (decorFitsSystemWindows =
                        // false), поэтому шапку и поле ввода надо прижать к
                        // системным отступам: иначе часы и заголовок наезжали
                        // друг на друга, а кнопка отправки — на жестовую
                        // полосу внизу.
                        .statusBarsPadding()
                        .padding(horizontal = 12.dp, vertical = 10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Icon(
                        Icons.Outlined.SmartToy,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(22.dp),
                    )
                    Spacer(Modifier.width(8.dp))
                    Column(Modifier.weight(1f)) {
                        Text(
                            "AI-чат · $mangaTitle",
                            style = MaterialTheme.typography.titleMedium,
                            maxLines = 1,
                        )
                        Text(
                            chapterTitle ?: "читалка",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            maxLines = 1,
                        )
                        if (backendLine.isNotBlank()) {
                            Text(
                                backendLine,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                maxLines = 2,
                            )
                        }
                        if (sessionLine.isNotBlank()) {
                            Text(
                                "Сессия книги: $sessionLine",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                maxLines = 1,
                            )
                        }
                    }
                    IconButton(onClick = onClose) {
                        Icon(Icons.Outlined.Close, contentDescription = "Скрыть AI-чат")
                    }
                }
                // Переписка или файлы. Файлы — отдельная вкладка, а не
                // сообщение в чате: агент создаёт их и раньше, и читателю надо
                // увидеть весь список, а не то, что попало в последний ответ.
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    FilterChip(
                        selected = tab == 0,
                        onClick = { tab = 0 },
                        label = { Text("Чат") },
                        modifier = Modifier.height(30.dp),
                    )
                    FilterChip(
                        selected = tab == 1,
                        onClick = {
                            tab = 1
                            filesRefresh++
                        },
                        label = { Text("Файлы") },
                        modifier = Modifier.height(30.dp),
                    )
                    // Сюжет: пересказ того, что уже прозвучало при чтении.
                    // Отдельная вкладка, потому что это не диалог с агентом, а
                    // его наблюдение: текст пишется сам по мере чтения.
                    FilterChip(
                        selected = tab == 2,
                        onClick = { tab = 2 },
                        label = { Text("Сюжет") },
                        modifier = Modifier.height(30.dp),
                    )
                    // Консоль: что ИИ делает прямо сейчас. Отдельный экран, а
                    // не ещё одна вкладка чата: её открывают, когда ход идёт и
                    // надо посмотреть, чем он занят.
                    FilterChip(
                        selected = false,
                        onClick = { showConsole = true },
                        label = { Text("Консоль") },
                        modifier = Modifier.height(30.dp),
                    )
                }
                if (showConsole) {
                    AiConsoleDialog(
                        onClose = { showConsole = false },
                        onStopEverything = stopEverything,
                    )
                }
                if (tab == 2) {
                    ReadingPlotPanel(mangaId = mangaId, showToast = showToast)
                }
                if (tab == 1) {
                    WorkspaceFilesPanel(
                        context = context,
                        refresh = filesRefresh,
                        // «Открыть» = показать файл. Раньше здесь был
                        // toShareIntent (ACTION_SEND), и кнопка открывала лист
                        // отправки: чтобы просто глянуть картинку, файл надо
                        // было сначала скопировать или отправить себе.
                        onOpen = { file ->
                            runCatching {
                                context.startActivity(
                                    file.toViewIntent(context).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                                )
                            }.onFailure {
                                showToast("Не открыть ${file.name}: нет приложения для ${file.mimeType()}")
                            }
                        },
                    )
                } else {
                // Настройки работы с этой книгой: режим, 18+, цензура. Отдельный
                // рядом, а не в меню: переключать их надо прямо по ходу чтения.
                if (mangaId != null) {
                    val bookId = mangaId
                    // Профиль книги, а не Book: в UI нужны только настройки.
                    val applyProfile: ((BookKnowledge.Book) -> Unit) -> Unit = { mutate ->
                        bookSettings = BookKnowledge.updateProfile(context, bookId, mutate)
                            .let { BookChatProfile.Settings(it.mode, it.matureAllowed, it.censorship, it.title, it.edition) }
                    }
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp),
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        FilterChip(
                            selected = bookSettings.mode == BookChatProfile.MODE_ROLEPLAY,
                            onClick = {
                                val next = if (bookSettings.mode == BookChatProfile.MODE_ROLEPLAY) {
                                    BookChatProfile.MODE_CHAT
                                } else {
                                    BookChatProfile.MODE_ROLEPLAY
                                }
                                applyProfile { it.mode = next }
                            },
                            label = { Text(BookChatProfile.modeTitle(bookSettings.mode)) },
                            modifier = Modifier.height(30.dp),
                        )
                        FilterChip(
                            selected = bookSettings.matureAllowed,
                            onClick = { applyProfile { it.matureAllowed = !it.matureAllowed } },
                            label = { Text("18+") },
                            modifier = Modifier.height(30.dp),
                        )
                        FilterChip(
                            selected = bookSettings.censorship,
                            onClick = { applyProfile { it.censorship = !it.censorship } },
                            label = { Text("Цензура") },
                            modifier = Modifier.height(30.dp),
                        )
                    }
                }
                if (loading || activity.isNotBlank()) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp, vertical = 2.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        if (loading) {
                            CircularProgressIndicator(Modifier.size(12.dp), strokeWidth = 2.dp)
                            Spacer(Modifier.width(6.dp))
                        }
                        Text(
                            buildString {
                                append(if (loading) "AI думает" else "Готово")
                                if (loading && elapsed > 0) append(" · ").append(elapsed).append(" с")
                                if (activity.isNotBlank()) append(" · ").append(activity)
                            },
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            maxLines = 2,
                        )
                    }
                }
                HorizontalDivider()

                LazyColumn(
                    state = listState,
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxWidth(),
                    contentPadding = androidx.compose.foundation.layout.PaddingValues(12.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    if (history.isEmpty() && !loading) {
                        item {
                            Text(
                                "Спросите что угодно о книге «$mangaTitle»: " +
                                    "сюжет, персонажи, порядок чтения, перевод реплик, " +
                                    "«нарисуй лого», «сделай заметку»… AI умеет создавать " +
                                    "файлы в workspace, а результат можно скачать.",
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                textAlign = TextAlign.Center,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 16.dp),
                            )
                        }
                    }

                    itemsIndexed(history) { index, msg ->
                        ChatBubble(
                            context = context,
                            msg = msg,
                            isMine = msg.role == "user",
                            canPlay = msg.role == "ai",
                            onCopy = {
                                val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE)
                                    as? ClipboardManager
                                clipboard?.setPrimaryClip(ClipData.newPlainText("AI-чат", msg.text))
                                showToast("Скопировано")
                            },
                            onChoice = { choice ->
                                if (!loading) send(choice, null, null)
                            },
                            onRetry = {
                                if (!loading) {
                                    history.remove(msg)
                                    send(msg.text, null, null)
                                }
                            },
                            onDelete = {
                                // Пока идёт ход, ответ ещё будет дописан в
                                // историю — и удалённое сообщение вернулось бы
                                // вместе с ним.
                                if (!loading) {
                                    history.remove(msg)
                                    scope.launch {
                                        AiHistoryManager.save(context, history.toList(), mangaId, historyChannel)
                                    }
                                }
                            },
                            onSpeak = {
                                TtsSpeaker.speak(context, msg.text)
                            },
                        )
                    }
                }

                AnimatedVisibility(visible = attachedName != null) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp, vertical = 4.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(Icons.Outlined.AttachFile, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(Modifier.width(6.dp))
                        Text(
                            attachedName ?: "",
                            style = MaterialTheme.typography.bodySmall,
                            maxLines = 1,
                            modifier = Modifier.weight(1f),
                        )
                        TextButton(onClick = {
                            attachedName = null
                            attachedBytes = null
                        }) {
                            Text("Убрать")
                        }
                    }
                }

                QuickActionsRow(
                    enabled = !loading,
                    onImage = { input = "Нарисуй картинку: " },
                    onAudio = { input = "Создай аудиофайл (render_audio): " },
                    onVideo = { input = "Сделай видео: " },
                    onZip = { send("Упакуй workspace в zip и покажи готовый файл", null, null) },
                    onSource = { input = "Прочитай источник и выучи правила книги: " },
                    onRules = { input = "Выучи правила книги по этому тексту:\n" },
                )

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .navigationBarsPadding()
                        .imePadding()
                        .padding(horizontal = 12.dp, vertical = 8.dp),
                    verticalAlignment = Alignment.Bottom,
                ) {
                    OutlinedIconButton(
                        onClick = { fileLauncher.launch(arrayOf("*/*")) },
                        enabled = !loading,
                    ) {
                        Icon(Icons.Outlined.AttachFile, contentDescription = "Прикрепить файл")
                    }
                    Spacer(Modifier.width(8.dp))
                    OutlinedTextField(
                        value = input,
                        onValueChange = { input = it },
                        modifier = Modifier.weight(1f),
                        placeholder = {
                            Text(
                                if (queuedMessage != null) {
                                    "В очереди — уйдёт следом"
                                } else {
                                    "Сообщение AI…"
                                },
                            )
                        },
                        maxLines = 4,
                        // Ввод не блокируется на время работы агента: писать
                        // ему последовательно должно быть можно, иначе вопрос
                        // приходилось заранее писать в поле и ждать.
                        enabled = true,
                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Send),
                        keyboardActions = KeyboardActions(
                            onSend = {
                                sendOrQueue(input.trim(), attachedName, attachedBytes)
                            },
                        ),
                    )
                    Spacer(Modifier.width(8.dp))
                    OutlinedIconButton(
                        onClick = { sendOrQueue(input.trim(), attachedName, attachedBytes) },
                        enabled = input.isNotBlank(),
                    ) {
                        Icon(Icons.AutoMirrored.Outlined.Send, contentDescription = "Отправить")
                    }
                    // Стоп виден всегда, пока идёт ход: иначе ответ агента,
                    // а вместе с ним озвучка и авточтение, нечем остановить.
                    if (loading) {
                        Spacer(Modifier.width(4.dp))
                        FilledIconButton(onClick = stopEverything) {
                            Icon(Icons.Outlined.StopCircle, contentDescription = "Остановить")
                        }
                    }
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp, vertical = 6.dp),
                    horizontalArrangement = Arrangement.End,
                ) {
                    TextButton(onClick = { showClearConfirm = true }) {
                        Text("Очистить историю")
                    }
                }
            }
                }
        }
    }


    if (showClearConfirm) {
        androidx.compose.material3.AlertDialog(
            onDismissRequest = { showClearConfirm = false },
            title = { Text("Очистить историю чата?") },
            text = { Text("История этой книги будет удалена навсегда. Это действие нельзя отменить.") },
            confirmButton = {
                Button(onClick = {
                    // «Удалено навсегда» должно означать навсегда: во время
                    // хода ответ агента дописывается в тот же список и
                    // перезаписывает файл, возвращая историю с ответом.
                    if (loading) {
                        showToast("Дождитесь окончания ответа")
                        showClearConfirm = false
                    } else {
                        history.clear()
                        scope.launch {
                            AiHistoryManager.save(context, history.toList(), mangaId, historyChannel)
                        }
                        showClearConfirm = false
                        showToast("История очищена")
                    }
                }) {
                    Text("Очистить")
                }
            },
            dismissButton = {
                TextButton(onClick = { showClearConfirm = false }) { Text("Отмена") }
            },
        )
    }
}

private fun sendMessage(
    context: Context,
    scope: kotlinx.coroutines.CoroutineScope,
    mangaId: Long?,
    mangaTitle: String,
    chapterTitle: String?,
    input: String,
    attachmentsName: String? = null,
    attachmentsBytes: ByteArray? = null,
    history: SnapshotStateList<Msg>,
    loading: (Boolean) -> Unit,
    onScroll: (Int) -> Unit,
    /** Настройки книги на момент отправки: цензура применяется к ответу. */
    censorship: Boolean = true,
    /** Канал истории на момент отправки, чтобы ответ не попал в чужую переписку. */
    historyChannel: String = AiHistoryManager.CHANNEL_CHAT,
    onActivity: (String) -> Unit = {},
    /** Вызывается после сохранения ответа: пора перечитать сводку сессии. */
    onDone: () -> Unit = {},
): kotlinx.coroutines.Job {
    loading(true)
    onActivity("Запрос к модели…")
    // Job возвращаем наружу, чтобы кнопка «Стоп» действительно прерывала ход:
    // раньше ссылка на него не хранилась, и `cancel()` был вызовом в пустоту.
    return scope.launch {
        // Запись вопроса в историю — внутри корутины: файл истории на диске,
        // а синхронный writeText на главном потоке ронял кадры на каждом ходе.
        AiHistoryManager.append(context, history, Msg(role = "user", text = input), mangaId, historyChannel)
        val reply = try {
            chatOnce(
                context = context,
                mangaId = mangaId,
                mangaTitle = mangaTitle,
                chapterTitle = chapterTitle,
                input = input,
                attachmentsName = attachmentsName,
                attachmentsBytes = attachmentsBytes,
                history = history,
                onProgress = onActivity,
            )
        } catch (e: CancellationException) {
            // Кнопка «Стоп»: отмена хода — не ошибка запроса. Раньше
            // runCatching глотал отмену и в историю попадал ответ
            // «Сбой запроса к AI: …», хотя читатель просто остановил агента.
            loading(false)
            onActivity("Остановлено")
            throw e
        } catch (e: Exception) {
            onActivity("Ошибка запроса")
            AiAgent.AgentReply(
                text = "Сбой запроса к AI: ${e.message ?: e::class.java.simpleName}",
                toolResults = emptyList(),
                images = emptyList(),
            )
        }
        // Фильтр грубых слов — настройка читателя, применяется к тому, что
        // реально попадёт в чат и в историю, иначе «цензура» была бы только
        // словами в промпте.
        val shown = if (censorship) {
            BookChatProfile.maskCensored(reply.text)
        } else {
            reply.text
        }
        // Пакетная генерация отдаёт несколько файлов одним вызовом: показываем
        // их все отдельными карточками, иначе читатель увидит одну картинку из
        // десяти и решит, что остальные не сделаны.
        val produced = reply.toolResults.flatMap { listOfNotNull(it.fileProduced) + it.extraFiles }
        val files = (produced + reply.images)
            .distinctBy { it.absolutePath }
            .mapNotNull { eu.kanade.tachiyomi.data.ai.AiWorkspace.relPathOrNull(context, it) }
            .distinct()
        AiHistoryManager.append(
            context = context,
            history = history,
            msg = Msg(
                role = "ai",
                text = shown,
                time = System.currentTimeMillis(),
                tokens = reply.tokens,
                model = reply.model,
                reasoning = reply.reasoning.orEmpty(),
                choices = reply.choices,
                tools = reply.toolResults.map { tr ->
                    buildString {
                        append(tr.name)
                        if (tr.status == "error") append(" — ошибка")
                        if (tr.tookMs > 0) append(" · ").append(AiAgent.humanMs(tr.tookMs))
                        val produced = tr.fileProduced
                        if (produced != null) {
                            append(" · ").append(produced.name).append(' ')
                            append(produced.length() / 1024).append(" КБ")
                        }
                        if (tr.extraFiles.isNotEmpty()) {
                            append(" · ещё ").append(tr.extraFiles.size)
                        }
                    }
                },
                files = files,
            ),
            mangaId = mangaId,
            channel = historyChannel,
        )
        loading(false)
        onActivity("Готово")
        onScroll(history.size - 1)
        onDone()
    }
}

// `}` внутри класса символов экранирован: без экрана ICU-движок регулярок
// (Android 13+, Itel/Infinix) бросает PatternSyntaxException в <clinit>.
private val linkRe = Regex("https?://[^\\s)\\]\\}\"']+", RegexOption.IGNORE_CASE)

/** Модель чата по текущему провайдеру — для заголовка и выбора ролей. */
private fun chatModelLabel(
    context: Context,
    prefs: mihon.domain.ocr.service.OcrPreferences,
): String {
    val provider = prefs.aiProvider().get()
    return when (provider) {
        eu.kanade.tachiyomi.data.ai.AiAssistant.PROVIDER_ZEN ->
            prefs.zenModel().get().ifBlank { eu.kanade.tachiyomi.data.ai.AiAssistant.ZEN_MODELS.first() }
        eu.kanade.tachiyomi.data.ai.AiAssistant.PROVIDER_OPENROUTER -> prefs.openrouterFreeModel().get()
            .ifBlank { eu.kanade.tachiyomi.data.ai.AiAssistant.OPENROUTER_FREE_FALLBACK.first() }
        else -> eu.kanade.tachiyomi.data.ai.AiProviders.userProvider(context, provider)?.model ?: provider
    }
}

private suspend fun chatOnce(
    context: Context,
    mangaId: Long?,
    mangaTitle: String,
    chapterTitle: String?,
    input: String,
    attachmentsName: String?,
    attachmentsBytes: ByteArray?,
    history: List<Msg>,
    onProgress: ((String) -> Unit)? = null,
): AiAgent.AgentReply =
    withContext(Dispatchers.IO) {
        val prefs = uy.kohesive.injekt.Injekt.get<mihon.domain.ocr.service.OcrPreferences>()
        val orchestrator = eu.kanade.tachiyomi.data.ai.AiModelRoles.orchestratorTarget(
            chatBackend = prefs.aiBackend().get(),
            chatProvider = prefs.aiProvider().get(),
            chatModel = chatModelLabel(context, prefs),
            orchestratorBackend = prefs.aiOrchestratorBackend().get(),
            orchestratorModel = prefs.aiOrchestratorModel().get(),
        )
        val resolution = AiBackends.resolve(
            context = context,
            backendId = orchestrator.backendId,
            modelOverride = orchestrator.modelOverride,
        )
        val chat = resolution.chat
        if (chat == null) {
            return@withContext AiAgent.AgentReply(
                text = resolution.message ?: "AI-бэкенд недоступен",
                toolResults = emptyList(),
                images = emptyList(),
            )
        }
        val attachedText = if (attachmentsName != null && attachmentsBytes != null) {
            val saved = eu.kanade.tachiyomi.data.ai.AiWorkspace.importAttachment(context, attachmentsName, attachmentsBytes)
            if (saved != null) {
                "Прикреплён файл: ${eu.kanade.tachiyomi.data.ai.AiWorkspace.relPath(context, saved)}"
            } else {
                "Прикреплён файл: $attachmentsName (не удалось сохранить)"
            }
        } else {
            null
        }
        val priorTurns = history
            .dropLast(1)
            // Сводка сжатия — не реплика, окно на неё тратить не надо.
            .filterNot { it.text.startsWith("[Сжато: ") || it.text.startsWith("[Сводка прошлого контекста]") }
            .map { it.role to it.text }
            // Раньше жёстко 6 сообщений (~3 обмена) при том, что и настройка,
            // и подпись в промпте обещали 12: первая тема исчезала через пару
            // реплик — читатель и видел «AI ничего не помнит».
            .takeLast(
                runCatching {
                    Injekt.get<mihon.domain.ocr.service.OcrPreferences>()
                        .aiHistoryLimit()
                        .get()
                        .coerceIn(4, 100)
                }.getOrDefault(12),
            )
        val knowledge = eu.kanade.tachiyomi.data.ai.BookKnowledge.render(context, mangaId)
            .ifBlank {
                "ЗНАНИЕ О КНИГЕ: пока ничего не проверено — выясни через web_search, " +
                    "прочитай найденную страницу через book_learn {\"url\":…} и сохрани правила."
            }
        // Присланная пользователем ссылка — это источник, а не вопрос: говорим
        // модели прямо, чтобы она прочитала страницу и зафиксировала правила.
        val links = linkRe.findAll(input).map { it.value }.distinct().take(3).toList()
        val prompt = buildString {
            append("Книга: ").append(mangaTitle)
            if (!chapterTitle.isNullOrBlank()) append("\nГлава: ").append(chapterTitle)
            if (links.isNotEmpty()) {
                append("\nПользователь прислал источник: ").append(links.joinToString(", "))
                append("\nПрочитай источник через book_learn {\"url\":\"…\"}, выведи из него правила ")
                append("(порядок чтения, области и рамки, баблы, расшифровка, голоса и роли) ")
                append("и зафиксируй их book_learn с kind. Если правил нет — так и скажи.")
            }

package mihon.data.ocr

import android.Manifest
import android.content.ContentValues
import android.content.Context
import android.content.pm.PackageManager
import android.media.MediaScannerConnection
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import androidx.core.content.ContextCompat
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import mihon.domain.ocr.model.OcrRegion
import tachiyomi.core.common.util.system.logcat
import java.io.File
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Кольцевой буфер скриншотов авточтения — текст регионов (~1-5 KB) плюс
 * необязательный JPEG-кадр каждого скриншота.
 *
 * Хранит до [MAX_ENTRIES] последних записей в JSON-файле. Если запись создана
 * с JPEG-кадром ([OcrScreenshotEntry.add]), картинка пишется в каталог
 * `filesDir/screenshots_images/<id>.jpg`, а в записи сохраняется её путь —
 * галерея показывает реальное изображение с оверлеем регионов.
 *
 * При превышении лимита самая старая запись и её файл удаляются.
 */
object OcrScreenshotBuffer {

    private const val DEFAULT_MAX_ENTRIES = 50
    private const val FILE_NAME = "screenshots.json"
    private const val IMAGE_DIR_NAME = "screenshots_images"

    /** Публичная папка в «Pictures», куда публикуются скриншоты для Галереи. */
    private const val GALLERY_DIR_NAME = "Yomikai"
    private const val JPEG_MIME = "image/jpeg"

    /** Префикс имени файла в галерее: по нему кадр узнаётся среди прочих. */
    private const val GALLERY_NAME_PREFIX = "Yomikai"

    /** Ограничение длины DISPLAY_NAME: длинные имена обрезаются системой. */
    private const val MAX_GALLERY_NAME_LENGTH = 80

    /** Лимит записей (кольцевой буфер). Меняется через dev-панель. */
    @kotlin.jvm.Volatile
    var maxEntries: Int = DEFAULT_MAX_ENTRIES

    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true; prettyPrint = false }

    private val _entries = MutableStateFlow<List<OcrScreenshotEntry>>(emptyList())
    val entries: StateFlow<List<OcrScreenshotEntry>> = _entries.asStateFlow()

    /** Последний добавленный скриншот — для индикатора в углу читалки. */
    private val _lastEntry = MutableStateFlow<OcrScreenshotEntry?>(null)
    val lastEntry: StateFlow<OcrScreenshotEntry?> = _lastEntry.asStateFlow()

    /**
     * Счётчик изменений буфера: вьюха страницы рисует пометки порядка чтения
     * на каждом кадре, а фильтровать список записей заново 60 раз в секунду
     * при прокрутке длинного вебтуна незачем. Кэш вьюхи инвалидируется этим
     * числом, а не подпиской на поток из анимации.
     */
    @Volatile
    var version: Int = 0
        private set

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private var persistFile: File? = null
    private var imagesDir: File? = null
    private var initialized = false

    fun init(context: Context) {
        if (initialized) return
        initialized = true
        persistFile = File(context.filesDir, FILE_NAME)
        imagesDir = File(context.filesDir, IMAGE_DIR_NAME).apply { mkdirs() }
        load()
    }

    // ---- Публичные методы ----

    /**
     * Добавить запись скриншота (текст + регионы ~1-5 KB, плюс необязательный
     * JPEG-кадр [imageJpeg], который пишется файлом и показывается в галерее).
     * Если буфер полон — самая старая запись (и её файл) удаляется.
     *
     * @return Созданная запись.
     */
    /**
     * Добавить запись в буфер.
     *
     * synchronized не лишний: писателей стало два — авточтение пишет кадр за
     * кадром, а кнопка «Скриншот сейчас» добавляет запись из отдельной
     * корутины. Без блокировки оба собирали список от одного и того же
     * состояния, и одна запись молча пропадала.
     *
     * [sourceWidth]/[sourceHeight]/[scanCrop] — геометрия того, какая часть
     * файла страницы попала в кадр: без неё нормализованные координаты
     * [regions] относятся к уменьшенному и обрезанному OCR-битмапу, и в книге
     * по ним нельзя нарисовать ничего. Оставленные значения по умолчанию означают
     * «геометрии нет»: запись читается как раньше, проекция для неё
     * не выполняется.
     */
    @Synchronized
    fun add(
        chapterId: Long,
        pageIndex: Int,
        scrollFraction: Float,
        regions: List<OcrRegion>,
        engineUsed: String,
        imageWidth: Int = 0,
        imageHeight: Int = 0,
        imageJpeg: ByteArray? = null,
        scanRegion: String = "viewport",
        sourceWidth: Int = 0,
        sourceHeight: Int = 0,
        scanCrop: SerializableNormalizedRect = SerializableNormalizedRect(),
    ): OcrScreenshotEntry {
        val id = System.currentTimeMillis()
        val serializableRegions = regions.map { SerializableOcrRegion.fromOcrRegion(it) }
        val summaryText = regions.joinToString(" ") { it.text.trim() }.trim()
        val imagePath = imageJpeg?.let { jpeg ->
            imagesDir?.let { dir ->
                File(dir, "$id.jpg").apply { writeBytes(jpeg) }.absolutePath
            }
        }
        val entry = OcrScreenshotEntry(
            id = id,
            chapterId = chapterId,
            pageIndex = pageIndex,
            scrollFraction = scrollFraction,
            timestamp = id,
            regions = serializableRegions,
            engineUsed = engineUsed,
            summaryText = summaryText,
            imageWidth = imageWidth,
            imageHeight = imageHeight,
            imagePath = imagePath,
            scanRegion = scanRegion,
            sourceWidth = sourceWidth,
            sourceHeight = sourceHeight,
            scanCrop = scanCrop,
        )

        val current = _entries.value.toMutableList()
        val limit = maxEntries.coerceAtLeast(1)
        if (current.size >= limit) {
            val evicted = current.removeFirst()
            deleteImageFile(evicted)
        }
        current.add(entry)
        _entries.value = current
        _lastEntry.value = entry
        version++
        persist()
        return entry
    }
    /**
     * Опубликовать JPEG-кадр в общем хранилище: `Pictures/Yomikai`, то есть
     * ровно там, где его видят «Галерея», «Файлы» и любой файловый менеджер.
     *
     * Зачем это нужно рядом с [add]: картинки буфера лежат в приватном
     * `filesDir/screenshots_images/`, куда не смотрят ни MediaStore, ни
     * FileProvider, ни галерея телефона. Читатель нажимал «Скриншот сейчас» и
     * не находил файл НИГДЕ. Поэтому тот же JPEG дополнительно уходит в
     * публичное хранилище, а внутренняя копия остаётся для вкладки «Скриншоты»
     * (там кадр показывается вместе с оверлеем распознанных регионов).
     *
     * На Android 10+ (MediaStore) разрешение на запись не нужно вовсе, а при
     * targetSdk 36 писать в публичные папки через `File` уже нельзя. Ветка для
     * API < 29 нужна только для Android 8–9: там пишем файлом, но лишь если
     * WRITE_EXTERNAL_STORAGE реально выдан — с targetSdk 36 система может не
     * выдать его вовсе, и тогда возвращаем null, а не падаем.
     *
     * Ошибки никогда не пробрасываются: публикация — дополнение, из-за неё
     * скриншот не должен теряться (в logcat пишем причину).
     *
     * @return Uri опубликованного файла или null, если публикация не вышла.
     */
    fun publishToGallery(context: Context, jpeg: ByteArray, displayName: String): Uri? {
        val name = galleryFileName(displayName)
        return runCatching {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                insertIntoMediaStore(context, jpeg, name)
            } else {
                writeToPublicPictures(context, jpeg, name)
            }
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: gallery publish failed for $name" }
            null
        }
    }

    /**
     * Опубликовать в общую галерею JPEG уже сохранённой записи буфера — кнопка
     * «Сохранить в галерею» во вкладке «Скриншоты» идёт через неё.
     * Файл не перекодируется: в галерею уходит ровно тот кадр, который видит
     * читатель (вместе с оверлеем регионов он остаётся во внутренней копии).
     *
     * @return Uri опубликованного файла или null — у записи нет картинки, файл
     * не читается либо публикация не вышла.
     */
    fun publishEntryToGallery(context: Context, entry: OcrScreenshotEntry): Uri? {
        val path = entry.imagePath
        if (path == null) {
            logcat(LogPriority.WARN) { "OcrScreenshotBuffer: entry ${entry.id} has no image" }
            return null
        }
        val bytes = runCatching { File(path).readBytes() }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: read image failed for $path" }
            return null
        }
        return publishToGallery(context, bytes, galleryDisplayName(entry.pageIndex, entry.timestamp))
    }

    /**
     * Читаемое имя файла в галерее: `Yomikai_20260930_143512_p12`.
     *
     * Читатель ищет кадр глазами — в «Файлах», в «Галерее», в «Моих файлах» — и
     * ориентируется по имени. Папка из сотни безликих `image.jpg` ни о чём не
     * говорит, поэтому в имени есть приложение, дата, время и номер страницы.
     * Публикуется это же имя, только с расширением `.jpg`.
     */
    fun galleryDisplayName(pageIndex: Int, timestamp: Long = System.currentTimeMillis()): String {
        val stamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date(timestamp))
        return "${GALLERY_NAME_PREFIX}_${stamp}_p${pageIndex + 1}"
    }

    /** Все скриншоты для конкретной главы (в порядке добавления). */
    fun forChapter(chapterId: Long): List<OcrScreenshotEntry> =
        _entries.value.filter { it.chapterId == chapterId }

    /** Все скриншоты для конкретной страницы. */
    fun forPage(chapterId: Long, pageIndex: Int): List<OcrScreenshotEntry> =
        _entries.value.filter { it.chapterId == chapterId && it.pageIndex == pageIndex }

    /** Очистить буфер. */
    fun clear() {
        _entries.value.forEach { deleteImageFile(it) }
        _entries.value = emptyList()
        _lastEntry.value = null
        version++
        persist()
    }

    /** Очистить скриншоты одной главы. */
    fun clearChapter(chapterId: Long) {
        val (keep, remove) = _entries.value.partition { it.chapterId != chapterId }
        remove.forEach { deleteImageFile(it) }
        _entries.value = keep
        if (_lastEntry.value?.chapterId == chapterId) _lastEntry.value = null
        version++
        persist()
    }

    /** Текущее количество записей в буфере. */
    fun size(): Int = _entries.value.size

    /** Размер файлов скриншотов (JSON + JPEG-кадры) в байтах. */
    fun diskSizeBytes(): Long {
        val jsonSize = persistFile?.length() ?: 0L
        val imagesSize = _entries.value.sumOf { it.imagePath?.let { p -> runCatching { File(p).length() }.getOrDefault(0L) } ?: 0L }
        return jsonSize + imagesSize
    }

    // ---- Внутренние ----

    /**
     * Вставка в MediaStore (Android 10+). Само разрешение на запись в
     * `Pictures` приложению не нужно — картинка сразу становится видна
     * Галерее. Если запись в поток не удалась, вставку откатываем: иначе в
     * `Pictures/Yomikai` остаётся файл нулевого размера, который галерея
     * показывает как «битую» картинку.
     */
    private fun insertIntoMediaStore(context: Context, jpeg: ByteArray, name: String): Uri? {
        val resolver = context.contentResolver
        val values = ContentValues().apply {
            put(MediaStore.MediaColumns.DISPLAY_NAME, name)
            put(MediaStore.MediaColumns.MIME_TYPE, JPEG_MIME)
            put(
                MediaStore.MediaColumns.RELATIVE_PATH,
                "${Environment.DIRECTORY_PICTURES}/$GALLERY_DIR_NAME",
            )
            put(MediaStore.MediaColumns.DATE_MODIFIED, System.currentTimeMillis() / 1000)
        }
        val uri = resolver.insert(
            MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY),
            values,
        ) ?: run {
            logcat(LogPriority.WARN) { "OcrScreenshotBuffer: MediaStore insert returned null for $name" }
            return null
        }
        return try {
            val output = resolver.openOutputStream(uri, "w")
            if (output == null) {
                runCatching { resolver.delete(uri, null, null) }
                logcat(LogPriority.WARN) { "OcrScreenshotBuffer: openOutputStream returned null for $name" }
                null
            } else {
                output.use { it.write(jpeg) }
                uri
            }
        } catch (e: Exception) {
            runCatching { resolver.delete(uri, null, null) }
            throw e
        }
    }

    /**
     * Фолбэк для Android 8–9: публичные «Pictures» ещё пишутся файлом.
     *
     * Тут MediaStore ещё не индексирует файл за нас, поэтому после записи
     * просим сканер перечитать каталог — иначе «Галерея» покажет файл только
     * после перезагрузки, а это ровно тот случай, когда читатель «не находит
     * файл НИГДЕ». На Android 10+ MediaStore индексирует вставку сам, там
     * сканер не нужен.
     */
    @Suppress("DEPRECATION")
    private fun writeToPublicPictures(context: Context, jpeg: ByteArray, name: String): Uri? {
        if (
            ContextCompat.checkSelfPermission(context, Manifest.permission.WRITE_EXTERNAL_STORAGE) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            logcat(LogPriority.WARN) {
                "OcrScreenshotBuffer: WRITE_EXTERNAL_STORAGE not granted, skip gallery publish"
            }
            return null
        }
        val dir = File(
            Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES),
            GALLERY_DIR_NAME,
        )
        if (!dir.exists() && !dir.mkdirs()) return null
        val file = File(dir, name)
        file.outputStream().use { it.write(jpeg) }
        runCatching {
            MediaScannerConnection.scanFile(context, arrayOf(file.absolutePath), null, null)
        }.onFailure { e ->
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: media scan failed for ${file.name}" }
        }
        return Uri.fromFile(file)
    }

    /**
     * Имя файла для галереи: MediaStore не любит слеши и прочие символы пути,
     * а расширение должно быть ровно `.jpg` — по нему галерея решает, что это
     * именно изображение, и рисует миниатюру.
     */
    private fun galleryFileName(displayName: String): String {
        val safe = displayName.substringBeforeLast('.')
            .map { ch -> if (ch.isLetterOrDigit() || ch == '-' || ch == '_') ch else '_' }
            .joinToString("")
            .take(MAX_GALLERY_NAME_LENGTH)
            .trim('_')
        return "${safe.ifBlank { "screenshot" }}.jpg"
    }

    private fun deleteImageFile(entry: OcrScreenshotEntry) {
        entry.imagePath?.let { path ->
            runCatching { File(path).delete() }.onFailure {
                logcat(LogPriority.WARN, it) { "OcrScreenshotBuffer: delete image failed" }
            }
        }
    }

    private fun persist() {
        val file = persistFile ?: return
        val entries = _entries.value
        scope.launch {
            try {
                file.writeText(json.encodeToString(entries))
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: persist failed" }
            }
        }
    }

    private fun load() {
        val file = persistFile ?: return
        if (!file.exists()) return
        try {
            val text = file.readText()
            if (text.isBlank()) return
            val loaded = json.decodeFromString<List<OcrScreenshotEntry>>(text)
            _entries.value = loaded
            _lastEntry.value = loaded.lastOrNull()
            version++
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: load failed" }
        }
    }
}

package mihon.data.ocr

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import androidx.core.app.NotificationCompat
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat

/**
 * Шторка уведомлений для распознанного текста.
 *
 * Запрос пользователя: «уменьш оверлей распознаного текста либо вынеси в шторку уведомлений».
 * Решение:
 *  - Оверлей по умолчанию — компактный (320dp карточка), а не на 70% экрана
 *  - Опция `pref_ocr_to_notification` дублирует распознанный текст в Notification
 *    с действиями Копировать / Озвучить / Закрыть — не перекрывает читалку
 *  - Стриминг: пока OCR идёт по тайлам, уведомление обновляется построчно
 */
object OcrNotificationManager {

    private const val CHANNEL_ID = "yomikai_ocr"
    private const val CHANNEL_NAME = "Распознанный текст"
    private const val NOTIF_ID = 4201

    private val _lastText = MutableStateFlow<String?>(null)
    val lastText: StateFlow<String?> = _lastText

    fun ensureChannel(context: Context) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        if (nm.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            CHANNEL_NAME,
            NotificationManager.IMPORTANCE_LOW,
        ).apply {
            description = "Распознанный OCR-текст из читалки и браузера"
            setShowBadge(false)
            enableVibration(false)
            setSound(null, null)
        }
        nm.createNotificationChannel(channel)
    }

    fun show(
        context: Context,
        text: String,
        isStreaming: Boolean = false,
        onCopy: (() -> Unit)? = null,
        onSpeak: (() -> Unit)? = null,
    ) {
        if (text.isBlank()) return
        _lastText.value = text
        ensureChannel(context)
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        val preview = text.take(512)
        val bigText = if (isStreaming) "$preview\n…распознаётся…" else preview

        val builder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(android.R.drawable.ic_menu_view)
            .setContentTitle(if (isStreaming) "Распознаётся…" else "Распознанный текст")
            .setContentText(preview.take(40))
            .setStyle(NotificationCompat.BigTextStyle().bigText(bigText))
            .setOngoing(isStreaming)
            .setOnlyAlertOnce(true)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setCategory(NotificationCompat.CATEGORY_PROGRESS)

        // Действия добавляются через PendingIntent в Activity — здесь заглушка
        // для логгирования; реальные Intent'ы ставит ReaderActivity/BrowserTab.
        if (!isStreaming) {
            builder.addAction(0, "Копировать", null)
            builder.addAction(0, "Озвучить", null)
        }

        try {
            nm.notify(NOTIF_ID, builder.build())
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrNotificationManager notify failed" }
        }
    }

    fun updateStreaming(context: Context, partialText: String) {
        show(context, partialText, isStreaming = true)
    }

    fun dismiss(context: Context) {
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        runCatching { nm.cancel(NOTIF_ID) }
        _lastText.value = null
    }
}

package eu.kanade.tachiyomi.data.cache

import android.content.Context
import android.text.format.Formatter
import com.jakewharton.disklrucache.DiskLruCache
import eu.kanade.tachiyomi.source.model.Page
import eu.kanade.tachiyomi.util.storage.DiskUtil
import eu.kanade.tachiyomi.util.storage.saveTo
import kotlinx.serialization.json.Json
import logcat.LogPriority
import okhttp3.Response
import okio.buffer
import okio.sink
import tachiyomi.core.common.util.system.logcat
import tachiyomi.domain.chapter.model.Chapter
import java.io.File
import java.io.IOException

/**
 * Class used to create chapter cache
 * For each image in a chapter a file is created
 * For each chapter a Json list is created and converted to a file.
 * The files are in format *md5key*.0
 *
 * @param context the application context.
 */
class ChapterCache(
    private val context: Context,
    private val json: Json,
) {

    /** Cache class used for cache management. */
    private val diskCache = DiskLruCache.open(
        File(context.cacheDir, "chapter_disk_cache"),
        PARAMETER_APP_VERSION,
        PARAMETER_VALUE_COUNT,
        PARAMETER_CACHE_SIZE,
    )

    /**
     * Returns directory of cache.
     */
    private val cacheDir: File = diskCache.directory

    /**
     * Returns real size of directory.
     */
    private val realSize: Long
        get() = DiskUtil.getDirectorySize(cacheDir)

    /**
     * Returns real size of directory in human readable format.
     */
    val readableSize: String
        get() = Formatter.formatFileSize(context, realSize)

    /**
     * Get page list from cache.
     *
     * @param chapter the chapter.
     * @return the list of pages.
     */
    fun getPageListFromCache(chapter: Chapter): List<Page> {
        // Get the key for the chapter.
        val key = DiskUtil.hashKeyForDisk(getKey(chapter))

        // Convert JSON string to list of objects. Throws an exception if snapshot is null
        return diskCache.get(key).use {
            json.decodeFromString(it.getString(0))
        }
    }

    /**
     * Add page list to disk cache.
     *
     * @param chapter the chapter.
     * @param pages list of pages.
     */
    fun putPageListToCache(chapter: Chapter, pages: List<Page>) {
        // Convert list of pages to json string.
        val cachedValue = json.encodeToString(pages)

        // Initialize the editor (edits the values for an entry).
        var editor: DiskLruCache.Editor? = null

        try {
            // Get editor from md5 key.
            val key = DiskUtil.hashKeyForDisk(getKey(chapter))
            editor = diskCache.edit(key) ?: return

            // Write chapter urls to cache.
            editor.newOutputStream(0).sink().buffer().use {
                it.write(cachedValue.toByteArray())
                it.flush()
            }

            diskCache.flush()
            editor.commit()
            editor.abortUnlessCommitted()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Failed to put page list to cache" }
            // Ignore.
        } finally {
            editor?.abortUnlessCommitted()
        }
    }

    /**
     * Returns true if image is in cache.
     *
     * @param imageUrl url of image.
     * @return true if in cache otherwise false.
     */
    fun isImageInCache(imageUrl: String): Boolean {
        return try {
            val key = DiskUtil.hashKeyForDisk(imageUrl)
            val inJournal = diskCache.get(key).use { it != null }
            val fileExists = getImageFile(imageUrl).exists()
            if (inJournal && !fileExists) {
                logcat(LogPriority.WARN) { "Image is in journal but file is missing: $imageUrl" }
            }
            inJournal && fileExists
        } catch (_: IOException) {
            false
        }
    }

    /**
     * Get image file from url.
     *
     * @param imageUrl url of image.
     * @return path of image.
     */
    fun getImageFile(imageUrl: String): File {
        // Get file from md5 key.
        val imageName = DiskUtil.hashKeyForDisk(imageUrl) + ".0"
        return File(diskCache.directory, imageName)
    }

    /**
     * Add image to cache.
     *
     * @param imageUrl url of image.
     * @param response http response from page.
     * @throws IOException image error.
     */
    @Throws(IOException::class)
    fun putImageToCache(imageUrl: String, response: Response) {
        // Initialize editor (edits the values for an entry).
        var editor: DiskLruCache.Editor? = null

        try {
            // Get editor from md5 key.
            val key = DiskUtil.hashKeyForDisk(imageUrl)
            editor = diskCache.edit(key) ?: return

            // Get OutputStream and write image with Okio.
            response.body.source().saveTo(editor.newOutputStream(0))

            diskCache.flush()
            editor.commit()
        } finally {
            response.body.close()
            editor?.abortUnlessCommitted()
        }
    }

    fun clear(): Int {
        var deletedFiles = 0
        cacheDir.listFiles()?.forEach {
            if (removeFileFromCache(it.name)) {
                deletedFiles++
            }
        }
        return deletedFiles
    }

    /**
     * Remove image from cache by its url.
     *
     * v1.9.91: прочитанные онлайн-страницы автоматически освобождаются из
     * кеша после их прочтения (полный префетч главы не раздувает хранилище).
     *
     * @param imageUrl url of image.
     */
    fun removeImageFromCache(imageUrl: String) {
        try {
            diskCache.remove(DiskUtil.hashKeyForDisk(imageUrl))
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Failed to remove image from cache" }
        }
    }

    /**
     * Remove file from cache.
     *
     * @param file name of file "md5.0".
     * @return status of deletion for the file.
     */
    private fun removeFileFromCache(file: String): Boolean {
        // Make sure we don't delete the journal file (keeps track of cache)
        if (file == "journal" || file.startsWith("journal.")) {
            return false
        }

        return try {
            // Remove the extension from the file to get the key of the cache
            val key = file.substringBeforeLast(".")
            // Remove file from cache
            diskCache.remove(key)
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Failed to remove file from cache" }
            false
        }
    }

    private fun getKey(chapter: Chapter): String {
        return "${chapter.mangaId}${chapter.url}"
    }
}

/** Application cache version.  */
private const val PARAMETER_APP_VERSION = 1

/** The number of values per cache entry. Must be positive.  */
private const val PARAMETER_VALUE_COUNT = 1

/** The maximum number of bytes this cache should use to store.  */
// v1.9.91: читалка кеширует ВСЕ страницы главы при онлайн-чтении (полный
// префетч), чтобы книгу можно было дочитать офлайн с места остановки.
// 100 МБ LRU вытеснял первые страницы большого тома — поднимаем до 1 ГБ.
private const val PARAMETER_CACHE_SIZE = 1024L * 1024 * 1024

