package eu.kanade.tachiyomi.data.tts

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.os.Build
import androidx.core.app.NotificationCompat
import eu.kanade.tachiyomi.R
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat

/**
 * Уведомление «Сейчас читается»: распознанный текст страницы + кнопка
 * «⏹ Остановить» прямо в шторке. Текст остаётся в уведомлении, даже когда
 * озвучка закончилась — можно перечитать.
 */
object TtsReadingNotifier {

    private const val CHANNEL_ID = "yomikai_tts_reading"
    private const val NOTIFICATION_ID = 0x77A1
    private const val ACTION_STOP = "app.yomikai.TTS_STOP"

    private var receiverRegistered = false

    /**
     * Читатель нажал «⏹ Остановить» в шторке.
     *
     * Кнопка раньше только глушила синтез: цикл авточтения продолжал листать
     * главу, кадр за кадром проглатывался в тишину, и читатель получал
     * пролистанную главу вместо остановки. Теперь запрос доходит до цикла
     * через [consumeStopRequest].
     */
    @Volatile
    private var stopRequested = false

    /**
     * Забрать запрос «остановить», если он был. Одноразово.
     *
     * Запрос сбрасывается чтением, а не показом уведомления: показ случается
     * в начале каждого кадра и затер бы ответ, который читатель уже дал.
     */
    fun consumeStopRequest(): Boolean {
        if (!stopRequested) return false
        stopRequested = false
        return true
    }

    private val stopReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context, intent: Intent) {
            if (intent.action == ACTION_STOP) {
                stopRequested = true
                TtsSpeaker.stop()
                dismiss(context)
            }
        }
    }

    /**
     * Лимит текста в уведомлении.
     *
     * Android отбрасывает Notification, чей суммарный размер превышает
     * ~500 КБ (RemoteViews / Bundle), и падает с TransactionTooLargeException
     * либо DeadObjectException, залив logcat простынёй. Полная страница OCR
     * легко даёт несколько тысяч символов, поэтому режем жёстко.
     */
    private const val MAX_NOTIFICATION_TEXT = 800

    /**
     * Показать уведомление о чтении.
     *
     * [pageLabel] — где читатель находится в главе («Страница 3 из 20»).
     * Показывается под заголовком: авточтение читает главу, а не одну
     * страницу, и без такой подсказки шторка выглядит как зависшая на первой.
     */
    fun show(context: Context, text: String, pageLabel: String? = null) {
        if (text.isBlank()) return
        val app = context.applicationContext
        val nm = app.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            nm.createNotificationChannel(
                NotificationChannel(
                    CHANNEL_ID,
                    "Озвучка страниц",
                    NotificationManager.IMPORTANCE_LOW,
                ),
            )
        }

        if (!receiverRegistered) {
            val filter = IntentFilter(ACTION_STOP)
            try {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                    app.registerReceiver(stopReceiver, filter, Context.RECEIVER_NOT_EXPORTED)
                } else {
                    @Suppress("UnspecifiedRegisterReceiverFlag")
                    app.registerReceiver(stopReceiver, filter)
                }
                receiverRegistered = true
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "Failed to register TTS stop receiver" }
            }
        }

        val stopIntent = PendingIntent.getBroadcast(
            app,
            0,
            Intent(ACTION_STOP).setPackage(app.packageName),
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE,
        )

        val safeText = text.take(MAX_NOTIFICATION_TEXT)
        val notification = NotificationCompat.Builder(app, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_mihon)
            .setContentTitle(pageLabel?.let { "🔊 Читается глава · $it" } ?: "🔊 Читается страница")
            .setContentText(safeText.take(120))
            .setStyle(NotificationCompat.BigTextStyle().bigText(safeText))
            .setOnlyAlertOnce(true)
            .setOngoing(false)
            .addAction(0, "⏹ Остановить", stopIntent)
            .build()

        // Без разрешения POST_NOTIFICATIONS (Android 13+) notify() бросает
        // SecurityException; уведомление — не повод ронять читалку.
        try {
            nm.notify(NOTIFICATION_ID, notification)
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "TTS notification rejected" }
        }
    }

    fun dismiss(context: Context) {
        val nm = context.applicationContext
            .getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        nm.cancel(NOTIFICATION_ID)
    }
}

package mihon.data.ocr

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import androidx.core.app.NotificationCompat
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat

/**
 * Шторка уведомлений для распознанного текста.
 *
 * Запрос пользователя: «уменьш оверлей распознаного текста либо вынеси в шторку уведомлений».
 * Решение:
 *  - Оверлей по умолчанию — компактный (320dp карточка), а не на 70% экрана
 *  - Опция `pref_ocr_to_notification` дублирует распознанный текст в Notification
 *    с действиями Копировать / Озвучить / Закрыть — не перекрывает читалку
 *  - Стриминг: пока OCR идёт по тайлам, уведомление обновляется построчно
 */
object OcrNotificationManager {

    private const val CHANNEL_ID = "yomikai_ocr"
    private const val CHANNEL_NAME = "Распознанный текст"
    private const val NOTIF_ID = 4201

    private val _lastText = MutableStateFlow<String?>(null)
    val lastText: StateFlow<String?> = _lastText

    fun ensureChannel(context: Context) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        if (nm.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            CHANNEL_NAME,
            NotificationManager.IMPORTANCE_LOW,
        ).apply {
            description = "Распознанный OCR-текст из читалки и браузера"
            setShowBadge(false)
            enableVibration(false)
            setSound(null, null)
        }
        nm.createNotificationChannel(channel)
    }

    fun show(
        context: Context,
        text: String,
        isStreaming: Boolean = false,
        onCopy: (() -> Unit)? = null,
        onSpeak: (() -> Unit)? = null,
    ) {
        if (text.isBlank()) return
        _lastText.value = text
        ensureChannel(context)
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        val preview = text.take(512)
        val bigText = if (isStreaming) "$preview\n…распознаётся…" else preview

        val builder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(android.R.drawable.ic_menu_view)
            .setContentTitle(if (isStreaming) "Распознаётся…" else "Распознанный текст")
            .setContentText(preview.take(40))
            .setStyle(NotificationCompat.BigTextStyle().bigText(bigText))
            .setOngoing(isStreaming)
            .setOnlyAlertOnce(true)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setCategory(NotificationCompat.CATEGORY_PROGRESS)

        // Действия добавляются через PendingIntent в Activity — здесь заглушка
        // для логгирования; реальные Intent'ы ставит ReaderActivity/BrowserTab.
        if (!isStreaming) {
            builder.addAction(0, "Копировать", null)
            builder.addAction(0, "Озвучить", null)
        }

        try {
            nm.notify(NOTIF_ID, builder.build())
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrNotificationManager notify failed" }
        }
    }

    fun updateStreaming(context: Context, partialText: String) {
        show(context, partialText, isStreaming = true)
    }

    fun dismiss(context: Context) {
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        runCatching { nm.cancel(NOTIF_ID) }
        _lastText.value = null
    }
}

package eu.kanade.tachiyomi.ui.overlay

import android.content.Context
import android.graphics.Bitmap
import android.graphics.PixelFormat
import android.graphics.Rect
import android.hardware.display.DisplayManager
import android.hardware.display.VirtualDisplay
import android.media.ImageReader
import android.os.Handler
import android.os.HandlerThread
import android.util.DisplayMetrics
import android.util.Log
import android.view.WindowManager

/**
 * Захват экрана через MediaProjection и вырезание рамки.
 *
 * Перенесено из отдельного приложения overlay-reader в основной Yomikai:
 * режим «рамка поверх окна» должен работать без установки второй программы.
 *
 * VirtualDisplay создаётся один раз и держится до остановки — это
 * единственный надёжный путь на Android 14+, где пересоздание дисплеев
 * одноразовыми проекциями запрещено.
 */
class OverlayCaptureEngine(
    context: Context,
    private val projection: android.media.projection.MediaProjection,
) {
    private val appContext = context.applicationContext

    private var thread: HandlerThread? = null
    private var handler: Handler? = null
    private var reader: ImageReader? = null
    private var display: VirtualDisplay? = null
    private var sizeW: Int = 0
    private var sizeH: Int = 0
    private var density: Int = 0

    /** Размер захватываемого экрана в px (актуальны после первого capture). */
    var screenWidth: Int = 0
        private set
    var screenHeight: Int = 0
        private set

    /** Захватить текущий кадр и вернуть битмап области [rect] (в экранных px). */
    fun capture(rect: Rect): Bitmap? {
        if (display == null && !ensureStarted()) return null

        // Статичный экран может долго не порождать новых кадров (AUTO_MIRROR
        // отрисовывает только «грязные» области) — крутимся до 3 секунд.
        val succeedAt = System.currentTimeMillis() + 3000
        var image: android.media.Image? = null
        while (image == null && System.currentTimeMillis() < succeedAt) {
            image = reader?.acquireLatestImage()
            if (image == null) Thread.sleep(120)
        }
        val img = image ?: return null
        return try {
            val full = copyImage(img) ?: return null
            try {
                val left = rect.left.coerceIn(0, full.width - 1)
                val top = rect.top.coerceIn(0, full.height - 1)
                val right = rect.right.coerceIn(left + 1, full.width)
                val bottom = rect.bottom.coerceIn(top + 1, full.height)
                Bitmap.createBitmap(full, left, top, right - left, bottom - top)
            } finally {
                if (!full.isRecycled) full.recycle()
            }
        } finally {
            img.close()
        }
    }

    private fun ensureStarted(): Boolean {
        if (display != null && reader != null) return true
        // Предыдущая попытка могла упасть уже после создания ImageReader:
        // тогда reader остался не-null, а display — null, и ensureStarted()
        // больше никогда не доходил до createVirtualDisplay (захват умирал
        // навсегда). Перед повтором разбираем half-initialized состояние.
        releaseCaptureResources()

        val metrics = DisplayMetrics()
        @Suppress("DEPRECATION")
        (appContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager)
            .defaultDisplay
            .getRealMetrics(metrics)
        sizeW = metrics.widthPixels
        sizeH = metrics.heightPixels
        density = metrics.densityDpi
        screenWidth = sizeW
        screenHeight = sizeH
        if (sizeW <= 0 || sizeH <= 0) return false

        thread = HandlerThread("overlay_capture").also { it.start() }
        handler = Handler(thread!!.looper)
        reader = ImageReader.newInstance(sizeW, sizeH, PixelFormat.RGBA_8888, 2)
        display = try {
            projection.createVirtualDisplay(
                "yomikai_overlay_capture",
                sizeW,
                sizeH,
                density,
                DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                reader!!.surface,
                null,
                handler,
            )
        } catch (e: Exception) {
            Log.e("YomikaiOverlayCapture", "createVirtualDisplay failed", e)
            null
        }
        if (display == null) {
            // Чистим за собой, чтобы следующий capture() честно попробовал снова.
            releaseCaptureResources()
        }
        return display != null
    }

    /**
     * Гасит только собственные ресурсы захвата. MediaProjection не трогаем:
     * она принадлежит сервису, и её остановка погасила бы всю сессию.
     */
    private fun releaseCaptureResources() {
        runCatching { display?.release() }
        runCatching { reader?.close() }
        display = null
        reader = null
        handler?.looper?.quitSafely()
        thread?.join(500)
        thread = null
        handler = null
    }

    private fun copyImage(image: android.media.Image): Bitmap? {
        val plane = image.planes[0]
        val buffer = plane.buffer
        val pixelStride = plane.pixelStride
        val rowStride = plane.rowStride
        val rowPadding = rowStride - pixelStride * image.width
        if (rowPadding < 0) return null

        val aux = Bitmap.createBitmap(
            image.width + rowPadding / pixelStride,
            image.height,
            Bitmap.Config.ARGB_8888,
        )
        aux.copyPixelsFromBuffer(buffer)
        val bmp = Bitmap.createBitmap(aux, 0, 0, image.width, image.height)
        if (!aux.isRecycled) aux.recycle()
        return bmp
    }

    fun stop() {
        releaseCaptureResources()
        runCatching { projection.stop() }
    }
}

