import android.graphics.Rect
import android.util.Log
import eu.kanade.tachiyomi.data.tts.TtsSpeaker
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull
import mihon.data.ocr.OcrPlugins
import mihon.domain.ocr.model.OcrImage
import mihon.domain.ocr.repository.OcrRepository
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import kotlin.coroutines.coroutineContext

/**
 * Чтение рамки поверх чужого приложения.
 *
 * Цикл: снять кадр области → распознать → озвучить → дождаться конца
 * речи → отправить свайп → повторить.
 *
 * Скролл наш собственный, а не приложения: приложение может вообще не
 * иметь прокрутки или листать по-своему, поэтому продвижение выполняется
 * жестом через [OverlayGestureService].
 */
class OverlayAutoReader(
    private val context: Context,
    private val capture: OverlayCaptureEngine,
) {
    private val prefs: OcrPreferences by lazy { Injekt.get() }

    /** Сколько ждать конца речи перед прокруткой, мс. */
    private val pauseAfterSpeechMs: Long get() = prefs.overlayReadPause().get().coerceIn(0, 10_000).toLong()

    /** Столько ждём после свайпа, пока приложение перерисует кадр. */
    private val settleAfterScrollMs: Long get() = prefs.overlayScrollSettle().get().coerceIn(200, 5_000).toLong()

    private val scrollDistance: Float
        get() = prefs.overlayScrollStep().get().coerceIn(10, 90) / 100f

    /**
     * Движок оверлея — тот, что выбран для домена «приложения».
     *
     * Вызывается только когда переключатель «свой движок» включён: тогда
     * распознавание идёт именно им, а не движком читалки.
     */
    private fun engineModel(): mihon.domain.ocr.model.OcrModel = prefs.appOcrEngine().get()

    /** Что на самом деле распознаёт: свой движок оверлея или движок читалки. */
    private fun currentModel(): mihon.domain.ocr.model.OcrModel =
        if (prefs.overlayOwnEngine().get()) engineModel() else prefs.ocrModel().get()

    fun engineTitle(): String = OcrPlugins.byModel(currentModel()).title

    /**
     * Один кадр области, распознанный в текст.
     *
     * @return текст или null, если кадр не удалось снять/прочитать
     */
    suspend fun readOnce(region: Rect): String? = withContext(Dispatchers.IO) {
        val bmp = runCatching { capture.capture(region) }.getOrNull() ?: return@withContext null
        try {
            val pixels = IntArray(bmp.width * bmp.height)
            bmp.getPixels(pixels, 0, bmp.width, 0, 0, bmp.width, bmp.height)
            val image = OcrImage(bmp.width, bmp.height, pixels)
            // Движок передаётся явно: иначе распознавание всё равно ушло бы
            // в движок читалки, и переключатель «свой движок» ничего бы не
            // менял, кроме подписи на кнопке.
            Injekt.get<OcrRepository>()
                .recognizeText(image, if (prefs.overlayOwnEngine().get()) engineModel() else null)
                .trim()
                .takeIf { it.isNotBlank() }
        } catch (e: Exception) {
            Log.e(TAG, "overlay read failed", e)
            null
        } finally {
            if (!bmp.isRecycled) bmp.recycle()
        }
    }

    /**
     * Запускает цикл чтения.
     *
     * @param onPage сообщает, что распознан новый экран (для панели оверлея)
     * @param onNote сообщает, что делает цикл (для панели оверлея)
     * @return задача цикла — её отмена останавливает чтение
     */
    fun start(
        scope: CoroutineScope,
        region: Rect,
        onPage: (String) -> Unit = {},
        onNote: (String) -> Unit = {},
    ): Job = scope.launch {
        var lastText: String? = null
        var repeats = 0
        onNote("Чтение начато · ${engineTitle()}")

        // Служба доступности может подключиться позже, чем нажали «Читать»:
        // пока она выключена, листать нечем, и раньше цикл молча завершался
        // после первой реплики. Теперь ждём и продолжаем.
        if (!awaitGestureService(onNote)) return@launch

        while (isActive) {
            val text = readOnce(region)
            if (text == null) {
                onNote("Не удалось прочитать кадр")
                // Кадр может не успеть прогрузиться; ждать и пробовать
                // снова вхолостую только жжёт батарею.
                delay(RETRY_DELAY_MS)
                continue
            }

            // Один и тот же текст после прокрутки означает, что приложение
            // не пролистнулось: озвучивать его второй раз бессмысленно, и
            // цикл ушёл бы в бесконечный повтор одного и того же.
            if (text == lastText) {
                repeats++
                if (repeats >= MAX_REPEATS) {
                    onNote("Приложение не пролистывается — листаю иначе")
                    // Последняя попытка: свайп длиннее и из другой точки.
                    // Некоторые приложения слушают жест только у самого низа
                    // экрана, и свайп по центру рамки они игнорируют.
                    if (!scrollWithFallback(region)) {
                        onNote("Прокрутка не идёт — проверьте Службу доступности")
                        return@launch
                    }
                    repeats = 0
                }
            } else {
                repeats = 0
                lastText = text
                onPage(text)
                speakAndWait(text)
            }

            if (!scrollForward(region)) return@launch
            delay(settleAfterScrollMs)
        }
    }

    /**
     * Ждёт включения Службы доступности, пока её нет.
     *
     * Раньше цикл на первой же неудаче просто завершался, и читатель видел
     * одну озвученную реплику без прокрутки и без объяснения. Теперь при
     * выключенной службе чтение честно ждёт и говорит, что именно надо
     * включить, но ждёт не бесконечно: иначе кнопка «Стоп» пришлось бы искать
     * вслепую.
     *
     * @return false, если службу так и не включили либо чтение отменили
     */
    private suspend fun awaitGestureService(onNote: (String) -> Unit): Boolean {
        var waited = 0L
        // currentCoroutineContext(), а не isActive: здесь нет CoroutineScope,
        // и isActive без получателя просто не разрешается.
        while (currentCoroutineContext().isActive &&
            !OverlayGestureService.isEnabled() &&
            waited < GESTURE_WAIT_MAX_MS
        ) {
            if (waited == 0L) onNote("Включите Службу доступности — жду, чтобы листать")
            delay(GESTURE_WAIT_MS)
            waited += GESTURE_WAIT_MS
        }
        if (!OverlayGestureService.isEnabled()) {
            onNote("Без Службы доступности листать нечем — чтение остановлено")
            return false
        }
        return currentCoroutineContext().isActive
    }

    /**
     * Прокрутка вперёд с проверкой результата.
     *
     * Прежний код останавливал чтение на первом же отказе жеста, и читатель
     * слышал одну реплику — после неё не было ни прокрутки, ни объяснения.
     * Теперь отказ не завершает чтение: жест повторяется, а если и он не
     * прошёл, причина называется прямо.
     */
    private suspend fun scrollForward(region: Rect): Boolean {
        repeat(SCROLL_ATTEMPTS) {
            if (OverlayGestureService.swipeAndAwait(verticalSwipe(region, scrollDistance))) return true
            delay(SCROLL_RETRY_MS)
        }
        // Жест уходит, но экран не меняется: значит точка не слушается.
        return scrollWithFallback(region)
    }

    /** Свайп у самого низа рамки и длиннее обычного — последний довод. */
    private suspend fun scrollWithFallback(region: Rect): Boolean {
        val dy = (region.height() * FALLBACK_STEP).toInt()
        if (dy < 1) return false
        val x = region.left + (region.width() * FALLBACK_X).toInt()
        return OverlayGestureService.swipeAndAwait(
            fromX = x,
            fromY = region.bottom - (region.height() * 0.05f).toInt(),
            toX = x,
            toY = region.bottom - (region.height() * 0.05f).toInt() - dy,
            durationMs = FALLBACK_MS,
        )
    }

    /** Пара координат свайпа по центру области на долю [fraction] её высоты. */
    private fun verticalSwipe(region: Rect, fraction: Float): GestureSwipe {
        val dy = (region.height() * fraction).toInt()
        val cx = region.centerX()
        val cy = region.centerY()
        return GestureSwipe(cx, cy + dy, cx, cy - dy)
    }

    /**
     * Озвучивает и ждёт конца речи, затем паузу.
     *
     * `TtsSpeaker` не отдаёт «прочитано» промисом, но сообщает состояние
     * через колбэк: [onState] приходит false, когда речь закончилась.
     */
    private suspend fun speakAndWait(text: String) {
        val done = kotlinx.coroutines.CompletableDeferred<Unit>()
        var started = false
        TtsSpeaker.speak(context, text) { speaking ->
            if (speaking) {
                started = true
            } else if (started) {
                done.complete(Unit)
            }
        }
        // Если движок не сообщил о начале (например, голос не найден),
        // ждать завершения бессмысленно — цикл обязан идти дальше.
        if (!started) {
            delay(NO_SPEECH_GRACE_MS)
            return
        }
        withTimeoutOrNull(MAX_SPEECH_MS) { done.await() }
        if (coroutineContext.isActive && pauseAfterSpeechMs > 0) delay(pauseAfterSpeechMs)
    }

    /**
     * Листать назад по одному экрану — кнопка «▲ назад» на панели.
     *
     * Работает и без запущенного цикла чтения: пригодится, чтобы вернуться к
     * предыдущей реплике вручную.
     */
    suspend fun scrollBack(region: Rect): Boolean {
        val dy = (region.height() * scrollDistance).toInt()
        if (dy < 1) return false
        val cx = region.centerX()
        val cy = region.centerY()
        return OverlayGestureService.swipeAndAwait(GestureSwipe(cx, cy - dy, cx, cy + dy))
    }

    companion object {
        private const val TAG = "OverlayAutoReader"
        private const val RETRY_DELAY_MS = 900L

        /** Сколько ждать, если движок вообще не начал говорить. */
        private const val NO_SPEECH_GRACE_MS = 300L

        /** Потолок одной реплики: иначе зависший движок стопорит цикл. */
        private const val MAX_SPEECH_MS = 5 * 60_000L

        /** Сколько одинаковых кадров подряд считаем «не пролисталось». */
        private const val MAX_REPEATS = 2

        /** Сколько раз повторить жест, прежде чем менять геометрию. */
        private const val SCROLL_ATTEMPTS = 2

        /** Пауза между попытками жеста, мс. */
        private const val SCROLL_RETRY_MS = 350L

        /** Как часто проверять, не включили ли Службу доступности, мс. */
        private const val GESTURE_WAIT_MS = 1_500L

        /** Сколько ждать включения Службы, прежде чем остановить чтение, мс. */
        private const val GESTURE_WAIT_MAX_MS = 90_000L

        /** Доля высоты области для запасного свайпа. */
        private const val FALLBACK_STEP = 0.7f

        /** Запасной свайп идёт левее центра: там меньше всего кнопок. */
        private const val FALLBACK_X = 0.35f

        /** Запасной свайп длиннее и медленнее — его замечают даже «вялые» списки. */
        private const val FALLBACK_MS = 480L
    }
}

package mihon.data.ocr

import android.Manifest
import android.content.ContentValues
import android.content.Context
import android.content.pm.PackageManager
import android.media.MediaScannerConnection
import android.net.Uri
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import androidx.core.content.ContextCompat
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import mihon.domain.ocr.model.OcrRegion
import tachiyomi.core.common.util.system.logcat
import java.io.File
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Кольцевой буфер скриншотов авточтения — текст регионов (~1-5 KB) плюс
 * необязательный JPEG-кадр каждого скриншота.
 *
 * Хранит до [MAX_ENTRIES] последних записей в JSON-файле. Если запись создана
 * с JPEG-кадром ([OcrScreenshotEntry.add]), картинка пишется в каталог
 * `filesDir/screenshots_images/<id>.jpg`, а в записи сохраняется её путь —
 * галерея показывает реальное изображение с оверлеем регионов.
 *
 * При превышении лимита самая старая запись и её файл удаляются.
 */
object OcrScreenshotBuffer {

    private const val DEFAULT_MAX_ENTRIES = 50
    private const val FILE_NAME = "screenshots.json"
    private const val IMAGE_DIR_NAME = "screenshots_images"

    /** Публичная папка в «Pictures», куда публикуются скриншоты для Галереи. */
    private const val GALLERY_DIR_NAME = "Yomikai"
    private const val JPEG_MIME = "image/jpeg"

    /** Префикс имени файла в галерее: по нему кадр узнаётся среди прочих. */
    private const val GALLERY_NAME_PREFIX = "Yomikai"

    /** Ограничение длины DISPLAY_NAME: длинные имена обрезаются системой. */
    private const val MAX_GALLERY_NAME_LENGTH = 80

    /** Лимит записей (кольцевой буфер). Меняется через dev-панель. */
    @kotlin.jvm.Volatile
    var maxEntries: Int = DEFAULT_MAX_ENTRIES

    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true; prettyPrint = false }

    private val _entries = MutableStateFlow<List<OcrScreenshotEntry>>(emptyList())
    val entries: StateFlow<List<OcrScreenshotEntry>> = _entries.asStateFlow()

    /** Последний добавленный скриншот — для индикатора в углу читалки. */
    private val _lastEntry = MutableStateFlow<OcrScreenshotEntry?>(null)
    val lastEntry: StateFlow<OcrScreenshotEntry?> = _lastEntry.asStateFlow()

    /**
     * Счётчик изменений буфера: вьюха страницы рисует пометки порядка чтения
     * на каждом кадре, а фильтровать список записей заново 60 раз в секунду
     * при прокрутке длинного вебтуна незачем. Кэш вьюхи инвалидируется этим
     * числом, а не подпиской на поток из анимации.
     */
    @Volatile
    var version: Int = 0
        private set

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private var persistFile: File? = null
    private var imagesDir: File? = null
    private var initialized = false

    fun init(context: Context) {
        if (initialized) return
        initialized = true
        persistFile = File(context.filesDir, FILE_NAME)
        imagesDir = File(context.filesDir, IMAGE_DIR_NAME).apply { mkdirs() }
        load()
    }

    // ---- Публичные методы ----

    /**
     * Добавить запись скриншота (текст + регионы ~1-5 KB, плюс необязательный
     * JPEG-кадр [imageJpeg], который пишется файлом и показывается в галерее).
     * Если буфер полон — самая старая запись (и её файл) удаляется.
     *
     * @return Созданная запись.
     */
    /**
     * Добавить запись в буфер.
     *
     * synchronized не лишний: писателей стало два — авточтение пишет кадр за
     * кадром, а кнопка «Скриншот сейчас» добавляет запись из отдельной
     * корутины. Без блокировки оба собирали список от одного и того же
     * состояния, и одна запись молча пропадала.
     *
     * [sourceWidth]/[sourceHeight]/[scanCrop] — геометрия того, какая часть
     * файла страницы попала в кадр: без неё нормализованные координаты
     * [regions] относятся к уменьшенному и обрезанному OCR-битмапу, и в книге
     * по ним нельзя нарисовать ничего. Оставленные значения по умолчанию означают
     * «геометрии нет»: запись читается как раньше, проекция для неё
     * не выполняется.
     */
    @Synchronized
    fun add(
        chapterId: Long,
        pageIndex: Int,
        scrollFraction: Float,
        regions: List<OcrRegion>,
        engineUsed: String,
        imageWidth: Int = 0,
        imageHeight: Int = 0,
        imageJpeg: ByteArray? = null,
        scanRegion: String = "viewport",
        sourceWidth: Int = 0,
        sourceHeight: Int = 0,
        scanCrop: SerializableNormalizedRect = SerializableNormalizedRect(),
    ): OcrScreenshotEntry {
        val id = System.currentTimeMillis()
        val serializableRegions = regions.map { SerializableOcrRegion.fromOcrRegion(it) }
        val summaryText = regions.joinToString(" ") { it.text.trim() }.trim()
        val imagePath = imageJpeg?.let { jpeg ->
            imagesDir?.let { dir ->
                File(dir, "$id.jpg").apply { writeBytes(jpeg) }.absolutePath
            }
        }
        val entry = OcrScreenshotEntry(
            id = id,
            chapterId = chapterId,
            pageIndex = pageIndex,
            scrollFraction = scrollFraction,
            timestamp = id,
            regions = serializableRegions,
            engineUsed = engineUsed,
            summaryText = summaryText,
            imageWidth = imageWidth,
            imageHeight = imageHeight,
            imagePath = imagePath,
            scanRegion = scanRegion,
            sourceWidth = sourceWidth,
            sourceHeight = sourceHeight,
            scanCrop = scanCrop,
        )

        val current = _entries.value.toMutableList()
        val limit = maxEntries.coerceAtLeast(1)
        if (current.size >= limit) {
            val evicted = current.removeFirst()
            deleteImageFile(evicted)
        }
        current.add(entry)
        _entries.value = current
        _lastEntry.value = entry
        version++
        persist()
        return entry
    }
    /**
     * Опубликовать JPEG-кадр в общем хранилище: `Pictures/Yomikai`, то есть
     * ровно там, где его видят «Галерея», «Файлы» и любой файловый менеджер.
     *
     * Зачем это нужно рядом с [add]: картинки буфера лежат в приватном
     * `filesDir/screenshots_images/`, куда не смотрят ни MediaStore, ни
     * FileProvider, ни галерея телефона. Читатель нажимал «Скриншот сейчас» и
     * не находил файл НИГДЕ. Поэтому тот же JPEG дополнительно уходит в
     * публичное хранилище, а внутренняя копия остаётся для вкладки «Скриншоты»
     * (там кадр показывается вместе с оверлеем распознанных регионов).
     *
     * На Android 10+ (MediaStore) разрешение на запись не нужно вовсе, а при
     * targetSdk 36 писать в публичные папки через `File` уже нельзя. Ветка для
     * API < 29 нужна только для Android 8–9: там пишем файлом, но лишь если
     * WRITE_EXTERNAL_STORAGE реально выдан — с targetSdk 36 система может не
     * выдать его вовсе, и тогда возвращаем null, а не падаем.
     *
     * Ошибки никогда не пробрасываются: публикация — дополнение, из-за неё
     * скриншот не должен теряться (в logcat пишем причину).
     *
     * @return Uri опубликованного файла или null, если публикация не вышла.
     */
    fun publishToGallery(context: Context, jpeg: ByteArray, displayName: String): Uri? {
        val name = galleryFileName(displayName)
        return runCatching {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                insertIntoMediaStore(context, jpeg, name)
            } else {
                writeToPublicPictures(context, jpeg, name)
            }
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: gallery publish failed for $name" }
            null
        }
    }

    /**
     * Опубликовать в общую галерею JPEG уже сохранённой записи буфера — кнопка
     * «Сохранить в галерею» во вкладке «Скриншоты» идёт через неё.
     * Файл не перекодируется: в галерею уходит ровно тот кадр, который видит
     * читатель (вместе с оверлеем регионов он остаётся во внутренней копии).
     *
     * @return Uri опубликованного файла или null — у записи нет картинки, файл
     * не читается либо публикация не вышла.
     */
    fun publishEntryToGallery(context: Context, entry: OcrScreenshotEntry): Uri? {
        val path = entry.imagePath
        if (path == null) {
            logcat(LogPriority.WARN) { "OcrScreenshotBuffer: entry ${entry.id} has no image" }
            return null
        }
        val bytes = runCatching { File(path).readBytes() }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: read image failed for $path" }
            return null
        }
        return publishToGallery(context, bytes, galleryDisplayName(entry.pageIndex, entry.timestamp))
    }

    /**
     * Читаемое имя файла в галерее: `Yomikai_20260930_143512_p12`.
     *
     * Читатель ищет кадр глазами — в «Файлах», в «Галерее», в «Моих файлах» — и
     * ориентируется по имени. Папка из сотни безликих `image.jpg` ни о чём не
     * говорит, поэтому в имени есть приложение, дата, время и номер страницы.
     * Публикуется это же имя, только с расширением `.jpg`.
     */
    fun galleryDisplayName(pageIndex: Int, timestamp: Long = System.currentTimeMillis()): String {
        val stamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.US).format(Date(timestamp))
        return "${GALLERY_NAME_PREFIX}_${stamp}_p${pageIndex + 1}"
    }

    /** Все скриншоты для конкретной главы (в порядке добавления). */
    fun forChapter(chapterId: Long): List<OcrScreenshotEntry> =
        _entries.value.filter { it.chapterId == chapterId }

    /** Все скриншоты для конкретной страницы. */
    fun forPage(chapterId: Long, pageIndex: Int): List<OcrScreenshotEntry> =
        _entries.value.filter { it.chapterId == chapterId && it.pageIndex == pageIndex }

    /** Очистить буфер. */
    fun clear() {
        _entries.value.forEach { deleteImageFile(it) }
        _entries.value = emptyList()
        _lastEntry.value = null
        version++
        persist()
    }

    /** Очистить скриншоты одной главы. */
    fun clearChapter(chapterId: Long) {
        val (keep, remove) = _entries.value.partition { it.chapterId != chapterId }
        remove.forEach { deleteImageFile(it) }
        _entries.value = keep
        if (_lastEntry.value?.chapterId == chapterId) _lastEntry.value = null
        version++
        persist()
    }

    /** Текущее количество записей в буфере. */
    fun size(): Int = _entries.value.size

    /** Размер файлов скриншотов (JSON + JPEG-кадры) в байтах. */
    fun diskSizeBytes(): Long {
        val jsonSize = persistFile?.length() ?: 0L
        val imagesSize = _entries.value.sumOf { it.imagePath?.let { p -> runCatching { File(p).length() }.getOrDefault(0L) } ?: 0L }
        return jsonSize + imagesSize
    }

    // ---- Внутренние ----

    /**
     * Вставка в MediaStore (Android 10+). Само разрешение на запись в
     * `Pictures` приложению не нужно — картинка сразу становится видна
     * Галерее. Если запись в поток не удалась, вставку откатываем: иначе в
     * `Pictures/Yomikai` остаётся файл нулевого размера, который галерея
     * показывает как «битую» картинку.
     */
    private fun insertIntoMediaStore(context: Context, jpeg: ByteArray, name: String): Uri? {
        val resolver = context.contentResolver
        val values = ContentValues().apply {
            put(MediaStore.MediaColumns.DISPLAY_NAME, name)
            put(MediaStore.MediaColumns.MIME_TYPE, JPEG_MIME)
            put(
                MediaStore.MediaColumns.RELATIVE_PATH,
                "${Environment.DIRECTORY_PICTURES}/$GALLERY_DIR_NAME",
            )
            put(MediaStore.MediaColumns.DATE_MODIFIED, System.currentTimeMillis() / 1000)
        }
        val uri = resolver.insert(
            MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY),
            values,
        ) ?: run {
            logcat(LogPriority.WARN) { "OcrScreenshotBuffer: MediaStore insert returned null for $name" }
            return null
        }
        return try {
            val output = resolver.openOutputStream(uri, "w")
            if (output == null) {
                runCatching { resolver.delete(uri, null, null) }
                logcat(LogPriority.WARN) { "OcrScreenshotBuffer: openOutputStream returned null for $name" }
                null
            } else {
                output.use { it.write(jpeg) }
                uri
            }
        } catch (e: Exception) {
            runCatching { resolver.delete(uri, null, null) }
            throw e
        }
    }

    /**
     * Фолбэк для Android 8–9: публичные «Pictures» ещё пишутся файлом.
     *
     * Тут MediaStore ещё не индексирует файл за нас, поэтому после записи
     * просим сканер перечитать каталог — иначе «Галерея» покажет файл только
     * после перезагрузки, а это ровно тот случай, когда читатель «не находит
     * файл НИГДЕ». На Android 10+ MediaStore индексирует вставку сам, там
     * сканер не нужен.
     */
    @Suppress("DEPRECATION")
    private fun writeToPublicPictures(context: Context, jpeg: ByteArray, name: String): Uri? {
        if (
            ContextCompat.checkSelfPermission(context, Manifest.permission.WRITE_EXTERNAL_STORAGE) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            logcat(LogPriority.WARN) {
                "OcrScreenshotBuffer: WRITE_EXTERNAL_STORAGE not granted, skip gallery publish"
            }
            return null
        }
        val dir = File(
            Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES),
            GALLERY_DIR_NAME,
        )
        if (!dir.exists() && !dir.mkdirs()) return null
        val file = File(dir, name)
        file.outputStream().use { it.write(jpeg) }
        runCatching {
            MediaScannerConnection.scanFile(context, arrayOf(file.absolutePath), null, null)
        }.onFailure { e ->
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: media scan failed for ${file.name}" }
        }
        return Uri.fromFile(file)
    }

    /**
     * Имя файла для галереи: MediaStore не любит слеши и прочие символы пути,
     * а расширение должно быть ровно `.jpg` — по нему галерея решает, что это
     * именно изображение, и рисует миниатюру.
     */
    private fun galleryFileName(displayName: String): String {
        val safe = displayName.substringBeforeLast('.')
            .map { ch -> if (ch.isLetterOrDigit() || ch == '-' || ch == '_') ch else '_' }
            .joinToString("")
            .take(MAX_GALLERY_NAME_LENGTH)
            .trim('_')
        return "${safe.ifBlank { "screenshot" }}.jpg"
    }

    private fun deleteImageFile(entry: OcrScreenshotEntry) {
        entry.imagePath?.let { path ->
            runCatching { File(path).delete() }.onFailure {
                logcat(LogPriority.WARN, it) { "OcrScreenshotBuffer: delete image failed" }
            }
        }
    }

    private fun persist() {
        val file = persistFile ?: return
        val entries = _entries.value
        scope.launch {
            try {
                file.writeText(json.encodeToString(entries))
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: persist failed" }
            }
        }
    }

    private fun load() {
        val file = persistFile ?: return
        if (!file.exists()) return
        try {
            val text = file.readText()
            if (text.isBlank()) return
            val loaded = json.decodeFromString<List<OcrScreenshotEntry>>(text)
            _entries.value = loaded
            _lastEntry.value = loaded.lastOrNull()
            version++
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrScreenshotBuffer: load failed" }
        }
    }
}

package eu.kanade.tachiyomi.ui.overlay

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.speech.RecognitionListener
import android.speech.RecognizerIntent
import android.speech.SpeechRecognizer
import eu.kanade.tachiyomi.data.tts.AutoReadEngine
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import mihon.data.ocr.MangaTranslatorService
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * STT для игр в реальном времени: английская речь (только голоса, без
 * текста) → текст → перевод → русские голоса.
 *
 * Системный [SpeechRecognizer] с частичными результатами (partial — сразу
 * в бабл, final — перевод через [MangaTranslatorService] и озвучка через
 * [AutoReadEngine], тот же движок, что в читалке). Слушает непрерывно:
 * после конца фразы/ошибки перезапускается, пока не вызовут [stop].
 * Требует RECORD_AUDIO (запрашивается из настроек).
 */
class GameSttManager(
    private val appContext: Context,
    private val prefs: OcrPreferences = Injekt.get(),
    private val readEngine: AutoReadEngine,
) {

    /** Частичный результат — показать в бабле, не озвучивать. */
    var onPartial: ((String) -> Unit)? = null

    /** Финальный текст (уже переведённый, если перевод включён). */
    var onFinal: ((String) -> Unit)? = null

    var onError: ((String) -> Unit)? = null
    var onListeningChanged: ((Boolean) -> Unit)? = null

    val isListening: Boolean get() = listening

    private var recognizer: SpeechRecognizer? = null
    private var listening = false
    private var wantListening = false
    private val mainHandler = Handler(Looper.getMainLooper())
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main.immediate)

    fun start() {
        if (wantListening) return
        if (!SpeechRecognizer.isRecognitionAvailable(appContext)) {
            onError?.invoke("Распознавание речи недоступно на устройстве")
            return
        }
        wantListening = true
        ensureRecognizer()
        listenOnce()
    }

    fun stop() {
        wantListening = false
        mainHandler.removeCallbacksAndMessages(null)
        runCatching { recognizer?.cancel() }
        setListening(false)
    }

    fun destroy() {
        stop()
        scope.cancel()
        runCatching { recognizer?.destroy() }
        recognizer = null
    }

    private fun ensureRecognizer() {
        if (recognizer != null) return
        recognizer = SpeechRecognizer.createSpeechRecognizer(appContext).apply {
            setRecognitionListener(listener)
        }
    }

    private fun listenOnce() {
        if (!wantListening) return
        val recognizer = recognizer ?: run {
            ensureRecognizer()
            recognizer ?: return
        }
        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(
                RecognizerIntent.EXTRA_LANGUAGE_MODEL,
                RecognizerIntent.LANGUAGE_MODEL_FREE_FORM,
            )
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, prefs.sttSourceLang().get().ifBlank { "en-US" })
            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, true)
            putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 3)
            putExtra(RecognizerIntent.EXTRA_CALLING_PACKAGE, appContext.packageName)
        }
        runCatching { recognizer.startListening(intent) }.onFailure {
            scheduleRestart(800)
        }
    }

    private fun scheduleRestart(delayMs: Long) {
        if (!wantListening) return
        mainHandler.removeCallbacksAndMessages(null)
        mainHandler.postDelayed({ if (wantListening) listenOnce() }, delayMs)
    }

    private fun setListening(value: Boolean) {
        if (listening == value) return
        listening = value
        onListeningChanged?.invoke(value)
    }

    private val listener = object : RecognitionListener {
        override fun onReadyForSpeech(params: Bundle?) {
            setListening(true)
        }

        override fun onBeginningOfSpeech() = Unit
        override fun onRmsChanged(rmsdB: Float) = Unit
        override fun onBufferReceived(buffer: ByteArray?) = Unit

        override fun onEndOfSpeech() {
            setListening(false)
        }

        override fun onPartialResults(partialResults: Bundle?) {
            val text = partialResults
                ?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                ?.firstOrNull()?.trim().orEmpty()
            if (text.isNotBlank()) onPartial?.invoke(text)
        }

        override fun onResults(results: Bundle?) {
            setListening(false)
            val text = results
                ?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                ?.firstOrNull()?.trim().orEmpty()
            if (text.isBlank()) {
                scheduleRestart(300)
                return
            }
            scope.launch {
                val spoken = runCatching {
                    if (prefs.sttTranslate().get()) {
                        val src = prefs.sttSourceLang().get().substringBefore('-').ifBlank { "auto" }
                        MangaTranslatorService.translate(text, targetLang = "ru", sourceLang = src)
                            .takeIf { it.isNotBlank() } ?: text
                    } else {
                        text
                    }
                }.getOrDefault(text)
                val gender = prefs.gameVoiceGender().get().takeIf { it != "auto" }
                readEngine.speakSingle(spoken, gender)
                onFinal?.invoke(spoken)
                scheduleRestart(300)
            }
        }

        override fun onError(error: Int) {
            setListening(false)
            when (error) {
                android.speech.SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS -> {
                    wantListening = false
                    onError?.invoke("Нет разрешения на микрофон")
                    return
                }
                android.speech.SpeechRecognizer.ERROR_CLIENT,
                android.speech.SpeechRecognizer.ERROR_RECOGNIZER_BUSY,
                -> {
                    // Пересоздаём распознаватель — иначе виснет в BUSY.
                    runCatching { recognizer?.destroy() }
                    recognizer = null
                    ensureRecognizer()
                }
                else -> Unit
            }
            scheduleRestart(600)
        }

        override fun onEvent(eventType: Int, params: Bundle?) = Unit
    }
}

package eu.kanade.tachiyomi.ui.overlay

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.GestureDescription
import android.content.Context
import android.content.Intent
import android.graphics.Path
import android.net.Uri
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.provider.Settings
import android.util.Log
import android.view.accessibility.AccessibilityEvent
import eu.kanade.tachiyomi.util.system.toast
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull
import kotlin.math.abs

/**
 * Служба доступности — только чтобы отправлять чужому приложению свайпы.
 *
 * Своей прокрутки у чужого приложения взять нельзя: листать его можно
 * лишь жестом, который кто-то должен отправить. Единственный доступный
 * способ — [android.accessibilityservice.AccessibilityService].
 *
 * Ничего больше служба не делает: события не читает, узлы не обходит и
 * ничего не выполняет. Ровно один жест — свайп по заданным координатам.
 */
class OverlayGestureService : AccessibilityService() {

    override fun onServiceConnected() {
        instance = this
    }

    override fun onDestroy() {
        if (instance === this) instance = null
        super.onDestroy()
    }

    /** Служба ни на что не подписана и не должна мешатьTalkBack. */
    override fun onInterrupt() = Unit

    override fun onAccessibilityEvent(event: AccessibilityEvent?) = Unit

    companion object {
        @Volatile
        var instance: OverlayGestureService? = null
            private set

        /**
         * Поток, на котором Android ждёт результат жеста.
         *
         * Отдельный от потока сервиса оверлея: жест отправляет цикл чтения, а
         * колбэк Android обязан получить на лоопере, который живёт, пока
         * работает сама служба доступности.
         */
        private val callbackHandler by lazy { Handler(Looper.getMainLooper()) }

        /** Включена ли служба в настройках Android. */
        fun isEnabled(): Boolean = instance != null

        /**
         * Отправляет один свайп.
         *
         * @param fromX,fromY начало жеста в пикселях экрана
         * @param toX,toY конец жеста
         * @param durationMs длительность жеста: слишком короткий пролистывает
         *   на полстраницы мимо текста, слишком длинный Android не засчитывает
         *   как свайп вовсе
         * @return true, если жест ушёл в систему
         */
        fun swipe(fromX: Int, fromY: Int, toX: Int, toY: Int, durationMs: Long = SWIPE_MS): Boolean {
            val service = instance ?: return false
            if (abs(fromX - toX) < 1 && abs(fromY - toY) < 1) return false
            val path = Path().apply {
                moveTo(fromX.toFloat(), fromY.toFloat())
                lineTo(toX.toFloat(), toY.toFloat())
            }
            val gesture = GestureDescription.Builder()
                .addStroke(
                    GestureDescription.StrokeDescription(path, 0, durationMs.coerceIn(50L, 3_000L)),
                )
                .build()
            return service.dispatchGesture(gesture, null, null) == true
        }

        /**
         * Свайп с ожиданием результата.
         *
         * [swipe] возвращает лишь «жест отправлен в систему» — этого
         * недостаточно: Android может отклонить жест уже по ходу (занято
         * окно, приложение перехватило), и читатель узнаёт об этом только по
         * тому, что следующий кадр совпал с предыдущим. Здесь результат
         * сообщается системой: true — жест отработал, false — отклонён.
         */
        suspend fun swipeAndAwait(
            fromX: Int,
            fromY: Int,
            toX: Int,
            toY: Int,
            durationMs: Long = SWIPE_MS,
        ): Boolean = swipeAndAwait(GestureSwipe(fromX, fromY, toX, toY), durationMs)

        /** То же для готового описания жеста. */
        suspend fun swipeAndAwait(swipe: GestureSwipe, durationMs: Long = SWIPE_MS): Boolean {
            val service = instance ?: return false
            if (abs(swipe.fromX - swipe.toX) < 1 && abs(swipe.fromY - swipe.toY) < 1) return false
            val path = Path().apply {
                moveTo(swipe.fromX.toFloat(), swipe.fromY.toFloat())
                lineTo(swipe.toX.toFloat(), swipe.toY.toFloat())
            }
            val gesture = GestureDescription.Builder()
                .addStroke(
                    GestureDescription.StrokeDescription(path, 0, durationMs.coerceIn(50L, 3_000L)),
                )
                .build()
            val result = CompletableDeferred<Boolean>()
            // Диспатчим с главного лупера: система привязывает службу к нему,
            // и часть прошивок молча отклоняет жест, отправленный из фонового
            // потока, даже если сам вызов возвращает true.
            val sent = withContext(Dispatchers.Main.immediate) {
                service.dispatchGesture(
                    gesture,
                    object : AccessibilityService.GestureResultCallback() {
                        override fun onCompleted(gestureDescription: GestureDescription?) {
                            result.complete(true)
                        }

                        override fun onCancelled(gestureDescription: GestureDescription?) {
                            Log.w(
                                TAG,
                                "dispatchGesture отменён системой: " +
                                    "(${swipe.fromX},${swipe.fromY})→(${swipe.toX},${swipe.toY})",
                            )
                            result.complete(false)
                        }
                    },
                    callbackHandler,
                )
            }
            if (!sent) {
                Log.w(TAG, "dispatchGesture не отправлен: служба не подключена к системе")
                return false
            }
            return withTimeoutOrNull(GESTURE_TIMEOUT_MS) { result.await() } ?: false
        }

        /**
         * Свайп вверх по центру области: так листают вперёд.
         *
         * Жест идёт по вертикали центра рамки, а не всего экрана, иначе
         * палец уезжал бы в область, которую приложение не слушает.
         */
        fun scrollForward(rect: android.graphics.Rect): Boolean {
            if (rect.width() <= 0 || rect.height() <= 0) return false
            val cx = rect.centerX()
            val fromY = rect.centerY() + (rect.height() * 0.30f).toInt()
            val toY = rect.centerY() - (rect.height() * 0.30f).toInt()
            return swipe(cx, fromY, cx, toY)
        }

        /** Свайп вниз — вернуться назад. */
        fun scrollBack(rect: android.graphics.Rect): Boolean {
            if (rect.width() <= 0 || rect.height() <= 0) return false
            val cx = rect.centerX()
            val fromY = rect.centerY() - (rect.height() * 0.30f).toInt()
            val toY = rect.centerY() + (rect.height() * 0.30f).toInt()
            return swipe(cx, fromY, cx, toY)
        }

        private const val SWIPE_MS = 320L

        /** Сколько ждать ответа системы по жесту, мс. */
        private const val GESTURE_TIMEOUT_MS = 3_000L

        private const val TAG = "OverlayGestureService"
    }
}

/** Прямоугольный жест: откуда и куда вести пальцем, в пикселях экрана. */
data class GestureSwipe(
    val fromX: Int,
    val fromY: Int,
    val toX: Int,
    val toY: Int,
)

/**
 * Ведёт в настройки доступности и объясняет «Ограниченные настройки».
 *
 * На Android 13+ приложение, установленное не из магазина, получает
 * серый, невключаемый переключатель Службы доступности: система блокирует
 * её «Ради безопасности — эта настройка сейчас недоступна». Обойти это
 * из кода нельзя, но можно прямо сказать, где разрешить.
 */
fun Context.requestGestureService() {
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        toast(
            "Переключатель серый? «О приложении» → ⋮ → " +
                "«Разрешить ограниченные настройки»",
        )
    }
    runCatching {
        startActivity(
            Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
        )
    }.onFailure { toast("Открой Настройки → Специальные возможности") }
}

/**
 * Системный экран приложения.
 *
 * Именно там на Android 13+ находится пункт ⋮ «Разрешить ограниченные
 * настройки», без которого Службу доступности из APK не включить.
 */
fun Context.openAppDetails() {
    runCatching {
        startActivity(
            Intent(
                Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                Uri.fromParts("package", packageName, null),
            ).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
        )
    }.onFailure { toast("Открой Настройки → Приложения") }
}

package eu.kanade.tachiyomi.ui.reader.loader

import eu.kanade.tachiyomi.data.cache.ChapterCache
import eu.kanade.tachiyomi.data.database.models.toDomainChapter
import eu.kanade.tachiyomi.source.model.Page
import eu.kanade.tachiyomi.source.online.HttpSource
import eu.kanade.tachiyomi.ui.reader.model.ReaderChapter
import eu.kanade.tachiyomi.ui.reader.model.ReaderPage
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.filter
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.runInterruptible
import kotlinx.coroutines.suspendCancellableCoroutine
import logcat.LogPriority
import tachiyomi.core.common.util.lang.launchIO
import tachiyomi.core.common.util.lang.withIOContext
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.util.concurrent.PriorityBlockingQueue
import kotlin.concurrent.atomics.AtomicInt
import kotlin.concurrent.atomics.ExperimentalAtomicApi
import kotlin.concurrent.atomics.incrementAndFetch

/**
 * Loader used to load chapters from an online source.
 */
internal class HttpPageLoader(
    private val chapter: ReaderChapter,
    private val source: HttpSource,
    private val chapterCache: ChapterCache = Injekt.get(),
) : PageLoader() {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    /**
     * A queue used to manage requests one by one while allowing priorities.
     */
    private val queue = PriorityBlockingQueue<PriorityPage>()

    /**
     * Индексы страниц, уже поставленных в очередь для фоновой загрузки.
     * Защищает от дубликатов в [queue], когда страница пере-привязывается
     * (скролл туда-сюда) во время полного префетча главы.
     */
    private val enqueued = java.util.Collections.synchronizedSet(mutableSetOf<Int>())

    init {
        scope.launchIO {
            flow {
                while (true) {
                    emit(runInterruptible { queue.take() })
                }
            }
                .filter { it.page.status == Page.State.Queue }
                .collect {
                    internalLoadPage(
                        page = it.page,
                        force = it.priority == PriorityPage.RETRY,
                    )
                }
        }
    }

    override var isLocal: Boolean = false

    /**
     * Returns the page list for a chapter. It tries to return the page list from the local cache,
     * otherwise fallbacks to network.
     */
    override suspend fun getPages(): List<ReaderPage> {
        val pages = try {
            chapterCache.getPageListFromCache(chapter.chapter.toDomainChapter()!!)
        } catch (e: Throwable) {
            if (e is CancellationException) {
                throw e
            }
            source.getPageList(chapter.chapter)
        }
        return pages.mapIndexed { index, page ->
            // Don't trust sources and use our own indexing
            ReaderPage(index, page.url, page.imageUrl)
        }
    }

    /**
     * Loads a page through the queue. Handles re-enqueueing pages if they were evicted from the cache.
     */
    override suspend fun loadPage(page: ReaderPage) = withIOContext {
        val imageUrl = page.imageUrl

        // Check if the image has been deleted
        if (page.status == Page.State.Ready && imageUrl != null && !chapterCache.isImageInCache(imageUrl)) {
            page.status = Page.State.Queue
        }

        // Automatically retry failed pages when subscribed to this page
        if (page.status is Page.State.Error) {
            page.status = Page.State.Queue
        }

        val queuedPages = mutableListOf<PriorityPage>()
        if (page.status == Page.State.Queue) {
            queuedPages += PriorityPage(page, PriorityPage.DEFAULT).also { queue.offer(it) }
        }
        queuedPages += preloadRemainingPages(page)

        suspendCancellableCoroutine<Nothing> { continuation ->
            continuation.invokeOnCancellation {
                queuedPages.forEach {
                    if (it.page.status == Page.State.Queue) {
                        queue.remove(it)
                        enqueued.remove(it.page.index)
                    }
                }
            }
        }
    }

    /**
     * Retries a page. This method is only called from user interaction on the viewer.
     */
    override fun retryPage(page: ReaderPage) {
        if (page.status is Page.State.Error) {
            page.status = Page.State.Queue
        }
        queue.offer(PriorityPage(page, PriorityPage.RETRY))
    }

    override fun recycle() {
        super.recycle()

        // Списком страниц делимся до отмены scope: дальше этот список уже никто
        // не переживёт вместе с загрузчиком.
        val pagesToSave = chapter.pages?.map { Page(it.index, it.url, it.imageUrl) }

        scope.cancel()
        queue.clear()

        // Cache current page list progress for online chapters to allow a faster reopen.
        // Запись уходит в GlobalScope (top-level launchIO), иначе scope уже отменён.
        pagesToSave?.let { pages ->
            launchIO {
                try {
                    chapterCache.putPageListToCache(chapter.chapter.toDomainChapter()!!, pages)
                } catch (e: CancellationException) {
                    throw e
                } catch (e: Exception) {
                    logcat(LogPriority.WARN, e) { "HttpPageLoader failed to cache page list" }
                }
            }
        }
    }

    /**
     * Полный фоновый префетч оставшихся страниц главы (не только 4 следующих).
     *
     * Каждая прочитанная онлайн-страница укладывается в [ChapterCache] — так
     * книгу можно дочитать офлайн с того места, где остановился, без повторной
     * загрузки. Текущая страница всегда грузится с приоритетом DEFAULT выше
     * фоновых ADJACENT, поэтому чтение остаётся мгновенным, а очередь
     * непрерывно кеширует все оставшиеся страницы.
     *
     * @return список [PriorityPage], добавленных в [queue]
     */
    private fun preloadRemainingPages(currentPage: ReaderPage): List<PriorityPage> {
        val pageIndex = currentPage.index
        val pages = currentPage.chapter.pages ?: return emptyList()
        if (pageIndex >= pages.lastIndex) return emptyList()

        val offered = mutableListOf<PriorityPage>()
        for (i in (pageIndex + 1)..pages.lastIndex) {
            val candidate = pages[i]
            if (candidate.status == Page.State.Queue && enqueued.add(candidate.index)) {
                val priorityPage = PriorityPage(candidate, PriorityPage.ADJACENT)
                queue.offer(priorityPage)
                offered += priorityPage
            }
        }
        return offered
    }

    /**
     * Loads the page, retrieving the image URL and downloading the image if necessary.
     * Downloaded images are stored in the chapter cache.
     *
     * @param page the page whose source image has to be downloaded.
     */
    private suspend fun internalLoadPage(page: ReaderPage, force: Boolean) {
        try {
            if (page.imageUrl.isNullOrEmpty()) {
                page.status = Page.State.LoadPage
                page.imageUrl = source.getImageUrl(page)
            }
            val imageUrl = page.imageUrl!!

            if (force || !chapterCache.isImageInCache(imageUrl)) {
                page.status = Page.State.DownloadImage
                val imageResponse = source.getImage(page)
                chapterCache.putImageToCache(imageUrl, imageResponse)
            }

            page.stream = { chapterCache.getImageFile(imageUrl).inputStream() }
            page.status = Page.State.Ready
        } catch (e: Throwable) {
            page.status = Page.State.Error(e)
            if (e is CancellationException) {
                throw e
            }
        } finally {
            // Страница обработана (успешно или с ошибкой): разрешаем поставить
            // её в очередь снова при следующем пере-привязывании.
            enqueued.remove(page.index)
        }
    }
}

/**
 * Data class used to keep ordering of pages in order to maintain priority.
 */
@OptIn(ExperimentalAtomicApi::class)
private class PriorityPage(
    val page: ReaderPage,
    val priority: Int,
) : Comparable<PriorityPage> {
    companion object {
        private val idGenerator = AtomicInt(0)

        const val RETRY = 2
        const val DEFAULT = 1
        const val ADJACENT = 0
    }

    private val identifier = idGenerator.incrementAndFetch()

    override fun compareTo(other: PriorityPage): Int {
        val p = other.priority.compareTo(priority)
        return if (p != 0) p else identifier.compareTo(other.identifier)
    }
}

