package mihon.data.ocr

import android.graphics.Bitmap
import mihon.domain.ocr.exception.OcrException
import mihon.domain.ocr.model.OcrBoundingBox

internal interface DetOcrEngine {
    suspend fun detectTextRegions(image: Bitmap): List<OcrBoundingBox>

    fun close()
}

internal class UnavailableDetOcrEngine : DetOcrEngine {
    override suspend fun detectTextRegions(image: Bitmap): List<OcrBoundingBox> {
        throw OcrException.DetectionUnavailable()
    }

    override fun close() = Unit
}

/**
 * Детектор текстовых областей на модели PP-OCRv4 (`cyrillic_detector.tflite`).
 *
 * Модель уже входит в пак `cyrillic_ocr` и загружается внутри
 * [CyrillicOcrEngine], поэтому здесь она не открывается второй раз — движок
 * переиспользуется целиком. Владелец движка — репозиторий, так что [close]
 * ничего не закрывает: иначе первый же `closeEngines()` закрыл бы модель
 * дважды.
 */
internal class CyrillicDetOcrEngine(
    private val engineProvider: () -> CyrillicOcrEngine,
) : DetOcrEngine {

    override suspend fun detectTextRegions(image: Bitmap): List<OcrBoundingBox> {
        return try {
            engineProvider().detectRegions(image)
        } catch (e: OcrException) {
            // Модели не установлены или не инициализировались — для вызывающей
            // стороны это то же самое, что «детектора нет».
            throw OcrException.DetectionUnavailable(e)
        }
    }

    /** Жизненным циклом модели управляет владелец [CyrillicOcrEngine]. */
    override fun close() = Unit
}

package mihon.data.ocr

import android.graphics.Bitmap
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.text.Text
import com.google.mlkit.vision.text.TextRecognition
import com.google.mlkit.vision.text.latin.TextRecognizerOptions
import kotlinx.coroutines.suspendCancellableCoroutine
import mihon.domain.ocr.model.OcrBoundingBox
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException

/**
 * Google ML Kit Text Recognition (on-device).
 *
 * Модель вкомпилирована в APK, поэтому движок полностью офлайн и не требует
 * пакета `cyrillic_ocr` или LiteRT. ML Kit отдаёт строки текста вместе с их
 * координатами, благодаря чему используется и как распознаватель, и как
 * детектор областей: [recognizeRegions] возвращает строки с нормализованными
 * рамками, и тап по реплике открывает именно её.
 *
 * В Android SDK нет отдельной bundled-модели ML Kit для кириллицы, поэтому
 * этот движник предназначен прежде всего для латинского текста. Каждая строка
 * проходит только безопасную очистку через [OcrTextCleaner.cleanMlKitLine];
 * координаты строки сохраняются.
 */
internal class MlKitOcrEngine : LineOcrEngine {

    private val recognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS)

    override suspend fun recognizeText(image: Bitmap): String = recognizeCleanedLines(image)
        .joinToString("\n") { it.text }

    override suspend fun recognizeLine(image: Bitmap): String = recognizeCleanedLines(image)
        .joinToString(" ") { it.text }
        .trim()

    /** Строка ML Kit после чистки конвейером кириллического движка. */
    private data class CleanedLine(val text: String, val line: Text.Line)

    /**
     * Строки страницы с нормализованными (0..1) рамками — замена детектору
     * областей. Рамки, которые ML Kit не вернул или которые вырождены, и
     * строки, отсеянные чисткой как мусор, пропускаются.
     */
    suspend fun recognizeRegions(image: Bitmap): List<MlKitRegion> {
        val width = image.width.toFloat()
        val height = image.height.toFloat()
        if (width <= 0f || height <= 0f) return emptyList()

        return recognizeCleanedLines(image).mapNotNull { cleaned ->
            val box = cleaned.line.boundingBox ?: return@mapNotNull null
            val boundingBox = OcrBoundingBox(
                left = (box.left / width).coerceIn(0f, 1f),
                top = (box.top / height).coerceIn(0f, 1f),
                right = (box.right / width).coerceIn(0f, 1f),
                bottom = (box.bottom / height).coerceIn(0f, 1f),
            )
            if (!boundingBox.isValid() || cleaned.text.isBlank()) {
                null
            } else {
                MlKitRegion(boundingBox = boundingBox, text = cleaned.text)
            }
        }
    }

    private suspend fun recognizeCleanedLines(image: Bitmap): List<CleanedLine> =
        recognizeLines(image).mapNotNull { line ->
            val text = OcrTextCleaner.cleanMlKitLine(line.text)
            if (text.isBlank()) null else CleanedLine(text, line)
        }

    private suspend fun recognizeLines(image: Bitmap): List<Text.Line> = suspendCancellableCoroutine { cont ->
        val input = InputImage.fromBitmap(image, 0)
        recognizer.process(input)
            .addOnSuccessListener { result ->
                cont.resume(result.textBlocks.flatMap { it.lines })
            }
            .addOnFailureListener { error ->
                cont.resumeWithException(error)
            }
    }

    override fun close() {
        recognizer.close()
    }
}

internal data class MlKitRegion(
    val boundingBox: OcrBoundingBox,
    val text: String,
)

package mihon.data.ocr

import android.graphics.Bitmap
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import mihon.domain.ocr.model.OcrBoundingBox
import mihon.domain.ocr.model.OcrRegion
import mihon.domain.ocr.model.OcrTextOrientation
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL
import java.util.Base64
import org.json.JSONArray
import org.json.JSONObject

internal class ZenFreeOcrEngine : OcrEngine {
    override suspend fun recognizeText(image: Bitmap): String = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        recognizePage(image).joinToString("\n") { it.text }
    }

    suspend fun recognizePage(image: Bitmap): List<OcrRegion> = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val connection = URL(ENDPOINT).openConnection() as HttpURLConnection
        try {
            val payload = JSONObject().apply {
                put("model", MODEL)
                put("max_tokens", MAX_TOKENS)
                put("stream", false)
                put(
                    "messages",
                    JSONArray().put(
                        JSONObject().apply {
                            put("role", "user")
                            put(
                                "content",
                                JSONArray()
                                    .put(
                                        JSONObject().apply {
                                            put("type", "text")
                                            put("text", OCR_PROMPT)
                                        },
                                    )
                                    .put(
                                        JSONObject().apply {
                                            put("type", "image_url")
                                            put(
                                                "image_url",
                                                JSONObject().apply {
                                                    put("url", "data:image/jpeg;base64,${encodeBitmap(image)}")
                                                },
                                            )
                                        },
                                    ),
                            )
                        },
                    ),
                )
            }
            connection.requestMethod = "POST"
            connection.doOutput = true
            connection.connectTimeout = CONNECT_TIMEOUT_MS
            connection.readTimeout = READ_TIMEOUT_MS
            connection.setRequestProperty("Content-Type", "application/json")
            connection.setRequestProperty("Accept", "application/json")
            connection.outputStream.use { output ->
                output.write(payload.toString().toByteArray(Charsets.UTF_8))
            }

            val status = connection.responseCode
            val response = (if (status in 200..299) connection.inputStream else connection.errorStream)
                ?.bufferedReader()
                ?.use { it.readText() }
                .orEmpty()
            if (status !in 200..299) {
                throw IllegalStateException("OpenCode Zen OCR request failed HTTP $status")
            }

            val message = JSONObject(response)
                .optJSONArray("choices")
                ?.optJSONObject(0)
                ?.optJSONObject("message")
                ?: throw IllegalStateException("OpenCode Zen OCR response has no choices")
            parseZenOcrRegions(extractMessageContent(message))
        } finally {
            connection.disconnect()
        }
    }

    /**
     * Произвольный вопрос о странице той же vision-моделью.
     *
     * Запрос уходит тем же прямым соединением, что и OCR (решение владельца
     * проекта — без прокси-абстракции), но вместо JSON с боксами модель
     * отвечает обычным текстом. Это «глаза» агента-оркестратора: он видит
     * кадр и продолжает свой цикл с web/file-инструментами.
     */
    suspend fun askAboutPage(image: Bitmap, question: String): String? = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val prompt = question.trim()
        if (prompt.isEmpty()) return@withContext null
        val payload = JSONObject().apply {
            put("model", MODEL)
            put("max_tokens", ASK_MAX_TOKENS)
            put("stream", false)
            put(
                "messages",
                JSONArray().put(
                    JSONObject().apply {
                        put("role", "user")
                        put(
                            "content",
                            JSONArray()
                                .put(
                                    JSONObject().apply {
                                        put("type", "text")
                                        put("text", ASK_PROMPT)
                                    },
                                )
                                .put(
                                    JSONObject().apply {
                                        put("type", "image_url")
                                        put(
                                            "image_url",
                                            JSONObject().apply {
                                                put("url", "data:image/jpeg;base64,${encodeBitmap(image)}")
                                            },
                                        )
                                    },
                                ),
                        )
                    },
                ),
            )
        }
        val answer = postAndReadText(payload)
        answer?.trim()?.takeIf { it.isNotEmpty() && !it.contains("FreeTierError") }
    }

    /** POST с готовым payload и чтение строкового ответа. null при сетевой ошибке. */
    private fun postAndReadText(payload: JSONObject): String? {
        val connection = URL(ENDPOINT).openConnection() as HttpURLConnection
        return try {
            connection.requestMethod = "POST"
            connection.doOutput = true
            connection.connectTimeout = CONNECT_TIMEOUT_MS
            connection.readTimeout = READ_TIMEOUT_MS
            connection.setRequestProperty("Content-Type", "application/json")
            connection.setRequestProperty("Accept", "application/json")
            connection.outputStream.use { it.write(payload.toString().toByteArray(Charsets.UTF_8)) }
            val status = connection.responseCode
            val body = (if (status in 200..299) connection.inputStream else connection.errorStream)
                ?.bufferedReader()
                ?.use { it.readText() }
                .orEmpty()
            if (status !in 200..299) {
                // Free tier закрыт для стороннего клиента — это не повод
                // ронять разговор, агент просто продолжит без взгляда.
                null
            } else {
                extractMessageContent(JSONObject(body).optJSONArray("choices")?.optJSONObject(0)
                    ?.optJSONObject("message") ?: JSONObject())
            }
        } catch (e: Exception) {
            null
        } finally {
            connection.disconnect()
        }
    }

    override fun close() = Unit

    private fun extractMessageContent(message: JSONObject): String {
        return when (val content = message.opt("content")) {
            is String -> content
            is JSONArray -> buildString {
                for (index in 0 until content.length()) {
                    val text = content.optJSONObject(index)?.optString("text").orEmpty()
                    if (text.isNotBlank()) append(text)
                }
            }
            else -> ""
        }
    }

    private fun encodeBitmap(bitmap: Bitmap): String {
        val maxSide = maxOf(bitmap.width, bitmap.height)
        val scale = if (maxSide > MAX_IMAGE_SIDE) MAX_IMAGE_SIDE.toFloat() / maxSide else 1f
        val scaled = if (scale < 1f) {
            Bitmap.createScaledBitmap(
                bitmap,
                (bitmap.width * scale).toInt().coerceAtLeast(1),
                (bitmap.height * scale).toInt().coerceAtLeast(1),
                true,
            )
        } else {
            null
        }
        val output = ByteArrayOutputStream()
        try {
            (scaled ?: bitmap).compress(Bitmap.CompressFormat.JPEG, JPEG_QUALITY, output)
        } finally {
            if (scaled != null && !scaled.isRecycled) scaled.recycle()
        }
        return Base64.getEncoder().encodeToString(output.toByteArray())
    }

    companion object {
        const val MODEL = "space-bunny-free"
        private const val ENDPOINT = "https://opencode.ai/zen/v1/chat/completions"
        private const val MAX_IMAGE_SIDE = 1080
        private const val JPEG_QUALITY = 78
        private const val MAX_TOKENS = 4096
        private const val ASK_MAX_TOKENS = 1024
        private const val CONNECT_TIMEOUT_MS = 15_000
        private const val READ_TIMEOUT_MS = 90_000
        private val ASK_PROMPT =
            "You are the eyes of a reading assistant. Look at this page image and answer the question " +
                "about it. Describe only what is actually visible: characters, actions, panel layout, " +
                "art style, and the text you can read. If the question needs context that is not on the " +
                "image, say so plainly instead of inventing it. Answer in the language of the question. " +
                "Be concise, plain text, no JSON and no markdown."
        private val OCR_PROMPT =
            "Transcribe every visible text block in this image. Preserve the original reading order, " +
                "language, spelling, punctuation, and line breaks. Do not translate, explain, or invent text. " +
                "Return only JSON: {\"regions\":[{\"text\":\"...\",\"box\":[left,top,right,bottom]," +
                "\"orientation\":\"horizontal\"}]}. Coordinates are integers from 0 to 1000 relative to the " +
                "full image. Use one region per visible speech bubble or text block. Use [] when no text exists."
    }
}

private val zenFreeJson = Json { ignoreUnknownKeys = true }

@Serializable
private data class ZenOcrResponse(
    val regions: List<ZenOcrRegion> = emptyList(),
    val text: String = "",
)

@Serializable
private data class ZenOcrRegion(
    val text: String = "",
    val box: List<Float> = emptyList(),
    val orientation: String = "horizontal",
)

internal fun parseZenOcrRegions(content: String): List<OcrRegion> {
    if (content.isBlank()) return emptyList()
    val jsonText = content.substringAfter("```json", content).substringBefore("```").trim()
    val objectStart = jsonText.indexOf('{')
    val objectEnd = jsonText.lastIndexOf('}')
    val parsed = if (objectStart >= 0 && objectEnd > objectStart) {
        runCatching {
            zenFreeJson.decodeFromString<ZenOcrResponse>(jsonText.substring(objectStart, objectEnd + 1))
        }.getOrNull()
    } else {
        null
    }
    if (parsed == null) {
        return listOf(
            OcrRegion(
                order = 0,
                text = content.trim(),
                boundingBox = OcrBoundingBox(0f, 0f, 1f, 1f),
                textOrientation = OcrTextOrientation.Horizontal,
            ),
        )
    }

    val regions = parsed.regions.mapIndexedNotNull { index, region ->
        val text = region.text.trim()
        if (text.isBlank() || region.box.size != 4) return@mapIndexedNotNull null
        val divisor = if (region.box.all { it > 1f }) 1000f else 1f
        val left = region.box[0] / divisor
        val top = region.box[1] / divisor
        val right = region.box[2] / divisor
        val bottom = region.box[3] / divisor
        val box = OcrBoundingBox(left, top, right, bottom)
        if (!box.isValid() || left !in 0f..1f || top !in 0f..1f || right !in 0f..1f || bottom !in 0f..1f) {
            return@mapIndexedNotNull null
        }
        OcrRegion(
            order = index,
            text = text,
            boundingBox = box,
            textOrientation = if (region.orientation.equals("vertical", ignoreCase = true)) {
                OcrTextOrientation.Vertical
            } else {
                OcrTextOrientation.Horizontal
            },
        )
    }
    if (regions.isNotEmpty()) return regions
    val fallbackText = parsed.text.trim()
    return if (fallbackText.isBlank()) {
        emptyList()
    } else {
        listOf(
            OcrRegion(
                order = 0,
                text = fallbackText,
                boundingBox = OcrBoundingBox(0f, 0f, 1f, 1f),
                textOrientation = OcrTextOrientation.Horizontal,
            ),
        )
    }
}

package mihon.data.ocr

import android.content.Context
import android.graphics.Bitmap
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.logcat
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL
import java.util.Base64
import org.json.JSONArray
import org.json.JSONObject

/**
 * OCR Engine backed by OpenRouter AI Vision models with strict verbatim transcription.
 */
internal class OpenRouterOcrEngine(
    private val context: Context,
    private val ocrPreferences: OcrPreferences,
) : OcrEngine {

    override suspend fun recognizeText(image: Bitmap): String = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }

        val apiKey = ocrPreferences.openrouterApiKey().get()
        if (apiKey.isBlank()) {
            logcat(LogPriority.WARN) { "OpenRouter API key is empty" }
        }

        val model = ocrPreferences.openrouterModel().get().ifBlank { "google/gemini-2.5-flash" }
        val base64Image = encodeBitmapToBase64(image)

        val jsonBody = JSONObject().apply {
            put("model", model)
            put("temperature", 0.0)
            val messages = JSONArray()
            val userMsg = JSONObject().apply {
                put("role", "user")
                val content = JSONArray()
                content.put(JSONObject().apply {
                    put("type", "text")
                    put("text", "Perform STRICT OPTICAL CHARACTER RECOGNITION (OCR) ONLY. Transcribe the exact text from the image verbatim without translating, explaining, summarizing, or adding any commentary. If no text is visible, return empty string.")
                })
                content.put(JSONObject().apply {
                    put("type", "image_url")
                    put("image_url", JSONObject().apply {
                        put("url", "data:image/jpeg;base64,$base64Image")
                    })
                })
                put("content", content)
            }
            messages.put(userMsg)
            put("messages", messages)
        }

        val endpoint = "https://openrouter.ai/api/v1/chat/completions"
        val connection = (URL(endpoint).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 15_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/json")
            if (apiKey.isNotBlank()) {
                setRequestProperty("Authorization", "Bearer $apiKey")
            }
            setRequestProperty("HTTP-Referer", "https://yomihon.github.io")
            setRequestProperty("X-Title", "Yomihon")
        }

        try {
            connection.outputStream.use { os ->
                os.write(jsonBody.toString().toByteArray(Charsets.UTF_8))
            }

            val statusCode = connection.responseCode
            val responseText = (if (statusCode in 200..299) connection.inputStream else connection.errorStream)
                ?.use { it.readBytes().toString(Charsets.UTF_8) } ?: ""

            if (statusCode !in 200..299) {
                throw Exception("OpenRouter request failed HTTP $statusCode: ${responseText.take(200)}")
            }

            val jsonResponse = JSONObject(responseText)
            val choices = jsonResponse.optJSONArray("choices")
            val extractedText = if (choices != null && choices.length() > 0) {
                choices.getJSONObject(0).optJSONObject("message")?.optString("content", "") ?: ""
            } else ""

            val usage = jsonResponse.optJSONObject("usage")
            val totalTokens = usage?.optLong("total_tokens", 100L) ?: 100L
            ocrPreferences.incrementTokens(totalTokens)

            extractedText.trim()
        } catch (e: Exception) {
            logcat(LogPriority.ERROR, e) { "OpenRouter OCR failed" }
            throw e
        } finally {
            connection.disconnect()
        }
    }

    override fun close() = Unit

    /**
     * Произвольный вопрос о странице. Тот же формат multimodal, что у
     * [recognizeText], но вместо «OCR ONLY» модель получает вопрос — это
     * «глаза» агента-оркестратора. null при любой ошибке: вызывающий код
     * обязан продолжить разговор без взгляда на страницу.
     */
    suspend fun askAboutPage(image: Bitmap, question: String): String? = withContext(Dispatchers.IO) {
        val text = question.trim()
        if (text.isEmpty() || image.isRecycled) return@withContext null
        val apiKey = ocrPreferences.openrouterApiKey().get()
        if (apiKey.isBlank()) return@withContext null
        val model = ocrPreferences.openrouterModel().get().ifBlank { "google/gemini-2.5-flash" }
        val jsonBody = JSONObject().apply {
            put("model", model)
            put("temperature", 0.2)
            put(
                "messages",
                JSONArray().put(
                    JSONObject().apply {
                        put("role", "user")
                        put(
                            "content",
                            JSONArray()
                                .put(
                                    JSONObject().apply {
                                        put(
                                            "type", "text"
                                        )
                                        put(
                                            "text",
                                            "You are the eyes of a reading assistant. Look at this page " +
                                                "image and answer the question about it. Describe only what " +
                                                "is actually visible: characters, actions, panel layout, art " +
                                                "style and readable text. If the answer needs context that " +
                                                "is not on the image, say so instead of inventing it. Answer " +
                                                "in the language of the question, plain text, no JSON.\n\n" +
                                                "QUESTION: $text",
                                        )
                                    },
                                )
                                .put(
                                    JSONObject().apply {
                                        put("type", "image_url")
                                        put(
                                            "image_url",
                                            JSONObject().apply {
                                                put("url", "data:image/jpeg;base64,${encodeBitmapToBase64(image)}")
                                            },
                                        )
                                    },
                                ),
                        )
                    },
                ),
            )
        }
        runCatching {
            val connection = (URL("https://openrouter.ai/api/v1/chat/completions").openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                doOutput = true
                connectTimeout = 15_000
                readTimeout = 60_000
                setRequestProperty("Content-Type", "application/json")
                setRequestProperty("Authorization", "Bearer $apiKey")
                setRequestProperty("HTTP-Referer", "https://yomihon.github.io")
                setRequestProperty("X-Title", "Yomihon")
            }
            try {
                connection.outputStream.use { it.write(jsonBody.toString().toByteArray(Charsets.UTF_8)) }
                val code = connection.responseCode
                val body = (if (code in 200..299) connection.inputStream else connection.errorStream)
                    ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
                if (code !in 200..299) return@runCatching null
                val answer = JSONObject(body).optJSONArray("choices")
                    ?.optJSONObject(0)?.optJSONObject("message")?.optString("content", "")
                answer?.trim()?.takeIf { it.isNotEmpty() }
            } finally {
                connection.disconnect()
            }
        }.getOrNull()
    }

    private companion object {
        /** Длинная сторона страницы перед отправкой в vision-модель. */
        const val MAX_IMAGE_SIDE = 1080
    }

    private fun encodeBitmapToBase64(bitmap: Bitmap): String {
        val stream = ByteArrayOutputStream()
        // Страница уменьшается до 1080 px по длинной стороне и кодируется
        // в JPEG: раньше улетал PNG полного размера (несколько мегабайт в
        // base64 внутри JSON), из-за чего запрос к vision-модели тянулся
        // десятки секунд и стоил дороже. Параметр качества у PNG к тому же
        // игнорировался — формат без потерь. Для чтения реплик 1080 px с
        // качеством 78 — больше, чем достаточно, а payload заметно меньше.
        val maxSide = maxOf(bitmap.width, bitmap.height)
        val scaled = if (maxSide > MAX_IMAGE_SIDE) {
            val factor = MAX_IMAGE_SIDE.toFloat() / maxSide
            Bitmap.createScaledBitmap(
                bitmap,
                (bitmap.width * factor).toInt().coerceAtLeast(1),
                (bitmap.height * factor).toInt().coerceAtLeast(1),
                true,
            )
        } else {
            null
        }
        val source = scaled ?: bitmap
        try {
            source.compress(Bitmap.CompressFormat.JPEG, 78, stream)
        } finally {
            if (scaled != null && !scaled.isRecycled) scaled.recycle()
        }
        val byteArray = stream.toByteArray()
        return Base64.getEncoder().encodeToString(byteArray)
    }
}

package mihon.data.ocr

import android.graphics.Bitmap
import androidx.core.graphics.scale
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.model.OcrBoundingBox
import mihon.domain.ocr.model.OcrRegion
import mihon.domain.ocr.model.OcrTextOrientation
import tachiyomi.core.common.util.system.logcat
import java.io.ByteArrayOutputStream
import java.io.IOException
import java.net.HttpURLConnection
import java.net.URL
import kotlin.random.Random

/**
 * OCR engine backed by Google Lens online OCR.
 * Extracts plain text from text-layout boxes in the protobuf response.
 */
internal class GlensOcrEngine(
    /**
     * BCP-47 язык источника (en, ru, ja, ko, zh…). Раньше был зашит "ja":
     * пользователь не мог читать англ/рус/прочие источники. Прокидывается из
     * OcrPreferences.glensLanguage().
     */
    val clientLanguage: String = DEFAULT_CLIENT_LANGUAGE,
    /** IANA tz региона (необязателен, напр. "Asia/Tokyo", "Europe/Kiev"). */
    val clientRegion: String = DEFAULT_CLIENT_REGION,
) : OcrEngine {
    private val textPostprocessor = TextPostprocessor()

    override suspend fun recognizeText(image: Bitmap): String = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }

        val startTime = System.nanoTime()
        try {
            val preparedImage = prepareImage(image)
            val payload = buildRequestPayload(preparedImage)
            val responseBytes = executeRequest(payload)
            val extractedText = parseResponsePage(responseBytes).text

            val totalTime = (System.nanoTime() - startTime) / 1_000_000
            logcat(LogPriority.INFO) { "OCR(glens) Runtime: recognizeText total time: $totalTime ms" }
            extractedText
        } catch (e: Exception) {
            logcat(LogPriority.ERROR, e) { "OCR (glens) failed" }
            throw e
        }
    }

    internal suspend fun recognizePage(image: Bitmap): GlensPageResult = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }

        val startTime = System.nanoTime()
        try {
            val preparedImage = prepareImage(image)
            val payload = buildRequestPayload(preparedImage)
            val responseBytes = executeRequest(payload)
            val pageResult = parseResponsePage(responseBytes)

            val totalTime = (System.nanoTime() - startTime) / 1_000_000
            logcat(LogPriority.INFO) { "OCR(glens) Runtime: recognizePage total time: $totalTime ms" }
            pageResult
        } catch (e: Exception) {
            logcat(LogPriority.ERROR, e) { "OCR (glens) page recognition failed" }
            throw e
        }
    }

    override fun close() = Unit

    private fun prepareImage(image: Bitmap): PreparedImage {
        val maxDim = maxOf(image.width, image.height)
        val resized = if (maxDim > MAX_IMAGE_DIMENSION) {
            val scaleFactor = MAX_IMAGE_DIMENSION.toFloat() / maxDim.toFloat()
            val targetWidth = (image.width * scaleFactor).toInt().coerceAtLeast(1)
            val targetHeight = (image.height * scaleFactor).toInt().coerceAtLeast(1)
            image.scale(targetWidth, targetHeight, filter = true)
        } else {
            null
        }

        val working = resized ?: image
        return try {
            val encoded = ByteArrayOutputStream()
            // JPEG вместо PNG: страница манги в PNG(100) весит около 3 МБ,
            // и на мобильной сети отправка занимала больше десяти секунд.
            // JPEG(78) даёт примерно 0.3-0.5 МБ при том же качестве
            // распознавания (текст в баллонах — крупный высококонтрастный
            // шрифт) и ускоряет и аплоад, и обработку на стороне Google Lens.
            val success = working.compress(Bitmap.CompressFormat.JPEG, 78, encoded)
            if (!success) {
                throw IOException("Failed to encode image for GLens request")
            }

            PreparedImage(
                bytes = encoded.toByteArray(),
                width = working.width,
                height = working.height,
            )
        } finally {
            resized?.recycle()
        }
    }

    private fun buildRequestPayload(image: PreparedImage): ByteArray {
        val requestId = Random.nextLong()

        return ProtoWriter().apply {
            writeMessage(fieldNumber = SERVER_REQUEST_OBJECTS_REQUEST) { objectsRequest ->
                objectsRequest.writeMessage(fieldNumber = OBJECTS_REQUEST_CONTEXT) { requestContext ->
                    requestContext.writeMessage(fieldNumber = REQUEST_CONTEXT_REQUEST_ID) { requestIdMessage ->
                        requestIdMessage.writeUInt64(fieldNumber = REQUEST_ID_UUID, value = requestId)
                        requestIdMessage.writeInt32(fieldNumber = REQUEST_ID_SEQUENCE_ID, value = 0)
                        requestIdMessage.writeInt32(fieldNumber = REQUEST_ID_IMAGE_SEQUENCE_ID, value = 0)
                        requestIdMessage.writeBytes(fieldNumber = REQUEST_ID_ANALYTICS_ID, value = Random.nextBytes(16))
                    }
                    requestContext.writeMessage(fieldNumber = REQUEST_CONTEXT_CLIENT_CONTEXT) { clientContext ->
                        clientContext.writeInt32(fieldNumber = CLIENT_CONTEXT_PLATFORM, value = PLATFORM_WEB)
                        clientContext.writeInt32(fieldNumber = CLIENT_CONTEXT_SURFACE, value = SURFACE_CHROMIUM)
                        clientContext.writeMessage(fieldNumber = CLIENT_CONTEXT_LOCALE_CONTEXT) { localeContext ->
                            localeContext.writeString(fieldNumber = LOCALE_LANGUAGE, value = clientLanguage)
                            localeContext.writeString(fieldNumber = LOCALE_REGION, value = clientRegion)
                        }
                        clientContext.writeMessage(fieldNumber = CLIENT_CONTEXT_CLIENT_FILTERS) { clientFilters ->
                            clientFilters.writeMessage(fieldNumber = CLIENT_FILTERS_FILTER) { filter ->
                                filter.writeInt32(fieldNumber = FILTER_FILTER_TYPE, value = AUTO_FILTER)
                            }
                        }
                    }
                }

                objectsRequest.writeMessage(fieldNumber = OBJECTS_REQUEST_IMAGE_DATA) { imageData ->
                    imageData.writeMessage(fieldNumber = IMAGE_DATA_PAYLOAD) { payload ->
                        payload.writeBytes(fieldNumber = IMAGE_PAYLOAD_BYTES, value = image.bytes)
                    }
                    imageData.writeMessage(fieldNumber = IMAGE_DATA_METADATA) { metadata ->
                        metadata.writeInt32(fieldNumber = IMAGE_METADATA_WIDTH, value = image.width)
                        metadata.writeInt32(fieldNumber = IMAGE_METADATA_HEIGHT, value = image.height)
                    }
                }
            }
        }.toByteArray()
    }

    private fun executeRequest(payload: ByteArray): ByteArray {
        val connection = (URL(LENS_ENDPOINT).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = CONNECT_TIMEOUT_MS
            readTimeout = READ_TIMEOUT_MS
            setRequestProperty("Content-Type", CONTENT_TYPE_PROTOBUF)
            setRequestProperty("User-Agent", DEFAULT_USER_AGENT)
            setRequestProperty("X-Goog-Api-Key", API_KEY)
            setRequestProperty("Connection", "keep-alive")
            setRequestProperty("Sec-Fetch-Mode", "no-cors")
            setRequestProperty("Sec-Fetch-Dest", "empty")
        }

        return try {
            connection.outputStream.use { output ->
                output.write(payload)
            }

            val statusCode = connection.responseCode
            val responseBytes = (if (statusCode in 200..299) connection.inputStream else connection.errorStream)
                ?.use { input -> input.readBytes() }
                ?: ByteArray(0)

            if (statusCode !in 200..299) {
                val bodyPreview = responseBytes.toString(Charsets.UTF_8).take(256)
                throw IOException("GLens request failed with HTTP $statusCode: $bodyPreview")
            }

            responseBytes
        } finally {
            connection.disconnect()
        }
    }

    private fun parseResponsePage(responseBytes: ByteArray): GlensPageResult {
        val reader = ProtoReader(responseBytes)
        val allLines = mutableListOf<ParsedLine>()

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            if (field == SERVER_RESPONSE_OBJECTS_RESPONSE && wireType == WIRE_TYPE_LENGTH_DELIMITED) {
                allLines += parseObjectsResponse(reader.readBytes())
            } else {
                reader.skipField(wireType)
            }
        }

        // Full-page furigana filter (across all text-layout blocks)
        val verticalLines = allLines.filter { it.isVertical && it.hasJpText }
        val horizontalLines = allLines.filter { !it.isVertical && it.hasJpText }
        val nonJpLines = allLines.filter { !it.hasJpText }

        val filteredVertical = filterRuby(
            verticalLines.sortedByDescending { it.centerX + it.width / 2f },
            isVertical = true,
        )
        val filteredHorizontal = filterRuby(
            horizontalLines.sortedBy { it.centerY },
            isVertical = false,
        )
        val filteredLines = filteredVertical + filteredHorizontal + nonJpLines

        val bubbles = mergeIntoBubbles(filteredLines)
        val regions = bubbles
            .mapIndexedNotNull { index, bubble -> bubble.toRegion(index) }
            .filter { it.text.isNotBlank() }

        return GlensPageResult(
            text = regions.joinToString(separator = " ") { it.text }.trim(),
            regions = regions,
        )
    }

    private fun parseObjectsResponse(objectsBytes: ByteArray): List<ParsedLine> {
        val reader = ProtoReader(objectsBytes)
        val paragraphs = mutableListOf<ParsedLine>()

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            if (field == OBJECTS_RESPONSE_TEXT && wireType == WIRE_TYPE_LENGTH_DELIMITED) {
                paragraphs += parseText(reader.readBytes())
            } else {
                reader.skipField(wireType)
            }
        }

        return paragraphs
    }

    private fun parseText(textBytes: ByteArray): List<ParsedLine> {
        val reader = ProtoReader(textBytes)
        val paragraphs = mutableListOf<ParsedLine>()

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            if (field == TEXT_LAYOUT && wireType == WIRE_TYPE_LENGTH_DELIMITED) {
                paragraphs += parseTextLayout(reader.readBytes())
            } else {
                reader.skipField(wireType)
            }
        }

        return paragraphs
    }

    private fun parseTextLayout(layoutBytes: ByteArray): List<ParsedLine> {
        val reader = ProtoReader(layoutBytes)
        val allLines = mutableListOf<ParsedLine>()

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            if (field == TEXT_LAYOUT_PARAGRAPH && wireType == WIRE_TYPE_LENGTH_DELIMITED) {
                allLines += collectParagraphLines(reader.readBytes())
            } else {
                reader.skipField(wireType)
            }
        }

        return allLines
    }

    /** Parses one paragraph proto, returning its [ParsedLine] objects without filtering. */
    private fun collectParagraphLines(paragraphBytes: ByteArray): List<ParsedLine> {
        val reader = ProtoReader(paragraphBytes)
        val lines = mutableListOf<ParsedLine>()

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            if (field == PARAGRAPH_LINE && wireType == WIRE_TYPE_LENGTH_DELIMITED) {
                val parsedLine = parseLine(reader.readBytes())
                if (parsedLine.text.isNotBlank()) {
                    lines += parsedLine
                }
            } else {
                reader.skipField(wireType)
            }
        }

        return lines
    }

    private fun parseLine(lineBytes: ByteArray): ParsedLine {
        val reader = ProtoReader(lineBytes)
        val words = mutableListOf<ParsedWord>()

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            if (field == LINE_WORD && wireType == WIRE_TYPE_LENGTH_DELIMITED) {
                words += parseWord(reader.readBytes())
            } else {
                reader.skipField(wireType)
            }
        }

        val plainText = words.joinToString("") { it.text }
        val text = words.joinToString(separator = "") { w -> w.text + w.separator }.trim()

        val isVertical = isVerticalLine(words)

        val positioned = words.filter { it.centerX > 0f || it.centerY > 0f }
        var centerX = 0f
        var centerY = 0f
        var width = 0f
        var height = 0f

        if (positioned.isNotEmpty()) {
            val minX = positioned.minOf { it.centerX - it.width / 2f }
            val maxX = positioned.maxOf { it.centerX + it.width / 2f }
            val minY = positioned.minOf { it.centerY - it.height / 2f }
            val maxY = positioned.maxOf { it.centerY + it.height / 2f }
            width = maxX - minX
            height = maxY - minY
            centerX = minX + width / 2f
            centerY = minY + height / 2f
        }

        val sizes = words.mapNotNull { w ->
            val s = if (isVertical) w.width else w.height
            s.takeIf { it > 0f }
        }.sorted()
        val characterSize = if (sizes.isNotEmpty()) sizes[sizes.size / 2] else 0f

        return ParsedLine(
            words = words,
            text = text,
            hasJpText = containsJapanese(plainText),
            hasKanji = containsKanji(plainText),
            isVertical = isVertical,
            centerX = centerX,
            centerY = centerY,
            width = width,
            height = height,
            characterSize = characterSize,
        )
    }

    private fun compute1DIntersection(minA: Float, maxA: Float, minB: Float, maxB: Float): Float {
        val overlapStart = maxOf(minA, minB)
        val overlapEnd = minOf(maxA, maxB)
        return maxOf(0f, overlapEnd - overlapStart)
    }

    private fun horizontalOverlapRatio(boxA: ParsedLine, boxB: ParsedLine): Float {
        val intersect = compute1DIntersection(
            boxA.centerX - boxA.width / 2f,
            boxA.centerX + boxA.width / 2f,
            boxB.centerX - boxB.width / 2f,
            boxB.centerX + boxB.width / 2f,
        )
        val smallestWidth = minOf(boxA.width, boxB.width)
        return if (smallestWidth > 0f) intersect / smallestWidth else 0f
    }

    private fun verticalOverlapRatio(boxA: ParsedLine, boxB: ParsedLine): Float {
        val intersect = compute1DIntersection(
            boxA.centerY - boxA.height / 2f,
            boxA.centerY + boxA.height / 2f,
            boxB.centerY - boxB.height / 2f,
            boxB.centerY + boxB.height / 2f,
        )
        val smallestHeight = minOf(boxA.height, boxB.height)
        return if (smallestHeight > 0f) intersect / smallestHeight else 0f
    }

    private fun filterRuby(lines: List<ParsedLine>, isVertical: Boolean): List<ParsedLine> {
        if (lines.none { it.hasJpText }) return lines

        val results = mutableListOf<ParsedLine>()
        var index = 0

        while (index < lines.size) {
            val current = lines[index]
            val next = lines.getOrNull(index + 1)

            if (next == null || !current.hasJpText || !next.hasJpText || current.hasKanji || !next.hasKanji) {
                results.add(current)
                index++
                continue
            }

            // At this point: current has no kanji and next has kanji.
            // current is the ruby (furigana) candidate; next is the kanji base.
            val ruby = current

            val isValidAlignment = if (isVertical) {
                val distH = ruby.centerX - next.centerX
                val minH = kotlin.math.abs(next.width - ruby.width) / 2f
                val maxH = next.width + (ruby.width / 2f)
                val overlapV = verticalOverlapRatio(ruby, next)
                distH > minH && distH < maxH && overlapV > 0.4f
            } else {
                val distV = next.centerY - ruby.centerY
                val minV = kotlin.math.abs(next.height - ruby.height) / 2f
                val maxV = next.height + (ruby.height / 2f)
                val overlapH = horizontalOverlapRatio(ruby, next)
                distV > minV && distV < maxV && overlapH > 0.4f
            }

            val baseSize = if (isVertical) next.characterSize else next.height
            val rubySize = if (isVertical) ruby.characterSize else ruby.height
            val isRubySized = baseSize > 0f && rubySize < baseSize * 0.85f

            if (isValidAlignment && isRubySized) {
                results.add(next)
                index += 2
            } else {
                results.add(current)
                index++
            }
        }
        return results
    }

    private fun mergeIntoBubbles(lines: List<ParsedLine>): List<ParsedLine> {
        if (lines.isEmpty()) return emptyList()

        val verticalLines = lines
            .filter { it.isVertical }
            .sortedByDescending { it.centerX }

        val horizontalLines = lines
            .filter { !it.isVertical }
            .sortedBy { it.centerY }

        return mergeBubbleGroup(verticalLines, isVertical = true) +
            mergeBubbleGroup(horizontalLines, isVertical = false)
    }

    /** Groups a pre-sorted list of same-orientation lines into bubble clusters. */
    private fun mergeBubbleGroup(lines: List<ParsedLine>, isVertical: Boolean): List<ParsedLine> {
        if (lines.isEmpty()) return emptyList()

        val used = BooleanArray(lines.size)
        val bubbles = mutableListOf<ParsedLine>()

        for (i in lines.indices) {
            if (used[i]) continue

            val cluster = mutableListOf(lines[i])
            used[i] = true

            var expanded = true
            while (expanded) {
                expanded = false
                for (j in lines.indices) {
                    if (used[j]) continue
                    if (cluster.any { isSameBubble(it, lines[j], isVertical) }) {
                        cluster += lines[j]
                        used[j] = true
                        expanded = true
                    }
                }
            }

            bubbles += if (cluster.size == 1) {
                cluster[0]
            } else {
                combineBubbleCluster(cluster, isVertical)
            }
        }

        return bubbles
    }

    private fun isSameBubble(a: ParsedLine, b: ParsedLine, isVertical: Boolean): Boolean {
        // Не склеиваем строки с сильно разным размером глифа: гигантский SFX
        // («ガブッ» во весь кадр) иначе становился «мостом», стягивающим в
        // один регион соседние реплики («ВЛАДЕЛЕЦ МАГАЗИНА…» + «У-у…» + сам
        // SFX с огромной общей рамкой). Размер шрифта внутри одного облачка
        // почти одинаков, у SFX — в разы крупнее.
        if (a.characterSize > 0f && b.characterSize > 0f) {
            val sizeRatio = minOf(a.characterSize, b.characterSize) /
                maxOf(a.characterSize, b.characterSize)
            if (sizeRatio < MERGE_MIN_CHAR_SIZE_RATIO) return false
        }
        return if (isVertical) {
            val vOverlap = verticalOverlapRatio(a, b)
            val hGap = kotlin.math.abs(a.centerX - b.centerX) -
                (a.width + b.width) / 2f
            val maxWidth = maxOf(a.width, b.width)
            vOverlap >= 0.4f && hGap <= maxWidth * 2f
        } else {
            val hOverlap = horizontalOverlapRatio(a, b)
            val vGap = kotlin.math.abs(a.centerY - b.centerY) -
                (a.height + b.height) / 2f
            val maxHeight = maxOf(a.height, b.height)
            hOverlap >= 0.3f && vGap <= maxHeight * 2f
        }
    }

    private fun combineBubbleCluster(cluster: List<ParsedLine>, isVertical: Boolean): ParsedLine {
        val sorted = if (isVertical) {
            cluster.sortedWith(
                compareByDescending<ParsedLine> { it.centerX }
                    .thenBy { it.centerY },
            )
        } else {
            cluster.sortedBy { it.centerY }
        }

        val text = sorted.joinToString("\n") { it.text }

        val minX = sorted.minOf { it.centerX - it.width / 2f }
        val maxX = sorted.maxOf { it.centerX + it.width / 2f }
        val minY = sorted.minOf { it.centerY - it.height / 2f }
        val maxY = sorted.maxOf { it.centerY + it.height / 2f }
        val newWidth = maxX - minX
        val newHeight = maxY - minY
        val newCenterX = minX + newWidth / 2f
        val newCenterY = minY + newHeight / 2f

        val representativeWords = sorted.flatMap { it.words }
        val medianCharSize = sorted.map { it.characterSize }.sorted().let { it[it.size / 2] }

        return ParsedLine(
            words = representativeWords,
            text = text,
            hasJpText = sorted.any { it.hasJpText },
            hasKanji = sorted.any { it.hasKanji },
            isVertical = isVertical,
            centerX = newCenterX,
            centerY = newCenterY,
            width = newWidth,
            height = newHeight,
            characterSize = medianCharSize,
        )
    }

    private fun isVerticalLine(words: List<ParsedWord>): Boolean {
        val positioned = words.filter { it.centerX > 0f || it.centerY > 0f }
        if (positioned.size >= 2) {
            val xRange = positioned.maxOf { it.centerX } - positioned.minOf { it.centerX }
            val yRange = positioned.maxOf { it.centerY } - positioned.minOf { it.centerY }
            return yRange > xRange
        }
        // Fallback: compare median word dimensions.
        val heights = words.mapNotNull { it.height.takeIf { h -> h > 0f } }.sorted()
        val widths = words.mapNotNull { it.width.takeIf { w -> w > 0f } }.sorted()
        if (heights.isEmpty() || widths.isEmpty()) return false
        val medH = heights[heights.size / 2]
        val medW = widths[widths.size / 2]
        return medH > medW
    }

    // Simple heuristic, doesn't need to be perfect due to other filtering restrictions
    private fun containsJapanese(text: String): Boolean = text.any { c ->
        val cp = c.code
        cp in 0x3040..0x30FF || // Hiragana + Katakana
            cp in 0x4E00..0x9FFF || // CJK Unified Ideographs (common kanji)
            cp in 0x3400..0x4DBF || // CJK Extension A
            cp in 0xF900..0xFAFF // CJK Compatibility Ideographs
    }

    private fun containsKanji(text: String): Boolean = text.any { c ->
        val cp = c.code
        cp in 0x4E00..0x9FFF || // CJK Unified Ideographs (common kanji)
            cp in 0x3400..0x4DBF || // CJK Extension A
            cp in 0xF900..0xFAFF // CJK Compatibility Ideographs
    }

    private fun parseWord(wordBytes: ByteArray): ParsedWord {
        val reader = ProtoReader(wordBytes)
        var text = ""
        var separator = ""
        var centerX = 0f
        var centerY = 0f
        var width = 0f
        var height = 0f

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            when (field) {
                WORD_PLAIN_TEXT if wireType == WIRE_TYPE_LENGTH_DELIMITED -> {
                    text = reader.readString()
                }
                WORD_SEPARATOR if wireType == WIRE_TYPE_LENGTH_DELIMITED -> {
                    separator = reader.readString()
                }
                WORD_GEOMETRY if wireType == WIRE_TYPE_LENGTH_DELIMITED -> {
                    val box = parseGeometryBox(reader.readBytes())
                    centerX = box.centerX
                    centerY = box.centerY
                    width = box.width
                    height = box.height
                }
                else -> reader.skipField(wireType)
            }
        }

        return ParsedWord(
            text = text,
            separator = separator,
            centerX = centerX,
            centerY = centerY,
            width = width,
            height = height,
        )
    }

    private data class BoundingBoxData(
        val centerX: Float,
        val centerY: Float,
        val width: Float,
        val height: Float,
    )

    private fun parseGeometryBox(geometryBytes: ByteArray): BoundingBoxData {
        val reader = ProtoReader(geometryBytes)
        var box = BoundingBoxData(0f, 0f, 0f, 0f)

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            if (field == GEOMETRY_BOUNDING_BOX && wireType == WIRE_TYPE_LENGTH_DELIMITED) {
                box = parseBoundingBox(reader.readBytes())
            } else {
                reader.skipField(wireType)
            }
        }

        return box
    }

    private fun parseBoundingBox(bboxBytes: ByteArray): BoundingBoxData {
        val reader = ProtoReader(bboxBytes)
        var centerX = 0f
        var centerY = 0f
        var width = 0f
        var height = 0f

        while (reader.hasRemaining()) {
            val tag = reader.readTag()
            if (tag == 0) break

            val field = tag ushr 3
            val wireType = tag and WIRE_TYPE_MASK
            when (field) {
                BOUNDING_BOX_CENTER_X if wireType == WIRE_TYPE_32BIT -> centerX = reader.readFloat()
                BOUNDING_BOX_CENTER_Y if wireType == WIRE_TYPE_32BIT -> centerY = reader.readFloat()
                BOUNDING_BOX_WIDTH if wireType == WIRE_TYPE_32BIT -> width = reader.readFloat()
                BOUNDING_BOX_HEIGHT if wireType == WIRE_TYPE_32BIT -> height = reader.readFloat()
                else -> reader.skipField(wireType)
            }
        }

        return BoundingBoxData(centerX = centerX, centerY = centerY, width = width, height = height)
    }

    /**
     * Intermediate representation of a parsed word used during furigana filtering.
     * Discarded after [parseLine] assembles the final string.
     * Coords are normalized to [0, 1] domain.
     */
    private data class ParsedWord(
        val text: String,
        val separator: String,
        val centerX: Float,
        val centerY: Float,
        val width: Float,
        val height: Float,
    )

    private data class ParsedLine(
        val words: List<ParsedWord>,
        val text: String,
        val hasJpText: Boolean,
        val hasKanji: Boolean,
        val isVertical: Boolean,
        val centerX: Float,
        val centerY: Float,
        val width: Float,
        val height: Float,
        val characterSize: Float,
    )

    internal data class GlensPageResult(
        val text: String,
        val regions: List<OcrRegion>,
    )

    private fun ParsedLine.toRegion(order: Int): OcrRegion? {
        if (text.isBlank() || width <= 0f || height <= 0f) {
            return null
        }

        val left = (centerX - width / 2f).coerceIn(0f, 1f)
        val top = (centerY - height / 2f).coerceIn(0f, 1f)
        val right = (centerX + width / 2f).coerceIn(0f, 1f)
        val bottom = (centerY + height / 2f).coerceIn(0f, 1f)
        val box = OcrBoundingBox(
            left = left,
            top = top,
            right = right,
            bottom = bottom,
        )

        if (!box.isValid()) {
            return null
        }

        return OcrRegion(
            order = order,
            text = textPostprocessor.postprocess(text),
            boundingBox = box,
            textOrientation = if (isVertical) OcrTextOrientation.Vertical else OcrTextOrientation.Horizontal,
        )
    }

    private data class PreparedImage(
        val bytes: ByteArray,
        val width: Int,
        val height: Int,
    ) {
        override fun equals(other: Any?): Boolean {
            if (this === other) return true
            if (javaClass != other?.javaClass) return false

            other as PreparedImage

            if (width != other.width) return false
            if (height != other.height) return false
            if (!bytes.contentEquals(other.bytes)) return false

            return true
        }

        override fun hashCode(): Int {
            var result = width
            result = 31 * result + height
            result = 31 * result + bytes.contentHashCode()
            return result
        }
    }

