private class ProtoWriter {
    private val output = ByteArrayOutputStream()

    fun writeInt32(fieldNumber: Int, value: Int) {
        writeTag(fieldNumber, wireType = 0)
        writeVarint32(value)
    }

    fun writeUInt64(fieldNumber: Int, value: Long) {
        writeTag(fieldNumber, wireType = 0)
        writeVarint64(value)
    }

    fun writeString(fieldNumber: Int, value: String) {
        writeBytes(fieldNumber, value.toByteArray(Charsets.UTF_8))
    }

    fun writeBytes(fieldNumber: Int, value: ByteArray) {
        writeTag(fieldNumber, wireType = 2)
        writeVarint32(value.size)
        output.write(value)
    }

    fun writeMessage(fieldNumber: Int, block: (ProtoWriter) -> Unit) {
        val nested = ProtoWriter().apply(block).toByteArray()
        writeBytes(fieldNumber, nested)
    }

    fun toByteArray(): ByteArray = output.toByteArray()

    private fun writeTag(fieldNumber: Int, wireType: Int) {
        writeVarint32((fieldNumber shl 3) or wireType)
    }

    private fun writeVarint32(value: Int) {
        var v = value
        while ((v and 0x7F.inv()) != 0) {
            output.write((v and 0x7F) or 0x80)
            v = v ushr 7
        }
        output.write(v and 0x7F)
    }

    private fun writeVarint64(value: Long) {
        var v = value
        while ((v and -0x80L) != 0L) {
            output.write(((v and 0x7F) or 0x80).toInt())
            v = v ushr 7
        }
        output.write((v and 0x7F).toInt())
    }
}

private class ProtoReader(
    private val bytes: ByteArray,
) {
    private var position = 0

    fun hasRemaining(): Boolean = position < bytes.size

    fun readTag(): Int {
        if (!hasRemaining()) return 0
        return readVarint32()
    }

    fun readString(): String = readBytes().toString(Charsets.UTF_8)

    fun readBytes(): ByteArray {
        val length = readVarint32()
        if (length < 0 || position + length > bytes.size) {
            throw IOException("Invalid length-delimited field length: $length")
        }

        val value = bytes.copyOfRange(position, position + length)
        position += length
        return value
    }

    /**
     * Read a 32-bit little-endian IEEE 754 float (protobuf wire type 5).
     * The caller must consume the tag first and verify wireType == [WIRE_TYPE_32BIT].
     */
    fun readFloat(): Float {
        if (position + 4 > bytes.size) {
            throw IOException("Unexpected end of protobuf while reading float")
        }
        val bits = (bytes[position].toInt() and 0xFF) or
            ((bytes[position + 1].toInt() and 0xFF) shl 8) or
            ((bytes[position + 2].toInt() and 0xFF) shl 16) or
            ((bytes[position + 3].toInt() and 0xFF) shl 24)
        position += 4
        return java.lang.Float.intBitsToFloat(bits)
    }

    fun skipField(wireType: Int) {
        when (wireType) {
            0 -> readVarint64()
            1 -> skipBytes(8)
            2 -> {
                val length = readVarint32()
                skipBytes(length)
            }
            5 -> skipBytes(4)
            else -> throw IOException("Unsupported protobuf wire type: $wireType")
        }
    }

    private fun skipBytes(count: Int) {
        if (count < 0 || position + count > bytes.size) {
            throw IOException("Invalid skip length: $count")
        }
        position += count
    }

    private fun readVarint32(): Int {
        var result = 0
        var shift = 0
        while (shift < 32) {
            if (!hasRemaining()) throw IOException("Unexpected end of protobuf while reading varint32")
            val b = bytes[position++].toInt() and 0xFF
            result = result or ((b and 0x7F) shl shift)
            if ((b and 0x80) == 0) return result
            shift += 7
        }

        // Read and discard extra bytes for malformed/int64 varints.
        repeat(5) {
            if (!hasRemaining()) throw IOException("Unexpected end of protobuf while reading varint32 overflow")
            if ((bytes[position++].toInt() and 0x80) == 0) return result
        }
        throw IOException("Malformed varint32")
    }

    private fun readVarint64(): Long {
        var result = 0L
        var shift = 0
        while (shift < 64) {
            if (!hasRemaining()) throw IOException("Unexpected end of protobuf while reading varint64")
            val b = bytes[position++].toLong() and 0xFFL
            result = result or ((b and 0x7FL) shl shift)
            if ((b and 0x80L) == 0L) return result
            shift += 7
        }
        throw IOException("Malformed varint64")
    }
}

package mihon.data.ocr

import android.content.Context
import android.graphics.Bitmap
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.exception.OcrException
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.logcat
import java.io.ByteArrayOutputStream
import java.net.HttpURLConnection
import java.net.URL
import java.util.Base64
import org.json.JSONArray
import org.json.JSONObject

/**
 * OCR Engine backed by Google AI / Gemini Vision API with strict verbatim transcription.
 */
internal class GoogleAiOcrEngine(
    private val context: Context,
    private val ocrPreferences: OcrPreferences,
) : OcrEngine {

    override suspend fun recognizeText(image: Bitmap): String = withContext(Dispatchers.IO) {
        require(!image.isRecycled) { "Input bitmap is recycled" }

        val apiKey = ocrPreferences.googleApiKey().get()
        if (apiKey.isBlank()) {
            throw OcrException.InitializationError(
                IllegalStateException("Google AI API key is empty"),
            )
        }
        val model = ocrPreferences.googleModel().get().ifBlank { "gemini-2.5-flash" }
        val base64Image = encodeBitmapToBase64(image)

        val jsonBody = JSONObject().apply {
            val generationConfig = JSONObject().apply {
                put("temperature", 0.0)
            }
            put("generationConfig", generationConfig)
            val contents = JSONArray()
            val contentItem = JSONObject().apply {
                val parts = JSONArray()
                parts.put(JSONObject().apply {
                    put("text", "Perform STRICT OPTICAL CHARACTER RECOGNITION (OCR) ONLY. Transcribe the exact characters seen in this image verbatim. Do not hallucinate, do not translate, do not add any markdown formatting or commentary.")
                })
                parts.put(JSONObject().apply {
                    put("inline_data", JSONObject().apply {
                        put("mime_type", "image/jpeg")
                        put("data", base64Image)
                    })
                })
                put("parts", parts)
            }
            contents.put(contentItem)
            put("contents", contents)
        }

        val urlString = "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$apiKey"
        val connection = (URL(urlString).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            doOutput = true
            connectTimeout = 15_000
            readTimeout = 60_000
            setRequestProperty("Content-Type", "application/json")
        }

        try {
            connection.outputStream.use { os ->
                os.write(jsonBody.toString().toByteArray(Charsets.UTF_8))
            }

            val statusCode = connection.responseCode
            val responseText = (if (statusCode in 200..299) connection.inputStream else connection.errorStream)
                ?.use { it.readBytes().toString(Charsets.UTF_8) } ?: ""

            if (statusCode !in 200..299) {
                throw Exception("Google AI request failed HTTP $statusCode: ${responseText.take(200)}")
            }

            val jsonResponse = JSONObject(responseText)
            val candidates = jsonResponse.optJSONArray("candidates")
            val extractedText = if (candidates != null && candidates.length() > 0) {
                val candidateParts = candidates.getJSONObject(0)
                    .optJSONObject("content")?.optJSONArray("parts")
                if (candidateParts != null && candidateParts.length() > 0) {
                    candidateParts.getJSONObject(0).optString("text", "")
                } else ""
            } else ""

            val usageMetadata = jsonResponse.optJSONObject("usageMetadata")
            val totalTokens = usageMetadata?.optLong("totalTokenCount", 120L) ?: 120L
            ocrPreferences.incrementTokens(totalTokens)

            extractedText.trim()
        } catch (e: Exception) {
            logcat(LogPriority.ERROR, e) { "Google AI OCR failed" }
            throw e
        } finally {
            connection.disconnect()
        }
    }

    override fun close() = Unit

    /**
     * Произвольный вопрос о странице. Тот же endpoint и та же картинка, что у
     * [recognizeText], но вместо «OCR ONLY» модель получает вопрос — это
     * «глаза» агента-оркестратора. null при любой ошибке: вызывающий код
     * обязан продолжить разговор без взгляда на страницу.
     */
    suspend fun askAboutPage(image: Bitmap, question: String): String? = withContext(Dispatchers.IO) {
        val text = question.trim()
        if (text.isEmpty() || image.isRecycled) return@withContext null
        val apiKey = ocrPreferences.googleApiKey().get()
        if (apiKey.isBlank()) return@withContext null
        val model = ocrPreferences.googleModel().get().ifBlank { "gemini-2.5-flash" }
        val jsonBody = JSONObject().apply {
            put("generationConfig", JSONObject().apply { put("temperature", 0.2) })
            put(
                "contents",
                JSONArray().put(
                    JSONObject().apply {
                        put(
                            "parts",
                            JSONArray()
                                .put(
                                    JSONObject().apply {
                                        put(
                                            "text",
                                            "You are the eyes of a reading assistant. Look at this page " +
                                                "image and answer the question about it. Describe only what " +
                                                "is actually visible: characters, actions, panel layout, art " +
                                                "style and readable text. If the answer needs context that " +
                                                "is not on the image, say so instead of inventing it. Answer " +
                                                "in the language of the question, plain text, no JSON.\n\n" +
                                                "QUESTION: $text",
                                        )
                                    },
                                )
                                .put(
                                    JSONObject().apply {
                                        put(
                                            "inline_data",
                                            JSONObject().apply {
                                                put("mime_type", "image/jpeg")
                                                put("data", encodeBitmapToBase64(image))
                                            },
                                        )
                                    },
                                ),
                        )
                    },
                ),
            )
        }
        runCatching {
            val url = "https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=$apiKey"
            val connection = (URL(url).openConnection() as HttpURLConnection).apply {
                requestMethod = "POST"
                doOutput = true
                connectTimeout = 15_000
                readTimeout = 60_000
                setRequestProperty("Content-Type", "application/json")
            }
            try {
                connection.outputStream.use { it.write(jsonBody.toString().toByteArray(Charsets.UTF_8)) }
                val code = connection.responseCode
                val body = (if (code in 200..299) connection.inputStream else connection.errorStream)
                    ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
                if (code !in 200..299) return@runCatching null
                val parts = JSONObject(body).optJSONArray("candidates")
                    ?.optJSONObject(0)?.optJSONObject("content")?.optJSONArray("parts")
                parts?.optJSONObject(0)?.optString("text", "")?.trim()?.takeIf { it.isNotEmpty() }
            } finally {
                connection.disconnect()
            }
        }.getOrNull()
    }

    private companion object {
        /** Длинная сторона страницы перед отправкой в vision-модель. */
        const val MAX_IMAGE_SIDE = 1080
    }

    private fun encodeBitmapToBase64(bitmap: Bitmap): String {
        val stream = ByteArrayOutputStream()
        // Страница уменьшается до 1500 px по длинной стороне и кодируется
        // в JPEG: раньше улетал PNG полного размера (несколько мегабайт в
        // base64 внутри JSON), из-за чего запрос к vision-модели тянулся
        // десятки секунд и стоил дороже. Параметр качества у PNG к тому же
        // игнорировался — формат без потерь.
        val maxSide = maxOf(bitmap.width, bitmap.height)
        val scaled = if (maxSide > MAX_IMAGE_SIDE) {
            val factor = MAX_IMAGE_SIDE.toFloat() / maxSide
            Bitmap.createScaledBitmap(
                bitmap,
                (bitmap.width * factor).toInt().coerceAtLeast(1),
                (bitmap.height * factor).toInt().coerceAtLeast(1),
                true,
            )
        } else {
            null
        }
        val source = scaled ?: bitmap
        try {
            source.compress(Bitmap.CompressFormat.JPEG, 78, stream)
        } finally {
            if (scaled != null && !scaled.isRecycled) scaled.recycle()
        }
        val byteArray = stream.toByteArray()
        return Base64.getEncoder().encodeToString(byteArray)
    }
}

package mihon.data.ocr

import android.content.Context
import android.graphics.Bitmap
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import mihon.domain.ocr.exception.OcrException
import mihon.domain.ocr.model.OcrBoundingBox
import mihon.domain.ocr.model.OcrRegion
import mihon.domain.ocr.model.OcrTextOrientation
import mihon.domain.ocr.service.OcrPreferences
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import okio.ByteString.Companion.toByteString
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.ByteArrayOutputStream
import java.io.IOException
import java.util.concurrent.TimeUnit

@Serializable
internal data class OwOcrBoundingBox(
    val center_x: Float,
    val center_y: Float,
    val width: Float,
    val height: Float,
    val rotation_z: Float? = null,
)

@Serializable
internal data class OwOcrWord(
    val text: String,
    val bounding_box: OwOcrBoundingBox,
    val separator: String? = null,
)

@Serializable
internal data class OwOcrLine(
    val bounding_box: OwOcrBoundingBox,
    val words: List<OwOcrWord> = emptyList(),
    val text: String? = null,
    val writing_direction: String? = null,
)

@Serializable
internal data class OwOcrParagraph(
    val bounding_box: OwOcrBoundingBox,
    val lines: List<OwOcrLine> = emptyList(),
    val writing_direction: String? = null,
)

@Serializable
internal data class OwOcrResult(
    val paragraphs: List<OwOcrParagraph> = emptyList(),
)

/**
 * OCR engine that communicates with a self-hosted OwOCR WebSocket endpoint.
 * Sends cropped bitmap images and receives recognized text.
 */
internal class OwOcrEngine(context: Context) : OcrEngine {
    private val ocrPreferences = Injekt.get<OcrPreferences>()
    private val client = OkHttpClient.Builder()
        .connectTimeout(15, TimeUnit.SECONDS)
        .readTimeout(60, TimeUnit.SECONDS)
        .writeTimeout(60, TimeUnit.SECONDS)
        .build()

    private val jsonParser = Json { ignoreUnknownKeys = true }

    private suspend fun queryServer(image: Bitmap): String = withContext(Dispatchers.IO) {
        val address = ocrPreferences.owocrAddress().get().trim()
        if (address.isBlank()) {
            throw IOException("OwOCR address is blank. Please configure it in settings.")
        }

        val stream = ByteArrayOutputStream()
        val success = image.compress(Bitmap.CompressFormat.PNG, 100, stream)
        if (!success) {
            throw IOException("Failed to compress bitmap to PNG")
        }
        val imageBytes = stream.toByteArray()

        val request = Request.Builder()
            .url(address)
            .build()

        val deferredResult = CompletableDeferred<String>()
        var webSocket: WebSocket? = null

        val listener = object : WebSocketListener() {
            private var accepted = false

            override fun onOpen(webSocket: WebSocket, response: Response) {
                webSocket.send(imageBytes.toByteString())
            }

            override fun onMessage(webSocket: WebSocket, text: String) {
                // The first message is typically 'True' or 'False' indicating acceptance
                if (!accepted) {
                    if (text == "True") {
                        accepted = true
                        // Wait for the actual OCR result
                    } else {
                        deferredResult.completeExceptionally(IOException("Server rejected the image with: $text"))
                        webSocket.close(1000, "Rejected")
                    }
                } else {
                    deferredResult.complete(text)
                    webSocket.close(1000, "Done")
                }
            }

            override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                deferredResult.completeExceptionally(t)
            }

            override fun onClosing(webSocket: WebSocket, code: Int, reason: String) {
                if (!deferredResult.isCompleted) {
                    deferredResult.completeExceptionally(IOException("Connection closed: $reason ($code)"))
                }
            }
        }

        webSocket = client.newWebSocket(request, listener)

        try {
            deferredResult.await()
        } catch (t: Throwable) {
            webSocket.cancel()
            throw t
        }
    }

    override suspend fun recognizeText(image: Bitmap): String {
        val rawResponse = queryServer(image)
        val trimmed = rawResponse.removePrefix("\uFEFF").trim()

        try {
            val ocrResult = jsonParser.decodeFromString<OwOcrResult>(trimmed)
            val textPostprocessor = TextPostprocessor()
            val combinedText = ocrResult.paragraphs.joinToString("\n\n") { paragraph ->
                paragraph.lines.joinToString("\n") { line ->
                    if (!line.text.isNullOrBlank()) {
                        line.text
                    } else {
                        line.words.joinToString("") { word ->
                            word.text + (word.separator ?: " ")
                        }.trim()
                    }
                }
            }
            return textPostprocessor.postprocess(combinedText)
        } catch (e: Exception) {
            // Fallback to raw response on parse failure
            val textPostprocessor = TextPostprocessor()
            return textPostprocessor.postprocess(rawResponse)
        }
    }

    suspend fun recognizePage(image: Bitmap): List<OcrRegion> {
        val rawResponse = queryServer(image)
        val trimmed = rawResponse.removePrefix("\uFEFF").trim()

        try {
            val ocrResult = jsonParser.decodeFromString<OwOcrResult>(trimmed)
            val textPostprocessor = TextPostprocessor()
            val regions = ocrResult.paragraphs.mapIndexedNotNull { index, paragraph ->
                val textBuilder = StringBuilder()
                paragraph.lines.forEachIndexed { lineIdx, line ->
                    if (lineIdx > 0) textBuilder.append("\n")
                    if (!line.text.isNullOrBlank()) {
                        textBuilder.append(line.text)
                    } else {
                        line.words.forEach { word ->
                            textBuilder.append(word.text)
                            textBuilder.append(word.separator ?: " ")
                        }
                    }
                }
                val paragraphText = textBuilder.toString().trim()
                if (paragraphText.isBlank()) return@mapIndexedNotNull null

                val bbox = paragraph.bounding_box
                val left = (bbox.center_x - bbox.width / 2f).coerceIn(0f, 1f)
                val top = (bbox.center_y - bbox.height / 2f).coerceIn(0f, 1f)
                val right = (bbox.center_x + bbox.width / 2f).coerceIn(0f, 1f)
                val bottom = (bbox.center_y + bbox.height / 2f).coerceIn(0f, 1f)

                val boundingBox = OcrBoundingBox(left = left, top = top, right = right, bottom = bottom)
                if (!boundingBox.isValid()) return@mapIndexedNotNull null

                val isVertical = paragraph.writing_direction == "TOP_TO_BOTTOM" ||
                    paragraph.lines.any { it.writing_direction == "TOP_TO_BOTTOM" }

                val orientation = if (isVertical) OcrTextOrientation.Vertical else OcrTextOrientation.Horizontal

                OcrRegion(
                    order = index,
                    text = textPostprocessor.postprocess(paragraphText),
                    boundingBox = boundingBox,
                    textOrientation = orientation,
                )
            }
            return regions
        } catch (e: Exception) {
            throw OcrException.DetectionUnavailable(
                IOException("OwOCR server response does not contain coordinates or is not in JSON format", e),
            )
        }
    }

    override fun close() {
        // OkHttpClient resources are automatically pooled and closed, no-op
    }
}

package mihon.data.ocr

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder
import org.json.JSONArray

/**
 * Service providing instant translation for manga OCR text.
 * Supports Google Translate, DeepL, and LLM translation gateways.
 */
object MangaTranslatorService {

    /** Переводчик может расставить пробелы внутри @@@ — учитываем это. */
    private val SEPARATOR_REGEX = Regex("""\s*@\s*@\s*@\s*""")

    /**
     * Переводит СПИСОК реплик одним запросом.
     *
     * Раньше авточтение переводило по одной реплике на HTTP-запрос: на
     * странице с 15 бабблами это 15 последовательных обращений между
     * озвучками. Здесь строки склеиваются разделителем, который переводчик
     * не трогает, и режутся обратно; при несовпадении числа строк —
     * безопасный откат на построчный перевод.
     */
    suspend fun translateAll(
        texts: List<String>,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): List<String> = withContext(Dispatchers.IO) {
        if (texts.isEmpty()) return@withContext emptyList()
        if (texts.size == 1) return@withContext listOf(translate(texts[0], targetLang, sourceLang))

        // Разделитель из символов, которые переводчик оставляет как есть.
        val separator = "\n@@@\n"
        val joined = texts.joinToString(separator)

        // У endpoint есть лимит на длину query — режем на порции.
        if (joined.length > 1500) {
            val half = texts.size / 2
            return@withContext translateAll(texts.take(half), targetLang, sourceLang) +
                translateAll(texts.drop(half), targetLang, sourceLang)
        }

        val translated = translate(joined, targetLang, sourceLang)
        val parts = translated.split(SEPARATOR_REGEX).map { it.trim() }
        if (parts.size == texts.size) {
            parts.mapIndexed { index, part -> part.ifBlank { texts[index] } }
        } else {
            logcat(LogPriority.INFO) { "Batch translate mismatch, falling back to per-line" }
            texts.map { translate(it, targetLang, sourceLang) }
        }
    }

    /**
     * Translates input text into target language (default: Russian "ru").
     */
    suspend fun translate(
        text: String,
        targetLang: String = "ru",
        sourceLang: String = "auto",
    ): String = withContext(Dispatchers.IO) {
        if (text.isBlank()) return@withContext ""

        try {
            // Instant Google Free Translate API
            val encodedText = URLEncoder.encode(text, "UTF-8")
            val urlString = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=$sourceLang&tl=$targetLang&dt=t&q=$encodedText"

            val connection = (URL(urlString).openConnection() as HttpURLConnection).apply {
                requestMethod = "GET"
                connectTimeout = 8_000
                readTimeout = 15_000
                setRequestProperty("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64)")
            }

            val responseText = connection.inputStream.use { it.readBytes().toString(Charsets.UTF_8) }
            val jsonArray = JSONArray(responseText)
            val sentences = jsonArray.optJSONArray(0)

            val translatedBuilder = StringBuilder()
            if (sentences != null) {
                for (i in 0 until sentences.length()) {
                    val sentence = sentences.optJSONArray(i)
                    if (sentence != null) {
                        translatedBuilder.append(sentence.optString(0, ""))
                    }
                }
            }

            connection.disconnect()
            val result = translatedBuilder.toString().trim()
            if (result.isNotBlank()) result else text
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "Manga translation failed for: $text" }
            text
        }
    }
}

