package mihon.data.ocr

import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

internal class OcrEngineLocks {
    private val cyrillicMutex = Mutex()
    private val mlKitMutex = Mutex()
    private val legacyMutex = Mutex()
    private val fastMutex = Mutex()
    private val glensMutex = Mutex()
    private val owOcrMutex = Mutex()
    private val openRouterMutex = Mutex()
    private val googleAiMutex = Mutex()
    private val zenFreeMutex = Mutex()
    private val detectionMutex = Mutex()

    suspend fun <T> withTextEngineLock(
        type: OcrRepositoryImpl.EngineType,
        block: suspend () -> T,
    ): T {
        return mutexFor(type).withLock {
            block()
        }
    }

    suspend fun <T> withDetectionLock(block: suspend () -> T): T {
        return detectionMutex.withLock {
            block()
        }
    }

    suspend fun <T> withAllLocks(block: suspend () -> T): T {
        return cyrillicMutex.withLock {
            mlKitMutex.withLock {
                legacyMutex.withLock {
                    fastMutex.withLock {
                        glensMutex.withLock {
                            owOcrMutex.withLock {
                                openRouterMutex.withLock {
                                    googleAiMutex.withLock {
                                        zenFreeMutex.withLock {
                                            detectionMutex.withLock {
                                                block()
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private fun mutexFor(type: OcrRepositoryImpl.EngineType): Mutex {
        return when (type) {
            OcrRepositoryImpl.EngineType.CYRILLIC -> cyrillicMutex
            OcrRepositoryImpl.EngineType.MLKIT -> mlKitMutex
            OcrRepositoryImpl.EngineType.LEGACY -> legacyMutex
            OcrRepositoryImpl.EngineType.FAST -> fastMutex
            OcrRepositoryImpl.EngineType.GLENS -> glensMutex
            OcrRepositoryImpl.EngineType.OWOCR -> owOcrMutex
            OcrRepositoryImpl.EngineType.OPENROUTER -> openRouterMutex
            OcrRepositoryImpl.EngineType.GOOGLE -> googleAiMutex
            OcrRepositoryImpl.EngineType.ZEN_FREE -> zenFreeMutex
        }
    }
}

package mihon.data.ocr

import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

/**
 * Очередь задач сканирования с приоритетами и ОТМЕНОЙ по месту.
 *
 * Раньше задача выполнялась в воркере очереди: отмена вызова (стоп
 * авточтения) лишь бросала await у подписчика, а само распознавание
 * докручивалось до конца — пользователь видел «Processing OCR…» после
 * стопа. Теперь каждая задача идёт в отдельном Job, и отмена подписчика
 * снимает задачу из очереди или гасит выполняющийся Job.
 */
internal class PrioritizedTaskQueue(
    private val scope: CoroutineScope,
    private val onIdle: () -> Unit = {},
) {
    enum class Priority {
        HIGH,
        NORMAL,
    }

    private class Holder {
        @Volatile
        var job: Job? = null

        @Volatile
        var cancelled: Boolean = false
    }

    private class Item(val holder: Holder, val task: suspend () -> Unit)

    private val mutex = Mutex()
    private val highPriorityTasks = ArrayDeque<Item>()
    private val normalPriorityTasks = ArrayDeque<Item>()

    private var activeTasks = 0
    private var workerJob: Job? = null

    suspend fun <T> submit(
        priority: Priority,
        block: suspend () -> T,
    ): T {
        val result = CompletableDeferred<T>()
        val holder = Holder()
        val item = Item(holder) {
            if (!holder.cancelled) {
                try {
                    result.complete(block())
                } catch (e: Throwable) {
                    if (!result.isCompleted) result.completeExceptionally(e)
                }
            }
        }

        mutex.withLock {
            when (priority) {
                Priority.HIGH -> highPriorityTasks.addLast(item)
                Priority.NORMAL -> normalPriorityTasks.addLast(item)
            }
            if (workerJob?.isActive != true) {
                workerJob = scope.launch { processQueue() }
            }
        }

        try {
            return result.await()
        } finally {
            // Стоп подписчика = стоп задачи: снимаем из очереди или гасим Job.
            holder.cancelled = true
            mutex.withLock {
                highPriorityTasks.remove(item)
                normalPriorityTasks.remove(item)
            }
            holder.job?.cancel()
        }
    }

    suspend fun isIdle(): Boolean {
        return mutex.withLock {
            activeTasks == 0 && highPriorityTasks.isEmpty() && normalPriorityTasks.isEmpty()
        }
    }

    private suspend fun processQueue() {
        while (true) {
            val item = mutex.withLock {
                val nextTask = highPriorityTasks.removeFirstOrNull()
                    ?: normalPriorityTasks.removeFirstOrNull()

                if (nextTask == null) {
                    workerJob = null
                    null
                } else {
                    activeTasks++
                    nextTask
                }
            } ?: break

            val job = scope.launch { item.task() }
            item.holder.job = job
            job.join()
            val becameIdle = mutex.withLock {
                activeTasks--
                activeTasks == 0 && highPriorityTasks.isEmpty() && normalPriorityTasks.isEmpty()
            }
            if (becameIdle) {
                onIdle()
            }
        }
    }
}

package mihon.data.ocr

import android.content.Context
import android.os.Environment
import java.io.File

/**
 * Resolves local OCR/vision model files installed OUTSIDE of the APK.
 *
 * The APK ships without any bundled models to stay lightweight: only online
 * engines work out of the box. Local models are optional and are loaded from
 * external storage when present.
 *
 * Search order for a model file (first match wins):
 * 1. App-scoped external dir (no permissions needed, filled by the in-app downloader):
 *    Android/data/app.yomihon/files/ocr_models/<flat name>
 * 2. Same dir with the asset-style sub-path: .../ocr_models/<sub/path>
 * 3. Legacy manual folders (best effort, may be unreadable on Android 11+):
 *    /sdcard/Yomihon/OCR/<flat name> and /sdcard/Download/Yomihon/OCR/<flat name>
 */
object OcrModelFiles {

    const val MODELS_DIR = "ocr_models"

    /** Maps asset-style paths to flat file names used in external folders and model packages. */
    private val flatNames = mapOf(
        "cyrillic_ocr/detector.tflite" to "cyrillic_detector.tflite",
        "cyrillic_ocr/recognizer_v3.tflite" to "cyrillic_recognizer_v3.tflite",
        "cyrillic_ocr/recognizer_v5.tflite" to "cyrillic_recognizer_v5.tflite",
        "cyrillic_ocr/dict_v3.txt" to "cyrillic_dict_v3.txt",
        "cyrillic_ocr/dict_v5.txt" to "cyrillic_dict_v5.txt",
        "ocr/encoder.tflite" to "encoder.tflite",
        "ocr/decoder.tflite" to "decoder.tflite",
        "ocr/embeddings.bin" to "embeddings.bin",
        "ocr_fast/encoder.tflite" to "encoder_fast.tflite",
        "ocr_fast/decoder.tflite" to "decoder_fast.tflite",
        "panel_detector/model.tflite" to "panel_detector.tflite",
    )

    /**
     * Returns an absolute readable file path for the given asset-style model path,
     * or null when the model is not installed externally.
     */
    fun resolve(context: Context, assetPath: String): String? {
        val flat = flatNames[assetPath] ?: File(assetPath).name

        val candidates = buildList {
            context.getExternalFilesDir(null)?.let { base ->
                add(File(File(base, MODELS_DIR), flat))
                add(File(File(base, MODELS_DIR), assetPath))
            }
            runCatching {
                val sdcard = Environment.getExternalStorageDirectory()
                add(File(File(sdcard, "Yomihon/OCR"), flat))
                add(
                    File(
                        File(
                            Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),
                            "Yomihon/OCR",
                        ),
                        flat,
                    ),
                )
            }
        }

        return candidates.firstOrNull { it.isFile && it.canRead() && it.length() > 0 }?.absolutePath
    }

    /** True when every given asset-style path resolves to an installed external file. */
    fun allInstalled(context: Context, assetPaths: List<String>): Boolean {
        return assetPaths.all { resolve(context, it) != null }
    }

    /** Deletes externally installed files for the given asset-style paths (app dir only). */
    fun delete(context: Context, assetPaths: List<String>) {
        val base = context.getExternalFilesDir(null) ?: return
        val dir = File(base, MODELS_DIR)
        assetPaths.forEach { assetPath ->
            val flat = flatNames[assetPath] ?: File(assetPath).name
            File(dir, flat).delete()
            File(dir, assetPath).delete()
        }
    }
}

package mihon.data.ocr

import io.kotest.matchers.collections.shouldContainExactly
import io.kotest.matchers.shouldBe
import mihon.domain.ocr.model.OcrModel
import mihon.domain.ocr.service.ScanRegion
import org.junit.jupiter.api.Test

/**
 * Реестр OCR-плагинов и пресеты типа контента.
 *
 * Обе сущности — чистые данные, поэтому проверяются без Android и без
 * загрузки моделей. Значения BALANCED зафиксированы как актуальные умолчания
 * движка: пользователь, не выбиравший пресет, получает поведение v1.9.76
 * (фильтр водяных знаков по доле чернил, более высокие пороги уверенности).
 */
class OcrPluginsTest {

    @Test
    fun `balanced preset repeats the engine defaults`() {
        val balanced = OcrTuning.preset(OcrContentType.BALANCED)
        balanced.detectorThreshold shouldBe 0.20f
        balanced.minComponentArea shouldBe 24
        balanced.maxTextBoxes shouldBe 96
        balanced.tilingMinTextBoxes shouldBe 8
        balanced.mergeOverlapYFactor shouldBe 0.55f
        balanced.mergeGapXFactor shouldBe 0.55f
        balanced.splitMinWidthPx shouldBe 32
        balanced.wordGapFactor shouldBe 1.7f
        balanced.minWordGapPx shouldBe 5
        balanced.contrastRetryConfidence shouldBe 0.90f
        balanced.verifierSkipConfidence shouldBe 0.82f
        balanced.minAcceptConfidence shouldBe 0.32f
        balanced.shortTextMinConfidence shouldBe 0.18f
        balanced.minCoverage shouldBe 0.12f
        balanced.minCropInkRatio shouldBe 0.03f
        balanced.contrastSkipInkThreshold shouldBe 0.02f
        balanced.verifierCyrillicBonus shouldBe 0.20f
        balanced.wholeLineBoundaryBonus shouldBe 0.08f
        balanced.rescueMaxLines shouldBe 6
        balanced.readingOrder shouldBe "rtl"
        balanced.scanRegion shouldBe ScanRegion.FULL_PAGE
    }

    @Test
    fun `single profile repeats the engine defaults`() {
        // Пресетов типа контента больше нет, поэтому тайлинг, фильтры чернил и
        // пороги одинаковы для всех книг — и проверяются на DEFAULT.
        OcrTuning.preset(OcrContentType.BALANCED).tilingMinTextBoxes shouldBe
            OcrTuning.DEFAULT.tilingMinTextBoxes
        OcrTuning.preset(OcrContentType.BALANCED).verifierSkipConfidence shouldBe
            OcrTuning.DEFAULT.verifierSkipConfidence
        OcrTuning.preset(OcrContentType.BALANCED).minCropInkRatio shouldBe
            OcrTuning.DEFAULT.minCropInkRatio
        OcrTuning.preset(OcrContentType.BALANCED).minComponentArea shouldBe
            OcrTuning.DEFAULT.minComponentArea
    }

    @Test
    fun `overrides replace only the fields the user filled in`() {
        val base = OcrTuning.preset(OcrContentType.BALANCED)
        val tuned = OcrTuningOverrides(detectorThreshold = 0.31f, rescueMaxLines = 3).applyTo(base)
        tuned.detectorThreshold shouldBe 0.31f
        tuned.rescueMaxLines shouldBe 3
        // Остальные поля не тронуты.
        tuned.minComponentArea shouldBe base.minComponentArea
        tuned.wordGapFactor shouldBe base.wordGapFactor
        tuned.minAcceptConfidence shouldBe base.minAcceptConfidence
    }

    @Test
    fun `out-of-range overrides are clamped instead of breaking the detector`() {
        val base = OcrTuning.DEFAULT
        val tuned = OcrTuningOverrides(
            detectorThreshold = 9f,
            minComponentArea = -5,
            maxTextBoxes = 0,
            wordGapFactor = 99f,
            minCoverage = 3f,
            rescueMaxLines = -1,
        ).applyTo(base)
        tuned.detectorThreshold shouldBe 0.99f
        tuned.minComponentArea shouldBe 1
        tuned.maxTextBoxes shouldBe 1
        tuned.wordGapFactor shouldBe 6.0f
        tuned.minCoverage shouldBe 0.9f
        tuned.rescueMaxLines shouldBe 0
    }

    @Test
    fun `empty overrides keep the preset untouched`() {
        val base = OcrTuning.preset(OcrContentType.BALANCED)
        OcrTuningOverrides().isEmpty shouldBe true
        OcrTuningOverrides().applyTo(base) shouldBe base
    }

    @Test
    fun `region profile composes preset and overrides`() {
        val profile = OcrRegionProfile(
            contentType = OcrContentType.BALANCED,
            scanRegion = ScanRegion.BOTTOM_HALF,
            overrides = OcrTuningOverrides(minAcceptConfidence = 0.4f),
        )
        val tuning = profile.tuning()
        tuning.scanRegion shouldBe ScanRegion.BOTTOM_HALF
        tuning.minAcceptConfidence shouldBe 0.4f
        // Не переопределённое поле осталось прежним.
        tuning.wordGapFactor shouldBe OcrTuning.DEFAULT.wordGapFactor
    }

    @Test
    fun `unknown content type falls back to balanced`() {
        // Прежние значения пресетов у пользователей остаются в настройках:
        // они обязаны разбираться и сводиться к единственному профилю.
        listOf("manhwa", "комикс", "manga", "manhua", "comic")
            .forEach { OcrContentType.fromId(it) shouldBe OcrContentType.BALANCED }
        OcrContentType.fromId(null) shouldBe OcrContentType.BALANCED
        OcrContentType.fromId("") shouldBe OcrContentType.BALANCED
    }

    @Test
    fun `every selectable plugin has a unique id and engine type`() {
        OcrPlugins.ALL.map { it.id }.distinct().size shouldBe OcrPlugins.ALL.size
        OcrPlugins.ALL.map { it.engineType }.distinct().size shouldBe OcrPlugins.ALL.size
        OcrPlugins.ALL.forEach { plugin ->
            OcrPlugins.byId(plugin.id) shouldBe plugin
            OcrPlugins.byEngineType(plugin.engineType) shouldBe plugin
            OcrPlugins.byModel(plugin.model) shouldBe plugin
        }
    }

    @Test
    fun `legacy engine selections migrate to the cyrillic plugin`() {
        OcrPlugins.byModel(OcrModel.LEGACY) shouldBe OcrPlugins.CYRILLIC
        OcrPlugins.byModel(OcrModel.FAST) shouldBe OcrPlugins.CYRILLIC
        OcrPlugins.byModel(OcrModel.TESSERACT) shouldBe OcrPlugins.CYRILLIC
        OcrPlugins.LEGACY_ALIASES.map { it.second }.toSet() shouldContainExactly setOf(OcrPlugins.CYRILLIC.id)
    }

    @Test
    fun `availability follows the declared requirements`() {
        val offlineOnly = OcrPlugins.available(
            networkAvailable = false,
            modelsInstalled = true,
            litertAvailable = true,
        )
        // Офлайн-движки с выполненными требованиями: PP-OCR (пак + LiteRT)
        // и ML Kit (вкомпилирован, требований нет).
        offlineOnly shouldContainExactly listOf(OcrPlugins.CYRILLIC, OcrPlugins.MLKIT)

        // ML Kit не требует ни сети, ни пакета моделей, поэтому доступен всегда.
        val nothing = OcrPlugins.available(
            networkAvailable = false,
            modelsInstalled = false,
            litertAvailable = false,
        )
        nothing shouldContainExactly listOf(OcrPlugins.MLKIT)

        val withKeys = OcrPlugins.available(
            networkAvailable = true,
            modelsInstalled = true,
            litertAvailable = true,
            hasApiKey = { true },
            hasServerAddress = { true },
        )
        withKeys.size shouldBe OcrPlugins.ALL.size
    }

    @Test
    fun `fallback chain keeps the semantics of the old presets`() {
        val primary = OcrPlugins.CYRILLIC

        OcrPlugins.fallbackChain(primary, "single", networkAvailable = true) shouldBe emptyList()

        // offline: остаётся только второй локальный движок (ML Kit).
        OcrPlugins.fallbackChain(primary, "offline", networkAvailable = true)
            .map { it.id } shouldContainExactly listOf("mlkit")

        OcrPlugins.fallbackChain(primary, "online", networkAvailable = true).map { it.id } shouldContainExactly
            listOf("google_lens", "zen_free", "google_ai", "openrouter", "owocr")

        // auto без сети не пробует онлайн-движки вовсе: локальные по приоритету.
        OcrPlugins.fallbackChain(OcrPlugins.GLENS, "auto", networkAvailable = false).map { it.id } shouldContainExactly
            listOf("cyrillic_ppocr", "mlkit")

        // auto с сетью: сначала онлайн по приоритету, потом локальный.
        OcrPlugins.fallbackChain(OcrPlugins.GLENS, "auto", networkAvailable = true).map { it.id } shouldContainExactly
            listOf("zen_free", "google_ai", "openrouter", "owocr", "cyrillic_ppocr", "mlkit")

        // Неизвестный пресет читается как auto: при отсутствии сети первичный
        // Cyrillic исключён, остаётся ML Kit.
        OcrPlugins.fallbackChain(primary, "что-то-новое", networkAvailable = false)
            .map { it.id } shouldContainExactly listOf("mlkit")
    }

    @Test
    fun `region-capable plugins expose their capability`() {
        OcrPlugins.ALL.filter { it.supportsRegions }.map { it.id } shouldContainExactly
            listOf(OcrPlugins.CYRILLIC.id, OcrPlugins.MLKIT.id, OcrPlugins.ZEN_FREE.id)
    }

    @Test
    fun `space bunny free parses ordered regions and coordinates`() {
        val regions = parseZenOcrRegions(
            """{"regions":[{"text":"Первая","box":[100,200,900,260],"orientation":"horizontal"},{"text":"Вторая","box":[0.1,0.3,0.8,0.4],"orientation":"vertical"}]}""",
        )

        regions.map { it.text } shouldContainExactly listOf("Первая", "Вторая")
        regions.map { it.order } shouldContainExactly listOf(0, 1)
        regions[0].boundingBox shouldBe mihon.domain.ocr.model.OcrBoundingBox(0.1f, 0.2f, 0.9f, 0.26f)
        regions[1].boundingBox shouldBe mihon.domain.ocr.model.OcrBoundingBox(0.1f, 0.3f, 0.8f, 0.4f)
        regions[1].textOrientation shouldBe mihon.domain.ocr.model.OcrTextOrientation.Vertical
        ZenFreeOcrEngine.MODEL shouldBe "space-bunny-free"
    }

    @Test
    fun `space bunny free keeps plain text and drops invalid regions`() {
        val plain = parseZenOcrRegions("Просто видимая реплика")
        plain.single().text shouldBe "Просто видимая реплика"
        plain.single().boundingBox shouldBe mihon.domain.ocr.model.OcrBoundingBox(0f, 0f, 1f, 1f)

        val filtered = parseZenOcrResultsWithInvalidRegion()
        filtered.map { it.text } shouldContainExactly listOf("Правильная")
    }

    private fun parseZenOcrResultsWithInvalidRegion() = parseZenOcrRegions(
        """{"regions":[{"text":"Неверная","box":[900,200,100,260]},{"text":"Правильная","box":[100,200,900,260]}]}""",
    )

    @Test
    fun `online flags match the fallback pools`() {
        OcrPlugins.ALL.filter { it.online }.map { it.id } shouldContainExactly
            listOf("google_lens", "zen_free", "google_ai", "openrouter", "owocr")
        OcrPlugins.ALL.filterNot { it.online }.map { it.id } shouldContainExactly
            listOf("cyrillic_ppocr", "mlkit")
    }

    @Test
    fun `keyless online plugins are the only ones the runtime chain may try`() {
        val withoutKeys = OcrPlugins.available(
            networkAvailable = true,
            modelsInstalled = true,
            litertAvailable = true,
        )
        withoutKeys.filter { it.online }.map { it.id } shouldContainExactly
            listOf("google_lens", "zen_free")

        val withGoogleKey = OcrPlugins.available(
            networkAvailable = true,
            modelsInstalled = true,
            litertAvailable = true,
            hasApiKey = { it == OcrPlugins.GOOGLE_AI },
        )
        withGoogleKey.filter { it.online }.map { it.id } shouldContainExactly
            listOf("google_lens", "zen_free", "google_ai")
    }
}

package mihon.data.ocr

import io.kotest.matchers.shouldBe
import org.junit.jupiter.api.Test

/**
 * Разбор кропа на строки по проекции строк.
 *
 * Проверяется ровно то, из-за чего появился разбор: детектор склеивает в один
 * бокс не только строку, но и колонку манхвы из пяти строк, и такой кроп
 * сжимается распознавателем в 320×48. При этом одиночная строка (обычный
 * случай) разбираться не должна — лишний проход там ничего не даёт, а ложное
 * разбиение разрезает глифы пополам.
 *
 * Геометрия тестов соответствует порогу движка: межстрочный зазор больше
 * `lineSplitMaxGapFactor` (0.45 высоты строки) — строки разные; зазор меньше —
 * это интервал внутри строки, и полосы обязаны слиться.
 */
class OcrLineBandsTest {

    /** Проекция строк: по [bands] подряд идущих строк с чернилами. */
    private fun profile(height: Int, vararg bands: IntRange): FloatArray {
        val ink = FloatArray(height)
        for (band in bands) {
            for (row in band) ink[row] = 0.4f
        }
        return ink
    }

    private fun bands(
        ink: FloatArray,
        minBands: Int = 2,
    ) = ocrLineBands(
        rowInk = ink,
        minInkRatio = 0.02f,
        maxGapFactor = 0.45f,
        minBandHeight = 4,
        minBands = minBands,
    )

    @Test
    fun `single line is never split`() {
        bands(profile(40, 8..24)) shouldBe emptyList()
    }

    @Test
    fun `single line touching the edges is never split`() {
        // Текст, обрезанный рамкой баллона: полоса от края до края.
        bands(profile(30, 0..29)) shouldBe emptyList()
    }

    @Test
    fun `column of five lines splits into five bands`() {
        // Высота строки 17, зазор 12 — зазор больше 0.45 высоты, строки разные.
        val found = bands(profile(140, 2..18, 31..47, 60..76, 89..105, 118..134))
        found.size shouldBe 5
        found.first() shouldBe 2..18
        found.last() shouldBe 118..134
    }

    @Test
    fun `close lines merge and stay whole`() {
        // Зазор в одну-две строки — это интервал внутри строки (диакритика,
        // висячие элементы букв). Полосы обязаны слиться, иначе глифы режутся.
        bands(profile(80, 10..30, 32..52, 54..74)) shouldBe emptyList()
    }

    @Test
    fun `two lines are returned but the engine needs three`() {
        val ink = profile(60, 4..24, 36..56)
        // Чистая функция честно отдаёт найденное...
        bands(ink).size shouldBe 2
        // ...а движок режет колонки только от трёх строк: подпись из двух
        // строк дёшево прочитать целиком.
        bands(ink, minBands = 3) shouldBe emptyList()
    }

    @Test
    fun `too short profile yields nothing`() {
        bands(profile(1, 0..0)) shouldBe emptyList()
    }

    @Test
    fun `blank profile yields nothing`() {
        bands(profile(50)) shouldBe emptyList()
    }

    @Test
    fun `faint noise below threshold is not a line`() {
        // Водяной знак оставляет меньше 2% чернил в строке: резать нечего.
        bands(FloatArray(60) { 0.01f }) shouldBe emptyList()
    }

    @Test
    fun `lines thinner than the minimum height are dropped`() {
        // Три полосы, но средняя — ореол рамки: остаётся две, и разбор отменяется.
        bands(profile(60, 4..24, 28..29, 36..56)) shouldBe emptyList()
    }

    @Test
    fun `a faint line does not disappear between strong lines`() {
        // Реплика читателя: на кропе из трёх мелких блоков средний блок из двух
        // слов даёт меньше чернил в строке, чем minInkRatio, и раньше выпадал
        // из разбора целиком — текст блока терялся. Теперь промежуток с
        // чернилами втягивается в полосу, и ни одна строка не пропадает.
        val ink = profile(120, 4..20, 52..68, 100..116)
        // Средняя «строка» — 40..48, чернил ниже порога, но строка не пустая.
        for (row in 40..48) ink[row] = 0.005f
        val found = bands(ink, minBands = 3)
        found.size shouldBe 3
        // Полоса доходит до последней строки с чернилами перед второй полосой.
        found[0].first shouldBe 4
        found[0].last shouldBe 48
        // Сильные полосы не изменились.
        found[1] shouldBe 52..68
        found[2] shouldBe 100..116
    }

    @Test
    fun `band edges reach the outermost faint ink`() {
        // Слабые чернила сверху и снизу относятся к первой и последней полосам.
        val ink = profile(100, 10..26, 40..56, 70..86)
        for (row in 0..3) ink[row] = 0.004f
        for (row in 92..95) ink[row] = 0.004f
        val found = bands(ink, minBands = 3)
        found.first().first shouldBe 0
        found.last().last shouldBe 95
    }

    @Test
    fun `blank gaps between strong lines stay gaps`() {
        // Пустой промежуток не должен раздуваться: полосы остаются узкими,
        // иначе соседние строки склеились бы в один кроп.
        val found = bands(profile(140, 2..18, 31..47, 60..76, 89..105, 118..134), minBands = 3)
        found.size shouldBe 5
        found shouldBe listOf(2..18, 31..47, 60..76, 89..105, 118..134)
    }
}

package mihon.data.ocr

import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.async
import kotlinx.coroutines.test.advanceUntilIdle
import kotlinx.coroutines.test.runTest
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class PrioritizedTaskQueueTest {

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun highPriorityTaskRunsBeforeQueuedNormalTask() = runTest {
        val events = mutableListOf<String>()
        val holdFirstTask = CompletableDeferred<Unit>()
        val queue = PrioritizedTaskQueue(backgroundScope)

        val first = async {
            queue.submit(PrioritizedTaskQueue.Priority.NORMAL) {
                events += "normal-1-start"
                holdFirstTask.await()
                events += "normal-1-end"
            }
        }
        advanceUntilIdle()

        val second = async {
            queue.submit(PrioritizedTaskQueue.Priority.NORMAL) {
                events += "normal-2"
            }
        }
        val highPriority = async {
            queue.submit(PrioritizedTaskQueue.Priority.HIGH) {
                events += "high"
            }
        }

        holdFirstTask.complete(Unit)

        first.await()
        highPriority.await()
        second.await()

        assertEquals(
            listOf("normal-1-start", "normal-1-end", "high", "normal-2"),
            events,
        )
    }

    @OptIn(ExperimentalCoroutinesApi::class)
    @Test
    fun highPriorityTaskRunsBeforeLaterPageScanChunks() = runTest {
        val events = mutableListOf<String>()
        val holdFirstChunk = CompletableDeferred<Unit>()
        val queue = PrioritizedTaskQueue(backgroundScope)

        val pageScan = async {
            queue.submit(PrioritizedTaskQueue.Priority.NORMAL) {
                events += "region-1-start"
                holdFirstChunk.await()
                events += "region-1-end"
            }

            queue.submit(PrioritizedTaskQueue.Priority.NORMAL) {
                events += "region-2"
            }
        }

        advanceUntilIdle()

        val recognizeText = async {
            queue.submit(PrioritizedTaskQueue.Priority.HIGH) {
                events += "recognize-text"
            }
        }

        holdFirstChunk.complete(Unit)

        pageScan.await()
        recognizeText.await()

        assertTrue(events.indexOf("recognize-text") < events.indexOf("region-2"))
    }
}

package mihon.data.ocr

import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.test.runTest
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class OcrEngineLocksTest {

    @Test
    fun differentTextEnginesCanRunInParallel() = runTest {
        val locks = OcrEngineLocks()
        val started = CompletableDeferred<Unit>()
        val release = CompletableDeferred<Unit>()
        val secondEntered = CompletableDeferred<Unit>()

        val first = async {
            locks.withTextEngineLock(OcrRepositoryImpl.EngineType.LEGACY) {
                started.complete(Unit)
                release.await()
            }
        }

        started.await()

        val second = async {
            locks.withTextEngineLock(OcrRepositoryImpl.EngineType.FAST) {
                secondEntered.complete(Unit)
            }
        }

        secondEntered.await()
        assertTrue(second.isCompleted)

        release.complete(Unit)
        awaitAll(first, second)
    }

    @Test
    fun sameTextEngineStillRunsSequentially() = runTest {
        val locks = OcrEngineLocks()
        val started = CompletableDeferred<Unit>()
        val release = CompletableDeferred<Unit>()
        val secondEntered = CompletableDeferred<Unit>()

        val first = async {
            locks.withTextEngineLock(OcrRepositoryImpl.EngineType.GLENS) {
                started.complete(Unit)
                release.await()
            }
        }

        started.await()

        val second = async {
            locks.withTextEngineLock(OcrRepositoryImpl.EngineType.GLENS) {
                secondEntered.complete(Unit)
            }
        }

        testScheduler.runCurrent()
        assertFalse(secondEntered.isCompleted)
        assertFalse(second.isCompleted)

        release.complete(Unit)
        awaitAll(first, second)
        assertTrue(secondEntered.isCompleted)
    }

    @Test
    fun withAllLocksWaitsForBusyEngineLocks() = runTest {
        val locks = OcrEngineLocks()
        val started = CompletableDeferred<Unit>()
        val release = CompletableDeferred<Unit>()
        val cleanupOrder = mutableListOf<String>()

        val activeWork = async {
            locks.withTextEngineLock(OcrRepositoryImpl.EngineType.FAST) {
                cleanupOrder += "work-start"
                started.complete(Unit)
                release.await()
                cleanupOrder += "work-end"
            }
        }

        started.await()

        val cleanup = async {
            locks.withAllLocks {
                cleanupOrder += "cleanup"
            }
        }

        testScheduler.runCurrent()
        assertFalse(cleanup.isCompleted)

        release.complete(Unit)
        awaitAll(activeWork, cleanup)
        assertEquals(listOf("work-start", "work-end", "cleanup"), cleanupOrder)
    }
}

