package mihon.data.ocr

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow

/**
 * Живые стадии сканирования/распознавания для индикации в читалке.
 *
 * Пользователь жаловался, что между тапом «OCR» и появлением текста нет
 * никакой индикации. Шина даёт UI честную стадию (и заметку: сколько боксов,
 * сколько символов, сколько срабатываний словарей), а позже послужит
 * источником истории сканирования.
 */
object OcrStageBus {

    enum class Stage { IDLE, DETECTING, RECOGNIZING, DONE, FAILED }

    data class Event(
        val stage: Stage,
        val note: String = "",
        val wordDictHits: Int = 0,
        val punctFixes: Int = 0,
        val splitFixes: Int = 0,
    )

    private val _event = MutableStateFlow(Event(Stage.IDLE))
    val event: StateFlow<Event> = _event

    fun post(stage: Stage, note: String = "") {
        val event = Event(
            stage = stage,
            note = note,
            wordDictHits = OcrTextCleanerStats.wordDictHits,
            punctFixes = OcrTextCleanerStats.punctFixes,
            splitFixes = OcrTextCleanerStats.splitFixes,
        )
        _event.value = event
        // Финал прохода сразу уходит в журнал сканирования (экран истории).
        if (stage == Stage.DONE || stage == Stage.FAILED) {
            OcrHistoryStore.addScan(
                ok = stage == Stage.DONE,
                detail = note,
                wordDictHits = event.wordDictHits,
                punctFixes = event.punctFixes,
                splitFixes = event.splitFixes,
            )
        }
    }
}

package mihon.data.ocr

import android.content.Context

/**
 * Публичная проверка доступности OCR-плагинов для UI.
 *
 * Экраны настроек живут в модуле `app`, а `OcrModelFiles` и
 * `CyrillicOcrEngine` — `internal` в модуле `data`. Чтобы UI не тянул внутренности
 * движка и не дублировал список файлов пакета моделей, проверка собирается
 * здесь и отдаётся уже готовым множеством id.
 */
object OcrPluginAvailability {

    /**
     * Id плагинов, которые можно использовать прямо сейчас.
     *
     * @param networkAvailable есть ли интернет;
     * @param hasApiKey есть ли ключ у плагина (OpenRouter / Google AI);
     * @param hasServerAddress задан ли адрес своего сервера (OwOCR).
     */
    fun availableIds(
        context: Context,
        networkAvailable: Boolean,
        hasApiKey: (OcrPluginDescriptor) -> Boolean = { false },
        hasServerAddress: (OcrPluginDescriptor) -> Boolean = { false },
    ): Set<String> {
        val litertAvailable = runCatching {
            com.google.ai.edge.litert.Environment.create().close()
        }.isSuccess
        val modelsInstalled = OcrModelFiles.allInstalled(
            context,
            listOf(
                CyrillicOcrEngine.DETECTOR_PATH,
                CyrillicOcrEngine.PRIMARY_PATH,
                CyrillicOcrEngine.PRIMARY_DICT_PATH,
            ),
        )
        return OcrPlugins.available(
            networkAvailable = networkAvailable,
            modelsInstalled = modelsInstalled,
            litertAvailable = litertAvailable,
            hasApiKey = hasApiKey,
            hasServerAddress = hasServerAddress,
        ).map { it.id }.toSet()
    }

    /** Причина недоступности одним текстом — для подзаголовка в настройках. */
    fun missingRequirement(
        plugin: OcrPluginDescriptor,
        availableIds: Set<String>,
    ): OcrPluginRequirement? {
        if (plugin.id in availableIds) return null
        return plugin.requirements.firstOrNull()
    }
}

package mihon.data.ocr

import io.kotest.matchers.floats.shouldBeGreaterThan
import io.kotest.matchers.floats.shouldBeLessThan
import io.kotest.matchers.shouldBe
import org.junit.jupiter.api.Test

/**
 * CTC-метрики декодера: нормализованная вероятность blank и штраф за
 * выпавшие буквы. Это чистые функции, поэтому проверяются без Android/TFLite.
 */
class CtcScoringTest {

    private fun synthetic(rows: List<Pair<Float, Float>>): FloatArray {
        // Класс 0 — blank, класс 1 — буква.
        val values = FloatArray(rows.size * 2)
        rows.forEachIndexed { index, (blank, letter) ->
            values[index * 2] = blank
            values[index * 2 + 1] = letter
        }
        return values
    }

    @Test
    fun `blank probability is a normalized value between zero and one`() {
        val probability = CtcScoring.softmax(synthetic(listOf(10f to 0f)), 0, 2)[0]
        probability shouldBeGreaterThan 0.99f
        probability shouldBeLessThan 1.0001f
    }

    @Test
    fun `raw logits are no longer mistaken for confidence`() {
        // Логит 8.0 раньше считался «уверенностью 8.0» и проходил любой порог.
        val probability = CtcScoring.softmax(synthetic(listOf(0f to 8f)), 0, 2)[1]
        probability shouldBeGreaterThan 0.99f
        probability shouldBeLessThan 1.0001f
    }

    @Test
    fun `blanks between letters are counted as dropped characters`() {
        // «А» + два blank + «Б»: два пропуска внутри распознанной подстроки.
        val decode = CtcDecode("АБ", 0.9f, emitted = 2, blankSteps = 2, steps = 4)
        CtcScoring.innerBlankCoverage(decode.blankSteps, decode.emitted, decode.steps) shouldBe 0.5f
    }

    @Test
    fun `clean text keeps its confidence`() {
        CtcScoring.coveragePenalty(0.9f, 0.05f, 0.12f) shouldBe 0.9f
        CtcScoring.coveragePenalty(0.9f, 0.12f, 0.12f) shouldBe 0.9f
    }

    @Test
    fun `dropped letters lower the confidence`() {
        CtcScoring.coveragePenalty(0.9f, 0.56f, 0.12f) shouldBeLessThan 0.75f
